_logger = logging.getLogger(__name__)

class ProductTemplate(models.Model):

    _inherit = 'product.template'

    vendor_id = fields.Many2one(
        'res.partner',
        string="Vendor"
    )

    vendor_fingerprint = fields.Char(
        index=True,
        copy=False
    )

    vendor_import_job_id = fields.Many2one(
        'vendor.import.job',
        string='Vendor Import Job',
        index=True,
        ondelete='set null'
    )
    

    vendor_stock_qty = fields.Integer()

    is_vendor_purged = fields.Boolean(
        default=False
    )

    vendor_family_id = fields.Char(
        string="Vendor Family ID",
        copy=False,
        readonly=True,
        index=True,
    )


    # =============================================
    # AUTO ASSIGN VENDOR DURING CREATE
    # =============================================

    @api.model
    def create(self, vals):

        user = self.env.user

        # Vendor user creating manually from UI
        if (
            user.has_group(
                'gift_product_configurator.group_product_vendor'
            )
            and not vals.get('vendor_id')
        ):

            vals['vendor_id'] = user.partner_id.id

        return super().create(vals)

    # ==========================================
    # PROTECT OTHER VENDOR PRODUCTS
    # ==========================================

    def write(self, vals):

        user = self.env.user

        if user.has_group(
            'gift_product_configurator.group_product_vendor'
        ):

            for product in self:

                if (
                    product.vendor_id
                    and
                    product.vendor_id != user.partner_id
                ):

                    raise AccessError(
                        "You can only edit your own products."
                    )

        return super().write(vals)

    # ==========================================
    # PROTECT DELETE
    # ==========================================

    def unlink(self):

        user = self.env.user

        if user.has_group(
            'gift_product_configurator.group_product_vendor'
        ):

            for product in self:

                if (
                    product.vendor_id
                    and
                    product.vendor_id != user.partner_id
                ):

                    raise AccessError(
                        "You can only delete your own products."
                    )

        return super().unlink()
    

