    #============================= MAIN FLOW (process steps) =====================

    def process_import(self):

        _logger.warning(f"PROCESS START → Job {self.id}")

        try:

            self._process_step()

        except Exception as e:
            _logger.error(f"PROCESS FAILED → {str(e)}")
            self.state = "failed"


    #=============Safe commit======================================================
    def _safe_commit_progress(self):

        try:

            self.flush_recordset()

        except Exception as flush_error:

            _logger.warning(
                f"FLUSH FAILED → {flush_error}"
            )

        try:

            self.env.cr.commit()

        except Exception as commit_error:

            _logger.warning(
                f"COMMIT FAILED → {commit_error}"
            )


    #========vendor completion email notification==========
    def send_completion_email(self, failed=False, error_message=None):

        self.ensure_one()

        _logger.warning(
            f"[EMAIL] START → job={self.id}"
        )

        # =============================================
        # VALIDATE VENDOR EMAIL
        # =============================================

        if not self.partner_id:

            _logger.error(
                f"[EMAIL] FAILED → NO PARTNER | job={self.id}"
            )

            return False

        if not self.partner_id.email:

            _logger.error(
                f"[EMAIL] FAILED → NO VENDOR EMAIL "
                f"| vendor={self.partner_id.id}"
            )

            return False

        # ============================================
        # DETECT ENVIRONMENT
        # ============================================

        base_url = self.env[
            'ir.config_parameter'
        ].sudo().get_param('web.base.url', '')

        is_staging = (
            'staging' in (base_url or '').lower()
        )

        _logger.warning(
            f"[EMAIL] ENVIRONMENT → "
            f"{'STAGING' if is_staging else 'PRODUCTION'}"
        )

        # ============================================
        # STAGING SKIP
        # ============================================

        if is_staging:

            _logger.warning(
                f"[EMAIL] SKIPPED → STAGING ENVIRONMENT "
                f"| vendor={self.partner_id.email}"
            )

            return False

        # ============================================
        # FIND SMTP SERVER
        # ============================================

        mail_server = self.env[
            'ir.mail_server'
        ].sudo().search([
            ('active', '=', True)
        ], limit=1)

        if not mail_server:

            _logger.error(
                "[EMAIL] FAILED → "
                "NO ACTIVE OUTGOING MAIL SERVER"
            )

            return False

        _logger.warning(
            f"[EMAIL] SMTP SERVER → "
            f"{mail_server.name}"
        )

        # ============================================
        # SUBJECT
        # ============================================

        if failed:

            subject = (
                f"Import Failed - {self.name}"
            )

            status_text = "Failed"

            error_html = f"""
                <br/><br/>
                <b>Error:</b><br/>
                {error_message or 'Unknown processing error'}
            """

        else:

            subject = (
                f"Import Completed - {self.name}"
            )

            status_text = "Completed"

            error_html = ""

        # ============================================
        # EMAIL BODY
        # ============================================

        body = f"""
            <div>
                <p>
                    Hello {self.partner_id.name},
                </p>

                <p>
                    Your vendor import job has finished processing.
                </p>

                <table border="1" cellpadding="6" cellspacing="0">

                    <tr>
                        <td><b>Job</b></td>
                        <td>{self.name}</td>
                    </tr>

                    <tr>
                        <td><b>Source</b></td>
                        <td>{self.source_type}</td>
                    </tr>

                    <tr>
                        <td><b>Status</b></td>
                        <td>{status_text}</td>
                    </tr>

                    <tr>
                        <td><b>Date</b></td>
                        <td>{self.create_date}</td>
                    </tr>

                </table>

                {error_html}

                <br/><br/>

                Regards
            </div>
        """

        # ============================================
        # CREATE MAIL
        # ============================================

        try:

            mail_values = {

                'subject': subject,

                'body_html': body,

                'email_to': self.partner_id.email,

                'email_from': mail_server.smtp_user or self.env.user.email,

                'auto_delete': False,
            }

            _logger.warning(
                f"[EMAIL] CREATING MAIL → "
                f"{self.partner_id.email}"
            )

            mail = self.env[
                'mail.mail'
            ].sudo().create(mail_values)

            _logger.warning(
                f"[EMAIL] MAIL CREATED → "
                f"mail_id={mail.id}"
            )

        except Exception as create_error:

            _logger.exception(
                f"[EMAIL] CREATE FAILED → "
                f"{str(create_error)}"
            )

            return False

        # ============================================
        # SEND
        # ============================================

        try:

            _logger.warning(
                f"[EMAIL] SENDING → mail_id={mail.id}"
            )

            mail.sudo().send()

            self.env.cr.commit()

            _logger.warning(
                f"[EMAIL] SUCCESS → "
                f"{self.partner_id.email}"
            )

            self.completion_email_sent = True

            self.env.cr.commit()

            return True

        except Exception as send_error:

            _logger.exception(
                f"[EMAIL] SEND FAILED → "
                f"{str(send_error)}"
            )

            try:

                mail.write({
                    'state': 'exception'
                })

                self.env.cr.commit()

            except Exception:
                pass

            return False
    
    #========vendor failed notification==============
    def _send_failed_processing_email(

        self,

        error_message=None
     ):

        self.ensure_one()

        try:

            # =====================================
            # FAILURE CONTEXT
            # =====================================

            stage = (

                self.last_known_state

                or

                self.state

                or

                "unknown"
            )

            retry_count = (

                self.stage_retry_count

                or

                0
            )

            full_error = f"""

            Stage:
            {stage}

            Retries:
            {retry_count}

            Error:
            {error_message or 'Unknown processing failure'}
            """

            _logger.warning(

                f"[FAILED EMAIL] "

                f"job={self.id} "

                f"stage={stage} "

                f"retry={retry_count}"
            )

            return self.send_completion_email(

                failed=True,

                error_message=full_error
            )

        except Exception as e:

            _logger.exception(

                f"[FAILED EMAIL ERROR] "

                f"{str(e)}"
            )

            return False

    #============Processing Jobs===================================================
    def _process_step(self):

        import json
        import re

        self.ensure_one()

        # =================================================
        # SAFETY
        # =================================================

        if self.pdf_file and self.excel_file:

            _logger.error(
                "[PROCESS STEP] BOTH PDF AND EXCEL PROVIDED"
            )

            self.state = "failed"

            self._safe_commit_progress()

            return


        _logger.warning(
            f"[PROCESS STEP] → state={self.state}"
        )


        # =================================================
        # DONE
        # =================================================

        if self.state == 'done':

            _logger.warning(
                f"JOB {self.id} ALREADY DONE ✅"
            )

            return

        # =================================================
        # REVIEW RECOVERY
        # =================================================

        if self.state == 'review':

            _logger.warning(

                f"[REVIEW RECOVERY] "

                f"retry={self.stage_retry_count}/10 "

                f"last_state={self.last_known_state}"
            )

            # =============================================
            # HARD FAILURE LIMIT
            # =============================================

            if self.stage_retry_count >= 5:

                _logger.error(

                    f"[JOB FAILED PERMANENTLY] "

                    f"job={self.id}"
                )

                self.state = 'failed'

                self.failed_at = fields.Datetime.now()

                self._safe_commit_progress()

                return

            # =============================================
            # RESTORE LAST KNOWN STATE
            # =============================================

            if self.last_known_state:

                self.state = self.last_known_state

                _logger.warning(
                    "[REVIEW RECOVERY] "
                    f"RESTORED STATE → {self.state} "
                    f"| JOB={self.id}"
                )

                self._safe_commit_progress()

                # IMPORTANT:
                # Do NOT return here.
                #
                # Continue through _process_step() so the
                # restored state is actually processed during
                # this same cron invocation.
                #
                # Example:
                #
                # review
                #   ↓
                # azure_review
                #   ↓
                # Azure/OpenAI interception
                #
                # This prevents the job from repeatedly
                # bouncing between review and azure_review.

            else:

                self.state = 'failed'

                self.last_error = (
                    "Review recovery failed: "
                    "no last known state available."
                )

                self.failed_at = fields.Datetime.now()

                self._safe_commit_progress()

                return


        # =================================================
        # URL FLOW
        # =================================================
        

        if self.data_url:

            _logger.warning(
                "FLOW → URL"
            )


            # =============================================
            # START
            # =============================================

            if self.state == 'draft':

                _logger.warning(
                    "[URL FLOW] START"
                )

                self.stage_retry_count = 0

                self.last_known_state = 'url_scraping'
                self.state = 'url_scraping'

                self._safe_commit_progress()

                return


            # =============================================
            # SCRAPE
            # =============================================

            if self.state == 'url_scraping':

                # =========================================
                # RECOVERY
                # =========================================

                if self.url_blocks_json:

                    _logger.warning(

                        "[URL RECOVERY] "

                        "USING SAVED BLOCKS"
                    )

                    self.stage_retry_count = 0

                    self.last_known_state = 'url_scraping'
                    self.state = 'url_scraping'

                    self._safe_commit_progress()

                    return


                _logger.warning(

                    f"[URL SCRAPE] "

                    f"SENDING TO APIFY "

                    f"| {self.data_url}"
                )


                previous_extract = bool(
                    self.extracted_text
                )


                result = self.parse_url()


                # =========================================
                # APIFY STILL PROCESSING
                # =========================================

                if result is True:

                    _logger.warning(

                        "[APIFY STATUS] "

                        "WAITING FOR RESPONSE"
                    )

                    return

                # =========================================
                # APIFY RESPONSE READY
                # =========================================

                _logger.warning(
                    "[APIFY STATUS] RESPONSE RECEIVED"
                )


                if (

                    self.extracted_text

                    and

                    not previous_extract

                ):

                    _logger.warning(
                        "URL EXTRACTION SUCCESS → url_ai"
                    )
                    self.stage_retry_count = 0

                    self.last_known_state = 'url_ai'
                    self.state = 'url_ai'

                    self._safe_commit_progress()

                    return


                # =========================================
                # FAILED
                # =========================================

                if self.state == 'failed':

                    _logger.warning(
                        "[URL SCRAPE FAILED]"
                    )

                    self._safe_commit_progress()

                    return


                _logger.warning(
                    "[URL SCRAPE] NO DATA EXTRACTED"
                )

                self.state = 'failed'

                self._safe_commit_progress()

                return


            # =============================================
            # AI
            # =============================================

            if self.state == 'url_ai':

                previous_batch = (
                    self.url_batch_index or 0
                )


                _logger.warning(

                    f"[URL AI START] "

                    f"batch={previous_batch}"
                )


                try:

                    self.send_to_openai_url()

                except Exception as e:

                    _logger.exception(

                        f"URL AI FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'url_ai'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return


                new_batch = (
                    self.url_batch_index or 0
                )


                _logger.warning(

                    f"[URL AI CHECK] "

                    f"{previous_batch} -> {new_batch}"
                )


                # =========================================
                # PROGRESS DETECTED
                # =========================================

                if new_batch > previous_batch:

                    _logger.warning(
                        "[URL AI] PROGRESS SAVED"
                    )

                elif self.state != 'url_creating':

                    _logger.warning(
                        "[URL AI] NO PROGRESS DETECTED"
                    )

                    self.state = 'failed'


                self._safe_commit_progress()

                return


            # =============================================
            # CREATE
            # =============================================

            if self.state == 'url_creating':

                if not self.ai_response:

                    self.state = 'failed'

                    _logger.warning(
                        "URL CREATE FAILED → NO AI RESPONSE"
                    )


                    self._safe_commit_progress()

                    return


                previous_index = (
                    self.last_processed_product_index or 0
                )


                _logger.warning(

                    f"[URL CREATE START] "

                    f"{previous_index}"
                )


                try:

                    self.create_products_url()

                except Exception as e:

                    _logger.exception(

                        f"URL CREATE FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'url_creating'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return


                new_index = (
                    self.last_processed_product_index or 0
                )


                _logger.warning(

                    f"[URL CREATE CHECK] "

                    f"{previous_index} -> {new_index}"
                )


                try:

                    total = len(
                        json.loads(
                            self.ai_response or "[]"
                        )
                    )

                except Exception:

                    total = 0


                _logger.warning(

                    f"[URL TOTAL PRODUCTS] "

                    f"{total}"
                )


                if new_index >= total:
                    self.stage_retry_count = 0
                   

                    if not self.completion_email_sent:

                        self.send_completion_email()
                   
                   
                    self.state = 'done'

                    _logger.warning(
                        "URL COMPLETE ✅"
                    )


                elif new_index > previous_index:

                    self.stage_retry_count = 0

                    self.last_known_state = 'url_creating'
                    self.state = 'url_creating'

                    _logger.warning(
                        "[URL CREATE] CONTINUE"
                    )

                else:

                    _logger.warning(
                        "[URL CREATE] NO PROGRESS"
                    )

                    self.state = 'failed'


                self._safe_commit_progress()

                return


        # =================================================
        # EXCEL FLOW
        # =================================================

        if self.excel_file and not self.pdf_file:

            _logger.warning(
                "FLOW → EXCEL"
            )


            # =============================================
            # START
            # =============================================

            if self.state == 'draft':

                self.stage_retry_count = 0

                self.last_known_state = 'excel_parsing'

                self.state = 'excel_parsing'

                self._safe_commit_progress()

                return


            # =============================================
            # PARSE
            # =============================================

            if self.state == 'excel_parsing':

                previous_index = (
                
                    self.excel_parse_index or 0
                )

                _logger.warning(

                    f"[EXCEL PARSE START] "

                    f"previous_index={previous_index}"
                )


                self.parse_excel()


                new_index = (
                   
                    self.excel_parse_index or 0
                )


                _logger.warning(

                    f"[EXCEL PARSE CHECK] "

                    f"{previous_index} -> {new_index}"
                )


                # ==========================================
                # NEW ROWS FOUND
                # ==========================================

                if new_index > previous_index:
                    
                    self.state = 'excel_ai'

                    _logger.warning(

                        "[EXCEL STATE CHANGE] "

                        f"{self.id} -> excel_ai"
                    )

                    _logger.warning(
                        "[EXCEL PARSE] NEW BATCH READY → excel_ai"
                    )

                    self._safe_commit_progress()

                    return


                else:

                    _logger.warning(
                        "[EXCEL PARSE] NO NEW ROWS"
                    )

                    if self.is_excel_parsed:

                        _logger.warning(
                            "[EXCEL PARSE COMPLETE] → excel_ai"
                        )

                        # successful stage transition
                      
                        self.stage_retry_count = 0

                        self.last_known_state = 'excel_ai'

                        self.state = 'excel_ai'

                        # cleanup optional URL enrichment state
                        self.excel_url_processing = False

                        self.excel_url_index = 0

                  
                    else:

                        _logger.warning(
                            "[EXCEL PARSE STALLED]"
                        )

                        self.stage_retry_count += 1

                        self.last_error = "Excel parse stalled"

                        self.last_known_state = 'excel_parsing'

                        self.state = 'review' 

                self._safe_commit_progress()

                return


            # =============================================
            # AI
            # =============================================

            if self.state == 'excel_ai':

                try:
                    previous_ai_index = self.excel_ai_index or 0

                    _logger.warning(

                        f"[EXCEL AI BEFORE] "

                        f"{previous_ai_index}"
                    )

                    self.send_to_openai_excel()

                    new_ai_index = self.excel_ai_index or 0

                    ai_progress_detected = (
                        new_ai_index > previous_ai_index
                    )
                                        
                    _logger.warning(

                        f"[EXCEL AI AFTER] "

                        f"{new_ai_index}"
                    )

                except Exception as e:

                    _logger.exception(

                        f"EXCEL AI FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'excel_ai'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return


                try:

                    extracted_rows = json.loads(
                        self.extracted_text or "[]"
                    )

                    total_rows = len(extracted_rows)

                except Exception:

                    total_rows = 0


                _logger.warning(

                    f"[EXCEL AI TOTAL ROWS] "

                    f"{total_rows}"
                )


                _logger.warning(

                    f"[EXCEL AI STATE] "

                    f"{self.state}"
                )

                # ==========================================
                # AI COMPLETE → CREATE
                # ==========================================

                if (
                        self.state != 'failed'
                        and
                        (
                            ai_progress_detected
                            or
                            self.ai_response
                        )
                    ):

                    _logger.warning(
                        "[EXCEL AI COMPLETE] → excel_creating"
                    )

                    self.stage_retry_count = 0

                    self.last_known_state = 'excel_creating'

                    self.state = 'excel_creating'

                self.flush_recordset()
                self.env.cr.commit()

                return

            # =============================================
            # CREATE
            # =============================================


            #-----------EXCEL ROW PROCESSOR-------------
        
            if self.state == 'excel_creating':
                
                try:

                    self.create_products_excel()
                  
                except Exception as e:

                    _logger.exception(
                        f"EXCEL CREATE FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'excel_creating'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return

                _logger.warning(

                    f"[EXCEL CREATE STATE] "

                    f"{self.state}"
                )


                self.flush_recordset()
                self.env.cr.commit()

                return


            if self.state == 'excel_url_enrichment':

                try:

                    self.process_excel_url_queue()

                except Exception as e:

                    _logger.exception(
                        f"EXCEL URL ENRICHMENT FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'excel_url_enrichment'

                    self.state = 'review'

                    self._safe_commit_progress()

                return

              
            # =============================================
            # RETURN
            # =============================================

            if (
                self.state == 'excel_creating'
                or
                self.state == 'excel_url_enrichment'
                or
                self.excel_url_processing
            ):

                return

        #=================================================
        # PDF FLOW
        # =================================================

        elif self.pdf_file:

            _logger.warning(
                "FLOW → PDF"
            )


            # =============================================
            # START
            # =============================================

            if self.state == 'draft':

                self.stage_retry_count = 0

                self.last_known_state = 'pdf_extracting'

                self.state = 'pdf_extracting'

                self._safe_commit_progress()

                return


            # =============================================
            # EXTRACT
            # =============================================

            if self.state == 'pdf_extracting':

                try:

                    self.extract_pdf()

                except Exception as e:

                    _logger.exception(

                        f"PDF EXTRACT FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'pdf_extracting'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return


                if (

                    (self.current_page or 0)

                    <

                    (self.total_pages or 0)

                ):

                    _logger.warning(

                        f"PDF EXTRACTION CONTINUES "

                        f"→ PAGE "

                        f"{self.current_page}/"

                        f"{self.total_pages}"
                    )

                    self.state = 'pdf_extracting'
                
                else:
                    _logger.warning(
                        "PDF EXTRACTION COMPLETE "
                        "→ family_a_review"
                    )

                    self.last_known_state = (
                        'family_a_review'
                    )

                    self.state = (
                        'family_a_review'
                    )
                  

                self.flush_recordset()
                self.env.cr.commit()

                return

            # =========================================================
            # AZURE FALLBACK FOR FAMILY A FAILED PAGES
            # =========================================================

            if self.state == 'azure_fallback':

                _logger.warning(
                    "[AZURE FALLBACK] START "
                    "| JOB=%s",
                    self.id
                )

                self.last_known_state = 'azure_fallback'

                # =====================================================
                # SAVE ORIGINAL JOB STATE
                # =====================================================
                #
                # The Azure fallback may span multiple cron invocations.
                #
                # The persistent snapshot below must survive those
                # invocations because self.pdf_file becomes the temporary
                # failed-pages-only PDF.
                #
                # IMPORTANT:
                # The snapshot is cleared only after Azure fallback
                # completes successfully.
                # =====================================================


                # =================================================
                # PERSIST ORIGINAL PDF BEFORE AZURE TEMPORARY PDF
                # =================================================
                #
                # IMPORTANT:
                #
                # self.pdf_file may already contain a temporary Azure
                # fallback PDF when this method is re-entered by a later
                # cron invocation.
                #
                # Therefore NEVER assume self.pdf_file is still the
                # original catalogue.
                #
                # The first Azure fallback invocation permanently
                # snapshots the original PDF.
                #
                # Subsequent retries reuse that snapshot.
                # =================================================

                if not self.azure_fallback_original_pdf:

                    if not self.pdf_file:

                        raise ValueError(
                            "Cannot start Azure fallback: "
                            "original PDF is unavailable."
                        )

                    self.azure_fallback_original_pdf = (
                        self.pdf_file
                    )

                    self.azure_fallback_original_total_pages = (
                        self.total_pages or 0
                    )

                    self.flush_recordset()
                    self.env.cr.commit()

                    _logger.warning(
                        "[AZURE FALLBACK] ORIGINAL PDF SNAPSHOT SAVED "
                        "| JOB=%s "
                        "| TOTAL_PAGES=%s",
                        self.id,
                        self.azure_fallback_original_total_pages,
                    )

                else:

                    _logger.warning(
                        "[AZURE FALLBACK] REUSING PERSISTED ORIGINAL PDF "
                        "| JOB=%s "
                        "| TOTAL_PAGES=%s",
                        self.id,
                        self.azure_fallback_original_total_pages,
                    )


                # =================================================
                # USE PERSISTED ORIGINAL AS AUTHORITATIVE SOURCE
                # =================================================

                original_pdf_file = (
                    self.azure_fallback_original_pdf
                )

                original_total_pages = (
                    self.azure_fallback_original_total_pages
                    or 0
                )

                original_current_page = (
                    self.current_page or 0
                )

                original_last_ai_page = (
                    self.last_ai_page or 0
                )

                page_model = self.env[
                    'vendor.import.page'
                ]

                preserved_pages = []

                temporary_pdf_created = False

                try:

                    # =================================================
                    # LOAD AUTHORITATIVE FAMILY A REVIEW
                    # =================================================

                    try:

                        family_a_review = json.loads(
                            self.family_a_review_json
                            or "{}"
                        )

                    except Exception as e:

                        raise ValueError(
                            "Invalid family_a_review_json: "
                            f"{str(e)}"
                        )

                    # =================================================
                    # DETERMINE REVIEW MODE
                    # =================================================

                    technical_failure = bool(
                        family_a_review.get(
                            "technical_failure",
                            False
                        )
                    )

                    # =================================================
                    # READ NORMAL FAMILY A FAILED PAGES
                    # =================================================

                    failed_pages = sorted({
                        int(page)
                        for page in family_a_review.get(
                            "failed_pages",
                            []
                        )
                    })

                    # =================================================
                    # TECHNICAL REVIEW FAILURE
                    # =================================================
                    #
                    # The Family A visual reviewer itself failed.
                    #
                    # Therefore there is NO trustworthy page-level
                    # decision.
                    #
                    # Every page currently extracted by Family A
                    # must be treated as requiring Azure processing.
                    #
                    # This is different from a normal review where
                    # failed_pages contains only the pages that
                    # Family A explicitly rejected.
                    # =================================================

                    if technical_failure:

                        # =================================================
                        # TECHNICAL FAMILY A FAILURE
                        # =================================================
                        #
                        # The original Family A page records may already have
                        # been removed by an earlier Azure fallback invocation.
                        #
                        # Therefore NEVER depend on vendor.import.page here.
                        #
                        # The authoritative page list was captured inside
                        # family_a_review_json before those records were removed.
                        # =================================================

                        failed_pages = sorted({
                            int(page)
                            for page in family_a_review.get(
                                "failed_pages",
                                []
                            )
                        })

                        _logger.warning(
                            "[AZURE FALLBACK] "
                            "TECHNICAL FAILURE PAGE SNAPSHOT "
                            "| JOB=%s "
                            "| PAGES=%s",
                            self.id,
                            failed_pages
                        )

                    else:

                        _logger.warning(
                            "[AZURE FALLBACK] "
                            "FAMILY A REVIEW FAILED PAGES "
                            "| JOB=%s "
                            "| PAGES=%s",
                            self.id,
                            failed_pages
                        )

                    # =================================================
                    # SAFETY: NOTHING TO FALL BACK
                    # =================================================
                    #
                    # An empty failed_pages list is safe only when
                    # the Family A review actually completed.
                    #
                    # A technical failure with an empty list must
                    # NEVER go directly to PDF AI.
                    # =================================================

                    if (
                        not failed_pages
                        and not technical_failure
                    ):

                        _logger.warning(
                            "[AZURE FALLBACK] NO FAILED PAGES "
                            "→ PDF AI "
                            "| JOB=%s",
                            self.id
                        )

                        self.last_known_state = 'pdf_ai'
                        self.state = 'pdf_ai'

                        self.flush_recordset()
                        self.env.cr.commit()

                        return


                    if (
                        not failed_pages
                        and technical_failure
                    ):

                        raise RuntimeError(
                            "Family A review failed technically "
                            "but no fallback page numbers were "
                            "recorded."
                        )

                    
                    # =================================================
                    # LOAD FAMILY A PASS PAGES FOR PRESERVATION
                    # =================================================
                    #
                    # NORMAL REVIEW:
                    #
                    # Family A successfully completed its review.
                    # Therefore only explicitly failed pages are sent
                    # to Azure. All other pages are preserved.
                    #
                    # TECHNICAL REVIEW FAILURE:
                    #
                    # Family A review never completed.
                    # Therefore NO Family A page is trusted or preserved.
                    # All captured fallback pages go to Azure.
                    # =================================================

                    preserved_pages = []

                    if technical_failure:

                        _logger.warning(
                            "[AZURE FALLBACK] "
                            "TECHNICAL FAILURE "
                            "→ NO FAMILY A PAGES PRESERVED "
                            "| JOB=%s "
                            "| AZURE_PAGES=%s",
                            self.id,
                            failed_pages
                        )

                    else:

                        existing_pages = page_model.search(
                            [
                                ('job_id', '=', self.id)
                            ],
                            order='page_number asc'
                        )

                        for record in existing_pages:

                            page_number = int(
                                record.page_number
                            )

                            # -------------------------------------------------
                            # EXPLICITLY FAILED FAMILY A PAGE
                            # -------------------------------------------------

                            if page_number in failed_pages:

                                _logger.warning(
                                    "[AZURE FALLBACK] "
                                    "NOT PRESERVING FAILED PAGE "
                                    "| JOB=%s "
                                    "| PAGE=%s",
                                    self.id,
                                    page_number
                                )

                                continue

                            # -------------------------------------------------
                            # APPROVED FAMILY A PAGE
                            # -------------------------------------------------

                            preserved_pages.append({
                                "page_number":
                                    page_number,

                                "extracted_json":
                                    record.extracted_json or "[]",

                                "page_images_json":
                                    record.page_images_json or "[]",
                            })

                        _logger.warning(
                            "[AZURE FALLBACK] "
                            "PRESERVED FAMILY A PASS PAGES "
                            "| JOB=%s "
                            "| COUNT=%s "
                            "| PAGES=%s",
                            self.id,
                            len(preserved_pages),
                            [
                                item["page_number"]
                                for item in preserved_pages
                            ]
                        )

                    # =================================================
                    # LOAD ORIGINAL PDF
                    # =================================================

                    if not original_pdf_file:

                        raise ValueError(
                            "Original PDF file is not available."
                        )

                    try:

                        original_pdf_bytes = (
                            base64.b64decode(
                                original_pdf_file
                            )
                        )

                    except Exception as e:

                        raise ValueError(
                            "Unable to decode original PDF: "
                            f"{str(e)}"
                        )

                    source_doc = None
                    fallback_doc = None

                    try:

                        # =================================================
                        # OPEN ORIGINAL PDF
                        # =================================================

                        source_doc = fitz.open(
                            stream=original_pdf_bytes,
                            filetype="pdf"
                        )

                        source_total_pages = len(
                            source_doc
                        )

                        _logger.warning(
                            "[AZURE FALLBACK] ORIGINAL PDF "
                            "| JOB=%s | TOTAL=%s",
                            self.id,
                            source_total_pages
                        )




                        # =================================================
                        # VALIDATE FAILED PAGE NUMBERS
                        # =================================================

                        _logger.warning(
                            "[AZURE FALLBACK] SOURCE PDF VALIDATION "
                            "| JOB=%s "
                            "| SOURCE_TOTAL_PAGES=%s "
                            "| FAILED_PAGES=%s "
                            "| SNAPSHOT_AVAILABLE=%s",
                            self.id,
                            source_total_pages,
                            failed_pages,
                            bool(self.azure_fallback_original_pdf),
                        )


                        invalid_pages = [
                            page
                            for page in failed_pages
                            if page < 1
                            or page > source_total_pages
                        ]

                        if invalid_pages:

                            raise ValueError(
                                "Family A review returned invalid "
                                "page numbers: "
                                f"{invalid_pages}"
                            )

                        # =================================================
                        # BUILD FAILED-PAGES-ONLY PDF
                        # =================================================
                        #
                        # IMPORTANT:
                        #
                        # The existing Azure extractor is intentionally
                        # reused unchanged.
                        #
                        # We give it a temporary PDF containing ONLY the
                        # pages Family A failed.
                        #
                        # Example:
                        #
                        # Original PDF:
                        #   1 2 3 4 5 6 7 8
                        #
                        # Family A:
                        #   PASS PASS FAIL PASS FAIL PASS PASS PASS
                        #
                        # Temporary PDF:
                        #   original page 3
                        #   original page 5
                        #
                        # Azure sees only 2 pages.
                        # =================================================

                        fallback_doc = fitz.open()

                        for original_page_number in failed_pages:

                            zero_based_page = (
                                original_page_number - 1
                            )

                            fallback_doc.insert_pdf(
                                source_doc,
                                from_page=zero_based_page,
                                to_page=zero_based_page
                            )

                        fallback_pdf_io = io.BytesIO()

                        fallback_doc.save(
                            fallback_pdf_io
                        )

                        fallback_pdf_io.seek(0)

                        fallback_pdf_bytes = (
                            fallback_pdf_io.getvalue()
                        )

                        fallback_pdf_base64 = (
                            base64.b64encode(
                                fallback_pdf_bytes
                            ).decode("utf-8")
                        )

                        temporary_pdf_created = True

                        _logger.warning(
                            "[AZURE FALLBACK] TEMPORARY PDF CREATED "
                            "| JOB=%s "
                            "| ORIGINAL_TOTAL=%s "
                            "| FAILED_PAGES=%s "
                            "| TEMP_TOTAL=%s",
                            self.id,
                            original_total_pages,
                            failed_pages,
                            len(failed_pages),
                        )

                    finally:

                        try:
                            if fallback_doc:
                                fallback_doc.close()
                        except Exception:
                            pass

                        try:
                            if source_doc:
                                source_doc.close()
                        except Exception:
                            pass

                    # =================================================
                    # REMOVE ALL CURRENT PAGE RECORDS TEMPORARILY
                    # =================================================
                    #
                    # This is NOT throwing away Family A output.
                    #
                    # The PASS records have already been copied into
                    # preserved_pages above.
                    #
                    # They will be recreated after Azure finishes.
                    #
                    # We must do this because the existing Azure
                    # extractor skips any page that already has a
                    # vendor.import.page record.
                    # =================================================

                    current_records = page_model.search([
                        ('job_id', '=', self.id)
                    ])

                    if current_records:

                        _logger.warning(
                            "[AZURE FALLBACK] TEMPORARILY REMOVING "
                            "PASS PAGE RECORDS "
                            "| JOB=%s | COUNT=%s",
                            self.id,
                            len(current_records)
                        )

                        current_records.unlink()

                    # =================================================
                    # SWITCH JOB TO FAILED-PAGES-ONLY PDF
                    # =================================================

                    self.pdf_file = (
                        fallback_pdf_base64
                    )

                    self.total_pages = (
                        len(failed_pages)
                    )

                    self.current_page = 0

                    self.last_ai_page = 0

                    self.last_known_state = (
                        'azure_fallback'
                    )

                    self.state = (
                        'azure_fallback'
                    )

                    self.flush_recordset()
                    self.env.cr.commit()

                    # =================================================
                    # RUN EXISTING AZURE EXTRACTOR
                    # =================================================
                    #
                    # IMPORTANT:
                    #
                    # We are NOT rewriting extract_pdf_azure().
                    #
                    # It continues to perform its normal batching,
                    # extraction, segmentation and persistence.
                    #
                    # The only difference is that its input PDF contains
                    # ONLY the failed Family A pages.
                    # =================================================

                    expected_temp_pages = (
                        len(failed_pages)
                    )

                    while (
                        (self.current_page or 0)
                        <
                        expected_temp_pages
                    ):

                        previous_page = (
                            self.current_page or 0
                        )

                        _logger.warning(
                            "[AZURE FALLBACK] RUNNING EXISTING "
                            "AZURE EXTRACTOR "
                            "| JOB=%s "
                            "| TEMP_PAGE=%s/%s",
                            self.id,
                            previous_page,
                            expected_temp_pages
                        )

                        self.last_known_state = (
                            'azure_fallback'
                        )

                        self.state = (
                            'azure_fallback'
                        )

                        self.extract_pdf_azure()

                        current_page = (
                            self.current_page or 0
                        )

                        _logger.warning(
                            "[AZURE FALLBACK] AZURE PROGRESS "
                            "| JOB=%s "
                            "| TEMP_PAGE=%s/%s",
                            self.id,
                            current_page,
                            expected_temp_pages
                        )

                        # =============================================
                        # PREVENT INFINITE LOOP
                        # =============================================

                        if current_page <= previous_page:

                            raise RuntimeError(
                                "Azure fallback extractor "
                                "did not advance. "
                                f"Previous={previous_page}, "
                                f"Current={current_page}"
                            )

                    # =================================================
                    # LOAD AZURE TEMPORARY PAGE RECORDS
                    # =================================================

                    azure_temp_pages = page_model.search(
                        [
                            ('job_id', '=', self.id)
                        ],
                        order='page_number asc'
                    )

                    _logger.warning(
                        "[AZURE FALLBACK] TEMPORARY AZURE RECORDS "
                        "| JOB=%s | COUNT=%s | EXPECTED=%s",
                        self.id,
                        len(azure_temp_pages),
                        len(failed_pages)
                    )

                    # =================================================
                    # SAFETY CHECK
                    # =================================================

                    if len(azure_temp_pages) != len(
                        failed_pages
                    ):

                        raise RuntimeError(
                            "Azure fallback did not produce "
                            "one page record for every failed "
                            "Family A page. "
                            f"Expected={len(failed_pages)}, "
                            f"Received={len(azure_temp_pages)}"
                        )

                    # =================================================
                    # REMAP AZURE TEMP PAGE NUMBERS
                    # =================================================
                    #
                    # Temporary:
                    #
                    #   1 → original failed page 7
                    #   2 → original failed page 13
                    #   3 → original failed page 21
                    #
                    # Must become:
                    #
                    #   7
                    #   13
                    #   21
                    #
                    # Also update the "page" value inside extracted_json.
                    # =================================================

                    for temp_index, azure_record in enumerate(
                        azure_temp_pages
                    ):

                        original_page_number = (
                            failed_pages[temp_index]
                        )

                        try:

                            blocks = json.loads(
                                azure_record.extracted_json
                                or "[]"
                            )

                        except Exception as e:

                            raise ValueError(
                                "Invalid Azure extracted_json "
                                f"for temporary page "
                                f"{temp_index + 1}: {str(e)}"
                            )

                        if not isinstance(
                            blocks,
                            list
                        ):

                            raise ValueError(
                                "Azure extracted_json must "
                                "contain a list."
                            )

                        # =============================================
                        # RESTORE ORIGINAL PAGE NUMBER INSIDE BLOCKS
                        # =============================================

                        for block in blocks:

                            if isinstance(
                                block,
                                dict
                            ):

                                block["page"] = (
                                    original_page_number
                                )

                        azure_record.write({
                            "page_number":
                                original_page_number,

                            "extracted_json":
                                json.dumps(
                                    blocks,
                                    ensure_ascii=False
                                )
                        })

                        _logger.warning(
                            "[AZURE FALLBACK] PAGE REMAPPED "
                            "| TEMP=%s "
                            "| ORIGINAL=%s "
                            "| JOB=%s",
                            temp_index + 1,
                            original_page_number,
                            self.id
                        )

                    # =================================================
                    # RESTORE FAMILY A PASS PAGES
                    # =================================================

                    restored_count = 0

                    for preserved in preserved_pages:

                        page_number = (
                            preserved["page_number"]
                        )

                        # ---------------------------------------------
                        # Safety: failed pages must come from Azure.
                        # ---------------------------------------------

                        if page_number in failed_pages:

                            _logger.warning(
                                "[AZURE FALLBACK] "
                                "NOT RESTORING FAILED PAGE "
                                "| PAGE=%s | JOB=%s",
                                page_number,
                                self.id
                            )

                            continue

                        # ---------------------------------------------
                        # Safety: don't duplicate Azure page.
                        # ---------------------------------------------

                        existing = page_model.search([
                            ('job_id', '=', self.id),
                            ('page_number', '=', page_number)
                        ], limit=1)

                        if existing:

                            _logger.warning(
                                "[AZURE FALLBACK] PAGE ALREADY EXISTS "
                                "| PAGE=%s | JOB=%s",
                                page_number,
                                self.id
                            )

                            continue

                        page_model.create({
                            'job_id':
                                self.id,

                            'page_number':
                                page_number,

                            'extracted_json':
                                preserved[
                                    "extracted_json"
                                ],

                            'page_images_json':
                                preserved[
                                    "page_images_json"
                                ],
                        })

                        restored_count += 1

                    _logger.warning(
                        "[AZURE FALLBACK] FAMILY A PASS PAGES "
                        "RESTORED "
                        "| JOB=%s | COUNT=%s",
                        self.id,
                        restored_count
                    )

                    # =================================================
                    # VERIFY FINAL PAGE INVENTORY
                    # =================================================

                    final_pages = page_model.search(
                        [
                            ('job_id', '=', self.id)
                        ],
                        order='page_number asc'
                    )

                    final_page_numbers = [
                        int(record.page_number)
                        for record in final_pages
                    ]

                    expected_page_numbers = sorted({
                        int(page)
                        for page in (
                            [
                                item["page_number"]
                                for item in preserved_pages
                            ]
                            +
                            failed_pages
                        )
                    })

                    _logger.warning(
                        "[AZURE FALLBACK] FINAL PAGE INVENTORY "
                        "| JOB=%s "
                        "| ACTUAL=%s "
                        "| EXPECTED=%s",
                        self.id,
                        final_page_numbers,
                        expected_page_numbers
                    )

                    if (
                        final_page_numbers
                        !=
                        expected_page_numbers
                    ):

                        raise RuntimeError(
                            "Final page inventory mismatch after "
                            "Azure fallback. "
                            f"Actual={final_page_numbers}, "
                            f"Expected={expected_page_numbers}"
                        )

                    # =================================================
                    # RESTORE ORIGINAL JOB PDF
                    # =================================================

                    self.pdf_file = (
                        original_pdf_file
                    )

                    self.total_pages = (
                        original_total_pages
                        or len(expected_page_numbers)
                    )

                    self.current_page = (
                        self.total_pages
                    )

                    # PDF AI must start from page 1 again.
                    self.last_ai_page = 0

                    # =================================================
                    # CLEAR PERSISTENT AZURE ORIGINAL SNAPSHOT
                    # =================================================
                    #
                    # Azure fallback has completed successfully.
                    # The temporary fallback PDF is no longer needed,
                    # and the persistent original snapshot can be removed.
                    # =================================================

                    self.azure_fallback_original_pdf = False

                    self.azure_fallback_original_total_pages = 0

                    _logger.warning(
                        "[AZURE FALLBACK] ORIGINAL PDF SNAPSHOT CLEARED "
                        "| JOB=%s",
                        self.id,
                    )


                    # =================================================
                    # HAND OFF TO AZURE VISUAL REVIEW
                    # =================================================
                    #
                    # Azure extraction has now completed and the final
                    # page inventory has been restored.
                    #
                    # DO NOT send directly to PDF AI.
                    #
                    # The existing azure_review state is responsible for
                    # deciding whether the Azure extraction is good enough
                    # or whether Azure re-cropping is required.
                    # =================================================

                    _logger.warning(
                        "[AZURE FALLBACK] COMPLETE "
                        "→ AZURE REVIEW "
                        "| JOB=%s "
                        "| PASS_PAGES=%s "
                        "| AZURE_PAGES=%s",
                        self.id,
                        len(preserved_pages),
                        len(failed_pages)
                    )

                    self.stage_retry_count = 0

                    self.last_error = False

                    self.last_known_state = (
                        'azure_review'
                    )

                    self.state = (
                        'azure_review'
                    )

                    self.flush_recordset()
                    self.env.cr.commit()

                    return

                except Exception as e:

                    # =================================================
                    # RESTORE PASS PAGES ON FAILURE
                    # =================================================

                    _logger.exception(
                        "[AZURE FALLBACK] FAILED "
                        "| JOB=%s | %s",
                        self.id,
                        str(e)
                    )

                    try:

                        # Remove temporary Azure records.
                        temporary_records = page_model.search([
                            ('job_id', '=', self.id)
                        ])

                        if temporary_records:

                            temporary_records.unlink()

                        # Restore Family A PASS records.
                        for preserved in preserved_pages:

                            existing = page_model.search([
                                ('job_id', '=', self.id),
                                (
                                    'page_number',
                                    '=',
                                    preserved["page_number"]
                                )
                            ], limit=1)

                            if existing:

                                continue

                            page_model.create({
                                'job_id':
                                    self.id,

                                'page_number':
                                    preserved[
                                        "page_number"
                                    ],

                                'extracted_json':
                                    preserved[
                                        "extracted_json"
                                    ],

                                'page_images_json':
                                    preserved[
                                        "page_images_json"
                                    ],
                            })

                    except Exception:

                        _logger.exception(
                            "[AZURE FALLBACK] "
                            "FAILED TO RESTORE FAMILY A "
                            "PASS PAGES "
                            "| JOB=%s",
                            self.id
                        )

                    # =================================================
                    # RESTORE TRUE ORIGINAL PDF FROM PERSISTENT SNAPSHOT
                    # =================================================

                    self.pdf_file = (
                        self.azure_fallback_original_pdf
                    )

                    self.total_pages = (
                        self.azure_fallback_original_total_pages
                        or 0
                    )

                    self.current_page = (
                        original_current_page
                    )

                    self.last_ai_page = (
                        original_last_ai_page
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = (
                        'azure_fallback'
                    )

                    self.state = (
                        'review'
                    )

                    self._safe_commit_progress()

                    return

            

            # =================================================
            # FAMILY A VISUAL QUALITY GATE
            # =================================================

            if self.state == 'family_a_review':

                _logger.warning(
                    "[FAMILY A REVIEW] START "
                    "| JOB=%s",
                    self.id
                )

                self.last_known_state = (
                    'family_a_review'
                )

                try:

                    review_result = (
                        self._review_family_a_extraction_with_openai()
                    )


                except Exception as e:

                    _logger.exception(
                        "[FAMILY A REVIEW] FAILED "
                        f"| JOB={self.id}"
                    )

                    # =================================================
                    # FAMILY A REVIEW TECHNICAL FAILURE
                    # =================================================
                    #
                    # OpenAI did NOT successfully complete the
                    # Family A visual review.
                    #
                    # Therefore Family A is NOT approved.
                    #
                    # Do not fabricate page-level failed_pages.
                    # Mark this as a review-level technical failure
                    # so azure_fallback can handle it differently
                    # from a normal Family A FAIL decision.
                    # =================================================
                    
                    # =================================================
                    # CAPTURE ORIGINAL FAMILY A PAGE NUMBERS
                    # =================================================

                    page_records = self.env[
                        'vendor.import.page'
                    ].search([
                        ('job_id', '=', self.id)
                    ], order='page_number asc')

                    fallback_pages = sorted({
                        int(record.page_number)
                        for record in page_records
                        if record.page_number
                    })

                    _logger.warning(
                        "[FAMILY A REVIEW] "
                        "TECHNICAL FAILURE PAGE SNAPSHOT "
                        "| JOB=%s "
                        "| PAGES=%s",
                        self.id,
                        fallback_pages
                    )

                    # =================================================
                    # DIAGNOSTIC: COMPLETE FAMILY A REVIEW OUTPUT
                    # =================================================

                    _logger.warning(
                        "[FAMILY A RAW REVIEW DIAGNOSTIC] "
                        "JOB=%s | TYPE=%s | KEYS=%s",
                        self.id,
                        type(review_result).__name__,
                        (
                            list(review_result.keys())
                            if isinstance(review_result, dict)
                            else None
                        )
                    )

                    if isinstance(review_result, dict):

                        _logger.warning(
                            "[FAMILY A RAW REVIEW DIAGNOSTIC] "
                            "JOB=%s | DECISION=%s | "
                            "PASSED_PAGES=%s | "
                            "PARTIAL_PAGES=%s | "
                            "FAILED_PAGES=%s",
                            self.id,
                            review_result.get("decision"),
                            review_result.get("passed_pages"),
                            review_result.get("partial_pages"),
                            review_result.get("failed_pages"),
                        )

                        family_a_pages = review_result.get(
                            "pages",
                            []
                        )

                        _logger.warning(
                            "[FAMILY A RAW REVIEW DIAGNOSTIC] "
                            "JOB=%s | PAGE_RECORD_COUNT=%s",
                            self.id,
                            len(family_a_pages)
                            if isinstance(family_a_pages, list)
                            else "NOT_A_LIST"
                        )

                        for page_result in (
                            family_a_pages
                            if isinstance(family_a_pages, list)
                            else []
                        ):

                            if not isinstance(
                                page_result,
                                dict
                            ):
                                _logger.warning(
                                    "[FAMILY A RAW PAGE INVALID] "
                                    "JOB=%s | VALUE=%r",
                                    self.id,
                                    page_result
                                )
                                continue

                            _logger.warning(
                                "[FAMILY A RAW PAGE] "
                                "JOB=%s | PAGE=%s | "
                                "DECISION=%s | KEYS=%s | "
                                "MISSING_ASSET_REQUESTS=%s",
                                self.id,
                                page_result.get("page"),
                                page_result.get("decision"),
                                list(page_result.keys()),
                                page_result.get(
                                    "missing_asset_requests"
                                ),
                            )

                    self.family_a_review_json = json.dumps(
                        {
                            "decision": "FAIL",
                            "confidence": 0,
                            "technical_failure": True,
                            "reason": (
                                "Family A visual review "
                                "failed technically."
                            ),
                            "error": str(e),
                            "pages": [],
                            "failed_pages": fallback_pages,
                        },
                        ensure_ascii=False
                    )

                    self.stage_retry_count = 0

                    self.last_error = str(e)

                    self.last_known_state = (
                        'azure_fallback'
                    )

                    self.state = (
                        'azure_fallback'
                    )

                    _logger.warning(
                        "[FAMILY A REVIEW] "
                        "TECHNICAL FAILURE "
                        "→ AZURE FALLBACK "
                        "| JOB=%s "
                        "| ERROR=%s "
                        "| NEW_STATE=%s",
                        self.id,
                        str(e),
                        self.state,
                    )

                    self.flush_recordset()
                    self.env.cr.commit()

                    _logger.warning(
                        "[FAMILY A REVIEW] "
                        "RETURNING AFTER TECHNICAL FAILURE "
                        "| JOB=%s "
                        "| STATE=%s",
                        self.id,
                        self.state,
                    )

                    return


                # =================================================
                # SAVE COMPLETE REVIEW RESULT
                # =================================================
               

                self.family_a_review_json = json.dumps(
                    review_result,
                    ensure_ascii=False
                )

                _logger.warning(
                    "[FAMILY A REVIEW JSON SAVED] "
                    "JOB=%s | CHARS=%s",
                    self.id,
                    len(self.family_a_review_json or "")
                )

                _logger.warning(
                    "[FAMILY A RAW REVIEW RESULT] "
                    "JOB=%s | RESULT=%s",
                    self.id,
                    json.dumps(
                        review_result,
                        ensure_ascii=False,
                        indent=2,
                        default=str
                    )
                )

                # =================================================
                # READ AUTHORITATIVE FAMILY A ROUTING
                # =================================================

                failed_pages = sorted({
                    int(page)
                    for page in review_result.get(
                        'failed_pages',
                        []
                    )
                })

                partial_pages = sorted({
                    int(page)
                    for page in review_result.get(
                        'partial_pages',
                        []
                    )
                })

                passed_pages = sorted({
                    int(page)
                    for page in review_result.get(
                        'passed_pages',
                        []
                    )
                })


                _logger.warning(
                    "[FAMILY A REVIEW] ROUTING DECISION "
                    "| JOB=%s "
                    "| PASS=%s "
                    "| PARTIAL=%s "
                    "| FAIL=%s",
                    self.id,
                    review_result.get(
                        'passed_pages',
                        []
                    ),
                    partial_pages,
                    failed_pages
                )

                # =================================================
                # FAMILY A REVIEW → AUTHORITATIVE ROUTING
                # =================================================

                _logger.warning(
                    "[FAMILY A ROUTING] "
                    "JOB=%s | FAILED=%s | PARTIAL=%s | PASSED=%s",
                    self.id,
                    failed_pages,
                    partial_pages,
                    passed_pages,
                )

                # =================================================
                # FULL PAGE FAILURE
                # → AZURE FULL FALLBACK
                # =================================================

                if failed_pages:

                    _logger.error(
                        "[FAMILY A ROUTING] "
                        "FULL FAILURE "
                        "→ AZURE FALLBACK "
                        "| JOB=%s "
                        "| FAILED_PAGES=%s "
                        "| PARTIAL_PAGES=%s "
                        "| PASSED_PAGES=%s",
                        self.id,
                        failed_pages,
                        partial_pages,
                        passed_pages,
                    )

                    self.last_known_state = (
                        'azure_fallback'
                    )

                    self.state = (
                        'azure_fallback'
                    )


                # =================================================
                # PARTIAL FAMILY A RESULT
                # → ALWAYS ENTER PARTIAL RECOVERY
                #
                # TEMPORARY TEST RULE:
                # Do NOT require recovery-request count here.
                #
                # We are testing whether the PARTIAL state itself
                # correctly enters the recovery state.
                # =================================================

                elif partial_pages:

                    _logger.warning(
                        "[FAMILY A ROUTING] "
                        "PARTIAL RESULT "
                        "→ FAMILY A PARTIAL RECOVERY "
                        "| JOB=%s "
                        "| PARTIAL_PAGES=%s "
                        "| PASSED_PAGES=%s "
                        "| FAILED_PAGES=%s",
                        self.id,
                        partial_pages,
                        passed_pages,
                        failed_pages,
                    )

                    self.last_known_state = (
                        'family_a_partial_recovery'
                    )

                    self.state = (
                        'family_a_partial_recovery'
                    )


                # =================================================
                # COMPLETE FAMILY A SUCCESS
                # → PDF AI
                # =================================================

                else:

                    _logger.warning(
                        "[FAMILY A TEST ROUTING] "
                        "PASS PAGES "
                        "→ PDF AI "
                        "| JOB=%s "
                        "| PAGES=%s",
                        self.id,
                        passed_pages
                    )

                    self.last_known_state = (
                        'pdf_ai'
                    )

                    self.state = (
                        'pdf_ai'
                    )


                # =================================================
                # PERSIST ROUTING DECISION
                # =================================================

                _logger.warning(
                    "[FAMILY A ROUTING] "
                    "FINAL STATE=%s "
                    "| LAST_KNOWN_STATE=%s "
                    "| JOB=%s",
                    self.state,
                    self.last_known_state,
                    self.id,
                )

                self.flush_recordset()
                self.env.cr.commit()

                return
            


            # =================================================
            # FAMILY A PARTIAL PRECISION RECOVERY
            # =================================================

            if self.state == 'family_a_partial_recovery':

                _logger.warning(
                    "[FAMILY A PARTIAL RECOVERY] START | JOB=%s",
                    self.id
                )

                self.last_known_state = (
                    'family_a_partial_recovery'
                )

                try:

                    # =================================================
                    # LOAD AUTHORITATIVE FAMILY A REVIEW
                    # =================================================

                    try:
                        family_a_review = json.loads(
                            self.family_a_review_json or "{}"
                        )

                    except Exception as e:

                        raise ValueError(
                            "Invalid family_a_review_json: "
                            f"{str(e)}"
                        )

                    if not isinstance(
                        family_a_review,
                        dict
                    ):
                        raise ValueError(
                            "Family A review result must "
                            "be a JSON object."
                        )

                    # =================================================
                    # AUTHORITATIVE PARTIAL PAGES
                    # =================================================

                    partial_pages = sorted({
                        int(page)
                        for page in family_a_review.get(
                            "partial_pages",
                            []
                        )
                    })

                    if not partial_pages:

                        raise ValueError(
                            "Family A entered partial recovery "
                            "but no partial_pages were recorded."
                        )

                    _logger.warning(
                        "[FAMILY A PARTIAL RECOVERY] "
                        "PARTIAL PAGES | JOB=%s | PAGES=%s",
                        self.id,
                        partial_pages
                    )

                    # =================================================
                    # BUILD RECOVERY REQUESTS
                    # =================================================

                    recovery_requests = []

                    for page_result in family_a_review.get(
                        "pages",
                        []
                    ):

                        _logger.warning(
                            "[FAMILY A RECOVERY PAGE INSPECT] "
                            "JOB=%s | RAW_PAGE_RESULT=%s",
                            self.id,
                            json.dumps(
                                page_result,
                                ensure_ascii=False,
                                default=str
                            )
                            if isinstance(page_result, dict)
                            else repr(page_result)
                        )


                        if not isinstance(
                            page_result,
                            dict
                        ):

                            _logger.error(
                                "[FAMILY A RECOVERY SKIP] "
                                "JOB=%s | REASON=PAGE_RESULT_NOT_DICT "
                                "| VALUE=%r",
                                self.id,
                                page_result
                            )

                            continue

                        try:
                            page_number = int(
                                page_result.get("page")
                            )

                        except (
                            TypeError,
                            ValueError
                        ) as e:

                            _logger.error(
                                "[FAMILY A RECOVERY SKIP] "
                                "JOB=%s | REASON=INVALID_PAGE_NUMBER "
                                "| RAW_PAGE=%r | ERROR=%s",
                                self.id,
                                page_result.get("page"),
                                str(e)
                            )

                            continue


                        if page_number not in partial_pages:

                            _logger.warning(
                                "[FAMILY A RECOVERY SKIP] "
                                "JOB=%s | PAGE=%s "
                                "| REASON=PAGE_NOT_IN_PARTIAL_PAGES "
                                "| PARTIAL_PAGES=%s",
                                self.id,
                                page_number,
                                partial_pages
                            )

                            continue

                        page_decision = str(
                            page_result.get(
                                "decision",
                                ""
                            )
                        ).upper().strip()


                        if page_decision != "PARTIAL":

                            _logger.warning(
                                "[FAMILY A RECOVERY SKIP] "
                                "JOB=%s | PAGE=%s "
                                "| REASON=PAGE_DECISION_NOT_PARTIAL "
                                "| DECISION=%s "
                                "| EXPECTED=PARTIAL",
                                self.id,
                                page_number,
                                page_decision
                            )

                            continue

                        requests = page_result.get(
                            "missing_asset_requests",
                            []
                        )

                        if not isinstance(
                            requests,
                            list
                        ):
                            raise ValueError(
                                "missing_asset_requests must "
                                "be a list for page "
                                f"{page_number}."
                            )

                        _logger.warning(
                            "[FAMILY A PARTIAL RECOVERY] "
                            "PAGE REQUESTS | JOB=%s | "
                            "PAGE=%s | COUNT=%s",
                            self.id,
                            page_number,
                            len(requests)
                        )

                        for request in requests:

                            if not isinstance(
                                request,
                                dict
                            ):

                                _logger.error(
                                    "[FAMILY A RECOVERY REQUEST SKIP] "
                                    "JOB=%s | PAGE=%s "
                                    "| REASON=REQUEST_NOT_DICT "
                                    "| VALUE=%r",
                                    self.id,
                                    page_number,
                                    request
                                )

                                continue

                            crop = request.get(
                                "crop",
                                {}
                            )

                            _logger.warning(
                                "[FAMILY A RECOVERY REQUEST INSPECT] "
                                "JOB=%s | PAGE=%s | "
                                "PRODUCT=%s | COLOR=%s | "
                                "REQUEST_KEYS=%s | CROP=%s",
                                self.id,
                                page_number,
                                request.get("product_reference"),
                                request.get("color"),
                                list(request.keys()),
                                json.dumps(
                                    request.get("crop"),
                                    ensure_ascii=False,
                                    default=str
                                )
                            )

                            if not isinstance(
                                crop,
                                dict
                            ):
                                crop = {}

                            recovery_request = {

                                "page":
                                    page_number,

                                "product_group":
                                    request.get(
                                        "product_group"
                                    ),

                                "product_reference":
                                    request.get(
                                        "product_reference"
                                    ),

                                "color":
                                    request.get(
                                        "color"
                                    ),

                                "required_image_role":
                                    request.get(
                                        "required_image_role"
                                    ),

                                "asset_type":
                                    request.get(
                                        "asset_type"
                                    ),

                                "reason":
                                    request.get(
                                        "reason"
                                    ),

                                "confidence":
                                    request.get(
                                        "confidence",
                                        0
                                    ),

                                # =====================================
                                # EXISTING AZURE-STYLE CROP CONTRACT
                                # =====================================

                                "crop": {

                                    "crop_id":
                                        crop.get(
                                            "crop_id"
                                        ),

                                    "figure_id":
                                        crop.get(
                                            "figure_id"
                                        ),

                                    "x":
                                        crop.get("x"),

                                    "y":
                                        crop.get("y"),

                                    "width":
                                        crop.get("width"),

                                    "height":
                                        crop.get("height"),

                                    "purpose":
                                        crop.get(
                                            "purpose"
                                        ),

                                    "product_reference":
                                        crop.get(
                                            "product_reference"
                                        ),

                                    "confidence":
                                        crop.get(
                                            "confidence",
                                            request.get(
                                                "confidence",
                                                0
                                            )
                                        )
                                }
                            }

                            recovery_requests.append(
                                recovery_request
                            )

                            _logger.warning(
                                "[FAMILY A PARTIAL RECOVERY] "
                                "TARGET | JOB=%s | PAGE=%s | "
                                "PRODUCT=%s | COLOR=%s | "
                                "CROP=(x=%s,y=%s,w=%s,h=%s) | "
                                "CONFIDENCE=%s",

                                self.id,

                                page_number,

                                request.get(
                                    "product_reference"
                                ),

                                request.get(
                                    "color"
                                ),

                                crop.get("x"),

                                crop.get("y"),

                                crop.get("width"),

                                crop.get("height"),

                                request.get(
                                    "confidence",
                                    0
                                )
                            )

                    # =================================================
                    # SAFETY CHECK
                    # =================================================
                    _logger.warning(
                        "[FAMILY A RECOVERY BUILD RESULT] "
                        "JOB=%s | "
                        "PARTIAL_PAGES=%s | "
                        "TOTAL_REQUESTS=%s | "
                        "REQUEST_PAGES=%s",
                        self.id,
                        partial_pages,
                        len(recovery_requests),
                        sorted({
                            item.get("page")
                            for item in recovery_requests
                            if isinstance(item, dict)
                        })
                    )

                    _logger.warning(
                        "[FAMILY A RECOVERY BUILD PAYLOAD] "
                        "JOB=%s | REQUESTS=%s",
                        self.id,
                        json.dumps(
                            recovery_requests,
                            ensure_ascii=False,
                            default=str
                        )
                    )

                    pages_with_requests = {
                        item["page"]
                        for item in recovery_requests
                    }

                    pages_without_requests = sorted(
                        set(partial_pages)
                        - pages_with_requests
                    )

                    if pages_without_requests:

                        if pages_without_requests:

                            diagnostic = {
                                "partial_pages": partial_pages,
                                "pages_with_requests": sorted(
                                    pages_with_requests
                                ),
                                "pages_without_requests": (
                                    pages_without_requests
                                ),
                                "total_recovery_requests": (
                                    len(recovery_requests)
                                ),
                                "family_a_page_count": len(
                                    family_a_review.get(
                                        "pages",
                                        []
                                    )
                                )
                            }

                            _logger.error(
                                "[FAMILY A PARTIAL RECOVERY] "
                                "MISSING RECOVERY TARGETS "
                                "| JOB=%s | DIAGNOSTIC=%s",
                                self.id,
                                json.dumps(
                                    diagnostic,
                                    ensure_ascii=False,
                                    default=str
                                )
                            )

                            raise ValueError(
                                "Family A PARTIAL recovery target construction failed. "
                                f"Partial pages={partial_pages}; "
                                f"pages with requests={sorted(pages_with_requests)}; "
                                f"pages without requests={pages_without_requests}; "
                                f"total requests={len(recovery_requests)}."
                            )

                    if not recovery_requests:

                        raise ValueError(
                            "Family A partial recovery contains "
                            "no recovery requests."
                        )

                    # =================================================
                    # SAVE RECOVERY PAYLOAD
                    # =================================================

                    self.family_a_partial_recovery_json = (
                        json.dumps(
                            {
                                "decision":
                                    "READY_FOR_PRECISION_RECOVERY",

                                "partial_pages":
                                    partial_pages,

                                "recovery_requests":
                                    recovery_requests
                            },
                            ensure_ascii=False
                        )
                    )

                    self.stage_retry_count = 0
                    self.last_error = False

                    self.last_known_state = (
                        'family_a_partial_recovery'
                    )

                    # =================================================
                    # IMPORTANT
                    #
                    # DO NOT CROP YET.
                    # DO NOT SEND TO PDF AI.
                    # DO NOT SEND TO AZURE.
                    #
                    # The next implementation stage will consume
                    # family_a_partial_recovery_json.
                    # =================================================

                    self.flush_recordset()
                    self.env.cr.commit()

                    _logger.warning(
                        "[FAMILY A PARTIAL RECOVERY] "
                        "REQUESTS READY FOR PRECISION CROP "
                        "| JOB=%s | PAGES=%s | REQUESTS=%s",
                        self.id,
                        partial_pages,
                        len(recovery_requests),
                    )

                    # =========================================================
                    # EXECUTE FAMILY A PRECISION CROP
                    # =========================================================

                    _logger.warning(
                        "[FAMILY A PARTIAL RECOVERY] "
                        "STARTING PRECISION CROP "
                        "| JOB=%s",
                        self.id,
                    )

                    crop_result = (
                        self._process_precision_crop_recovery()
                    )

                    return

                except Exception as e:

                    _logger.exception(
                        "[FAMILY A PARTIAL RECOVERY] "
                        "INITIALIZATION FAILED | JOB=%s | %s",
                        self.id,
                        str(e)
                    )

                    self.stage_retry_count += 1
                    self.last_error = str(e)

                    self.last_known_state = (
                        'family_a_partial_recovery'
                    )

                    self._safe_commit_progress()

                    return


            # =============================================
            # PDF AI
            # =============================================

            if self.state == 'pdf_ai':

                try:

                    self.send_to_openai_pdf()

                except Exception as e:

                    _logger.exception(

                       f"PDF AI FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'pdf_ai'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return


                page_total = self.env[
                    'vendor.import.page'
                ].search_count([

                    ('job_id', '=', self.id)

                ])


                _logger.warning(

                    f"[PDF AI CHECK] "

                    f"{self.last_ai_page}/"

                    f"{page_total}"
                )


                if (

                    (self.last_ai_page or 0)

                    <

                    page_total

                ):

                    _logger.warning(

                        f"PDF AI CONTINUES "

                        f"→ {self.last_ai_page}/"

                        f"{page_total}"
                    )

                    self.stage_retry_count = 0

                    self.last_known_state = 'pdf_ai'

                    self.state = 'pdf_ai'

                else:

                    _logger.warning(
                        "PDF AI COMPLETE → pdf_creating"
                    )

                    self.stage_retry_count = 0

                    self.last_known_state = 'pdf_creating'
                    
                    self.state = 'pdf_creating'


                self.flush_recordset()
                self.env.cr.commit()

                return

            # =================================================
            # AZURE VISUAL REVIEW
            # =================================================

            if self.state == 'azure_review':

                _logger.warning(
                    "[AZURE REVIEW] START "
                    f"| JOB={self.id}"
                )

                self.last_known_state = 'azure_review'

                try:

                    audit_result = (
                        self._review_azure_evidence_with_openai()
                    )

                except Exception as e:

                    _logger.exception(
                        "[AZURE REVIEW] FAILED "
                        f"| {str(e)}"
                    )

                    # =============================================
                    # REAL TECHNICAL FAILURE
                    # =============================================

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'azure_review'

                    # Use the EXISTING retry/review mechanism.
                    self.state = 'review'

                    self._safe_commit_progress()

                    return

                # =================================================
                # READ AI DECISION
                # =================================================

                decision = str(
                    audit_result.get(
                        "decision",
                        "FAIL"
                    )
                ).upper()

                # =================================================
                # SAVE COMPLETE REVIEW RESULT
                # =================================================

                self.azure_review_json = json.dumps(
                    audit_result,
                    ensure_ascii=False
                )

                # =================================================
                # PASS
                # =================================================

                if decision == "PASS":

                    _logger.warning(
                        "[AZURE REVIEW] PASS "
                        "→ EXISTING PDF AI "
                        f"| JOB={self.id}"
                    )

                    self.last_known_state = 'pdf_ai'

                    self.state = 'pdf_ai'

                # =================================================
                # CROP REQUIRED
                # =================================================

                elif decision == "CROP":

                    _logger.warning(
                        "[AZURE REVIEW] CROP REQUIRED "
                        "→ AZURE CROP "
                        f"| JOB={self.id}"
                    )

                    self.azure_crop_completed = False

                    self.last_known_state = 'azure_crop'

                    self.state = 'azure_crop'

                # =================================================
                # UNKNOWN / INVALID DECISION
                # =================================================

                else:

                    _logger.warning(
                        "[AZURE REVIEW] "
                        f"INVALID DECISION={decision} "
                        f"| JOB={self.id}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = (
                        "Azure visual review returned "
                        f"invalid decision: {decision}"
                    )

                    self.last_known_state = 'azure_review'

                    self.state = 'review'

                self.flush_recordset()

                self.env.cr.commit()

                return


            # =================================================
            # AZURE IMAGE CROPPING
            # =================================================

            if self.state == 'azure_crop':

                _logger.warning(
                    "[AZURE CROP] START "
                    f"| JOB={self.id}"
                )

                self.last_known_state = 'azure_crop'

                try:

                    crop_result = (
                        self._process_azure_crop_request()
                    )

                except Exception as e:

                    _logger.exception(
                        "[AZURE CROP] FAILED "
                        f"| {str(e)}"
                    )

                    # =============================================
                    # REAL TECHNICAL FAILURE
                    # =============================================

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'azure_crop'

                    # Existing retry mechanism.
                    self.state = 'review'

                    self._safe_commit_progress()

                    return

                # =================================================
                # CROP SUCCESS
                # =================================================

                if crop_result.get(
                    "success"
                ):

                    _logger.warning(
                        "[AZURE CROP] COMPLETE "
                        "→ EXISTING PDF AI "
                        f"| JOB={self.id}"
                    )

                    self.azure_crop_completed = True

                    self.last_known_state = 'pdf_ai'

                    self.state = 'pdf_ai'

                # =================================================
                # CROP FAILURE
                # =================================================

                else:

                    _logger.warning(
                        "[AZURE CROP] FAILED "
                        f"| JOB={self.id}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = (
                        crop_result.get(
                            "error",
                            "Azure crop failed"
                        )
                    )

                    self.last_known_state = 'azure_crop'

                    self.state = 'review'

                self.flush_recordset()

                self.env.cr.commit()

                return

            # =============================================
            # PDF CREATE
            # =============================================

            if self.state == 'pdf_creating':

                try:

                    self.create_products_pdf()

                except Exception as e:

                    _logger.exception(
                        f"PDF CREATE FAILED → {str(e)}"
                    )

                    self.stage_retry_count += 1

                    self.last_error = str(e)

                    self.last_known_state = 'pdf_creating'

                    self.state = 'review'

                    self._safe_commit_progress()

                    return

                try:

                    total_ai_pages = len(
                        json.loads(
                            self.ai_response or "[]"
                        )
                    )

                except Exception:

                    total_ai_pages = 0


                if (

                    (self.last_created_page or 0)

                    <

                    total_ai_pages

                ):

                    _logger.warning(

                        f"PDF CREATE CONTINUES "

                        f"→ {self.last_created_page}/"

                        f"{total_ai_pages}"
                    )

                    self.stage_retry_count = 0

                    self.last_known_state = 'pdf_creating'
                    self.state = 'pdf_creating'

                else:

                    _logger.warning(
                        "PDF COMPLETE ✅"
                    )

                    self.stage_retry_count = 0
                    self.state = 'done'

                    if not self.completion_email_sent:

                        self.send_completion_email()


                self.flush_recordset()
                self.env.cr.commit()

                return

            
