    #========================================================
    #URL WORKFLOW
    #========================================================
    #------------parse url-----------------------------------

    def parse_url(self):

        import json

        _logger.warning(f"APIFY SCRAPE → {self.data_url}")

        raw_data = self._run_apify_actor(self.data_url)

        # =====================================================
        # APIFY STILL RUNNING
        # =====================================================

        if raw_data is None:

            _logger.warning(
                "APIFY NOT READY → WAIT NEXT CRON"
            )

            self.state = "url_scraping"

            return True

        # =====================================================
        # EMPTY RAW RESPONSE
        # =====================================================

        if not raw_data:

            _logger.error(
                "APIFY FAILED → EMPTY DATASET"
            )

            self.state = "failed"

            return

        # =====================================================
        # SAFE DEBUG LOG
        # =====================================================

        try:

            _logger.warning(
                f"RAW APIFY ITEMS → {len(raw_data)}"
            )

        except Exception:
            pass

        # =====================================================
        # HANDLE STRUCTURED RESPONSES
        # =====================================================

        first = raw_data[0] if raw_data else {}

        response_type = first.get("type")

        # =====================================================
        # BLOCKED
        # =====================================================

        if response_type == "BLOCKED":

            reason = first.get(
                "reason",
                "Unknown block detected"
            )

            status_code = first.get(
                "status_code"
            )

            _logger.error(
                f"URL BLOCKED → {reason}"
            )

            if status_code:
                _logger.error(
                    f"BLOCK STATUS CODE → {status_code}"
                )

            self.state = "failed"

            return

        # =====================================================
        # EMPTY
        # =====================================================

        if response_type == "EMPTY":

            reason = first.get(
                "reason",
                "No products extracted"
            )

            debug = first.get("debug", {})

            _logger.error(
                f"URL EXTRACTION EMPTY → {reason}"
            )

            if debug:

                _logger.error(
                    f"PAGE TITLE → {debug.get('title')}"
                )

                _logger.error(
                    f"IMAGES FOUND → {debug.get('images_found')}"
                )

                _logger.error(
                    f"LINKS FOUND → {debug.get('links_found')}"
                )

                _logger.error(
                    f"POSSIBLE PRODUCT BLOCKS → "
                    f"{debug.get('possible_product_blocks')}"
                )

                _logger.error(
                    f"COOKIE DETECTED → "
                    f"{debug.get('cookie_detected')}"
                )

                preview = debug.get(
                    'body_preview',
                    ''
                )

                _logger.error(
                    f"BODY PREVIEW → {preview[:300]}"
                )

            self.state = "failed"

            return

        # ===================================================
        # PRODUCTS
        # ===================================================

        structured_data = []

        for block in raw_data:

            # ==============================================
            # FORMAT 1 → Legacy EverythingBranded
            # ==============================================

            if block.get("text"):

                structured_data.append({

                    "text": block.get("text"),

                    "image": block.get("image")

                })

                continue

            # ==============================================
            # FORMAT 2 → Wrapped PRODUCTS
            # ==============================================

            if block.get("type") == "PRODUCTS":

                items = block.get("items", [])

                if items:

                    structured_data.extend(items)

                continue

            # ==============================================
            # FORMAT 3 → Direct Product List (NEW)
            # ==============================================

            if (

                block.get("semanticType") == "PRODUCT"

                or block.get("title")

                or block.get("url")

            ):

                structured_data.append({

                    "title":

                        block.get("title"),

                    "sku":

                        block.get("sku"),

                    "description":

                        block.get("description"),

                    "price":

                        block.get("price"),

                    "currency":

                        block.get("currency"),

                    "url":

                        block.get("url"),

                    "image":

                        block.get("image"),

                    "rawText":

                        block.get("rawText"),

                    "brand":

                        block.get("brand"),

                    "stock":

                        block.get("stock"),

                    "rating":

                        block.get("rating"),

                    "semanticType":

                        block.get("semanticType")

                })

                continue


        _logger.warning(

            "[URL PARSER] "

            f"structured_products={len(structured_data)}"

        )

        if not structured_data:

            _logger.error(
                "NO VALID PRODUCTS FOUND AFTER PARSING"
            )

            self.state = "failed"

            return


        # ============================================
        # URL BATCHING
        # ============================================

        BATCH_SIZE = 40

        start = (
            self.url_parse_index or 0
        )

        end = min(

            start + BATCH_SIZE,

            len(structured_data)
        )

        total_structured = len(structured_data)

        structured_data = structured_data[
            start:end
        ]


        _logger.warning(

            "[URL PARSE BATCH] "

            f"{start} -> {end} "

            f"| batch={len(structured_data)} "

            f"| total={total_structured}"

        )


        # =====================================================
        # NORMALIZE
        # =====================================================

        normalized = self._normalize_url_data(
            structured_data
        )

        # ============================================
        # SAVE URL PARSE PROGRESS
        # ============================================

        self.url_parse_index = end


        _logger.warning(

            f"[URL PARSE SAVE] "

            f"{self.url_parse_index}"
        )

        _logger.warning(
            f"[URL NORMALIZED COUNT] {len(normalized)}"
        )


        if not normalized:

            _logger.error(
                "NORMALIZATION FAILED → EMPTY DATA"
            )

            self.state = "failed"

            return

        # =====================================================
        # STORE SAFELY
        # =====================================================

        #payload = json.dumps(normalized)

        # 🔥 LIMIT STORAGE SIZE
        #self.extracted_text = payload[:50000]

        payload = json.dumps(normalized)

        # ============================================
        # PERSIST URL BLOCKS
        # ============================================

        self.url_blocks_json = payload

        # compatibility
        self.extracted_text = payload[:50000]


        _logger.warning(

            f"[URL STORE] "

            f"saved_blocks={len(normalized)}"
        )


        _logger.warning(
            f"APIFY DONE → {len(normalized)} ITEMS"
        )

        # =====================================================
        # MOVE TO NEXT STEP
        # =====================================================

        if self.url_parse_index >= total_structured:
            _logger.warning(
                "[URL PARSE] FINAL BATCH READY"
            )

        else:

            _logger.warning(
                "[URL PARSE] MORE BATCHES REMAIN"
            )


        self.state = "url_ai"

   
    # ===========Send to OPENAI URL =========================
    def send_to_openai_url(self):

        import re
        import json
        import math

        api_key = self.env['ir.config_parameter'].sudo().get_param('openai.api.key')

        if not api_key:
            raise Exception("OpenAI API key not configured")

        client = OpenAI(api_key=api_key)

        # ================= LOAD PAGES =================
        try:
            # pages = json.loads(self.extracted_text or "[]")

            pages = json.loads(

                self.url_blocks_json

                or

                self.extracted_text

                or

                "[]"
            )

        except Exception:
            _logger.error("INVALID extracted_text JSON")
            return

        if not pages:
            _logger.error("NO PAGES TO PROCESS")
            return

        # ================= LOAD EXISTING =================
        existing_products = []
        if self.ai_response:
            try:
                data = json.loads(self.ai_response)
                if isinstance(data, list):
                    existing_products = data
            except Exception as e:
                _logger.warning(f"AI RESPONSE LOAD FAILED → {str(e)}")
                existing_products = []

        current_batch = self.url_batch_index or 0

        # ================= FLATTEN =================
        all_blocks = [b for p in pages for b in p.get("blocks", [])]

        _logger.warning(f"RAW BLOCKS → {len(all_blocks)}")

        # ================= CLEAN =================
        cleaned_blocks = self._clean_scraped_blocks(all_blocks)

        # ==========================================
        # DEBUG REMOVED PRODUCTS
        # ==========================================

        cleaned_texts = {
            (b.get("text") or "").strip()
            for b in cleaned_blocks
        }

        removed_blocks = []

        for block in all_blocks:

            text = (block.get("text") or "").strip()

            if text not in cleaned_texts:

                removed_blocks.append(block)

        _logger.warning(
            f"[REMOVED BLOCK DETAILS] {len(removed_blocks)}"
        )

        for i, block in enumerate(removed_blocks):

            _logger.warning(

                f"[REMOVED {i+1}] "

                f"{(block.get('text') or '')[:300]}"
            )

        _logger.warning(f"CLEAN BLOCKS → {len(cleaned_blocks)}")
        _logger.warning(f"REMOVED BLOCKS → {len(all_blocks) - len(cleaned_blocks)}")

        # KEEP WEBSITE ORDER
        # cleaned_blocks = sorted(cleaned_blocks, key=lambda x: (x.get("text") or "")[:50])

        # ================= BATCH =================
        BLOCK_BATCH_SIZE = 8

        batched_blocks = [
            cleaned_blocks[i:i + BLOCK_BATCH_SIZE]
            for i in range(0, len(cleaned_blocks), BLOCK_BATCH_SIZE)
        ]

        total_batches = len(batched_blocks)
        self.url_total_batches = total_batches

        _logger.warning(f"TOTAL BLOCK BATCHES → {total_batches}")
        _logger.warning(f"CURRENT BATCH → {current_batch}")

        # ================= STOP IF DONE =================
        if current_batch >= total_batches:
            _logger.warning("ALL URL BATCHES PROCESSED ✅")
            self.state = "url_creating"
            return

        # ================= PROCESS ONE BATCH =================
        block_batch = batched_blocks[current_batch]

        _logger.warning(
            "========== AI INPUT BLOCKS =========="
        )

        for i, block in enumerate(block_batch):

            _logger.warning(

                f"[AI INPUT {i+1}]\n"

                f"{(block.get('text') or '')[:500]}"
            )

        _logger.warning(f"PROCESSING BLOCK COUNT → {len(block_batch)}")
        _logger.warning(f"AI → PROCESSING BLOCK BATCH {current_batch + 1}")

      
        combined_text = "\n\n---\n\n".join([
            f"""
            TEXT:
            {b.get('text','')}

            PRICE:
            {b.get('price','')}

            STOCK:
            {b.get('stock','')}

            IMAGE_URL:
            {b.get('image','')}
            """

            for b in block_batch
        ])


        if not combined_text.strip():
            _logger.warning("EMPTY COMBINED TEXT → SKIP")
            self.url_batch_index += 1
            return

        if len(combined_text) > 15000:
            combined_text = combined_text[:15000]
            _logger.warning("TEXT TRIMMED → PREVENT TOKEN OVERFLOW")

        # ================= PROMPT =================
        prompt = f"""
            You are a highly precise e-commerce product extraction engine.

            You are processing raw scraped website content.

            =====================================
            YOUR GOAL
            =====================================

            Extract ALL individual products from the text.

            IMPORTANT:
            - A single block may contain MULTIPLE products → you MUST split them
            - Each product MUST be returned separately
            - NEVER merge multiple products into one

            =====================================
            HOW TO IDENTIFY A PRODUCT
            =====================================

            A product usually contains:
            - product name
            - price (e.g. $, £, €, numbers)
            - specs or description
            - sometimes reviews

            Strong indicators:
            - currency symbols ($, £, €)
            - model names (Dell, Lenovo, etc.)
            - numbers like GB, inch, SSD, RAM, etc.

            =====================================
            STRICT RULES
            =====================================

            1. RETURN ONLY VALID JSON ARRAY
            2. NO explanation
            3. NO markdown
            4. NO text outside JSON

            5. EACH product must be unique
            6. REMOVE duplicates
            7. DO NOT skip products
            8. SPLIT combined text into multiple products

            =====================================
            REMOVE THIS NOISE
            =====================================

            Ignore anything related to:
            - navigation (Home, Login, Pricing)
            - cookies/privacy
            - footer text
            - categories only (no product info)
            - repeated headers

           =====================================
            VARIANT DETECTION
            =====================================

            IMPORTANT:

            Use PRODUCT IMAGES as the PRIMARY
            source for detecting variants.

            Also use:
            - product title
            - description
            - SKU
            - repeated patterns
            - packaging labels
            - text printed on product
            - visible size/capacity markings

            Detect REAL differences such as:
            - color
            - material
            - finish
            - texture
            - pattern
            - lid type
            - bottle type
            - packaging
            - shape
            - capacity
            - dimensions
            - style
            - design
            - print variation

            IMPORTANT RULES:

            1. NEVER generate:
            - Variant 1
            - Variant 2
            - Default
            - Standard
            - Option A
            - Option B

            2. ALWAYS return meaningful
            attribute names and values.

            GOOD EXAMPLES:

            {{
            "Color": "Black"
            }}

            {{
            "Material": "Bamboo"
            }}

            {{
            "Capacity": "750ml"
            }}

            {{
            "Design": "Football Print"
            }}

            {{
            "Finish": "Matte Silver"
            }}

            3. If a SINGLE IMAGE contains
            MULTIPLE product colors/designs:

            Create SEPARATE variants for EACH
            visible product variation.

            Example:
            - black bottle
            - blue bottle
            - red bottle

            MUST become:

            [
            {{
                "attributes": {{
                "Color": "Black"
                }}
            }},
            {{
                "attributes": {{
                "Color": "Blue"
                }}
            }},
            {{
                "attributes": {{
                "Color": "Red"
                }}
            }}
            ]

            4. If products differ by:
            - artwork
            - printed graphics
            - pattern
            - branding
            - sports design
            - texture

            Use:
            {{
            "Design": "..."
            }}

            5. If products differ mainly by:
            - size
            - dimensions
            - capacity

            Use:
            {{
            "Size": "..."
            }}

            OR

            {{
            "Capacity": "..."
            }}

            6. NEVER invent attributes that
            cannot be visually or textually
            supported.

            7. If uncertainty exists:
            Prefer:
            - Color
            - Design
            - Material
            - Capacity

            based on strongest visible evidence.

            8. If NO meaningful difference exists:
            Return ONE variant only.

            9. IMPORTANT:
            When multiple products appear in
            one image, treat each visible
            variation as a separate variant,
            even if no explicit text exists.

            10. Preserve consistency across
            all variants for the same product.

            BAD EXAMPLE:
            [
            {{
                "attributes": {{
                "Variant": "Variant 1"
                }}
            }}
            ]

            GOOD EXAMPLE:
            [
            {{
                "attributes": {{
                "Color": "White"
                }}
            }},
            {{
                "attributes": {{
                "Color": "Black"
                }}
            }}
            ]


            =====================================
            OUTPUT FORMAT
            =====================================

            [
                {{
                    "name": "Clean product name",
                    "description": "Short product description (max 30 words)",
                    "category": "Best guess category",
                    "price": "",
                    "stock": "",
                    "image": "image_url_or_null",
                    "variants": [
                                {{
                                    "attributes": {{
                                        "Variant": ""
                                    }},
                                    "image_index": 0,
                                    "stock": null
                                }}
                            ]
                }}
            ]

            =====================================
            EXTRA RULES
            =====================================

            - Keep names SHORT and CLEAN
            - Description must be concise
            - Infer category intelligently
            - If no image exists → return null
            - If price exists → extract it
            - If stock exists → extract it
            - NEVER invent stock or price
            - If unsure → still extract

            =====================================
            TEXT TO PROCESS
            =====================================

        {combined_text}
        """

        # ================= OPENAI =================
        try:
            response = client.responses.create(
                model="gpt-4.1-mini",
                input=prompt,
                temperature=0,
                timeout=60
            )

            result = response.output_text.strip()
            result = re.sub(r"^```(?:json)?|```$", "", result).strip()

            parsed = json.loads(result)

            _logger.warning(
                "[RAW AI OUTPUT]\n%s"

                % json.dumps(
                    parsed,
                    indent=4,
                    default=str
                )
            )

            if isinstance(parsed, list):

                cleaned = [p for p in parsed if p.get("name")]

                _logger.warning(f"AI RETURNED → {len(cleaned)} PRODUCTS")

                # 🔥 DEDUPE BY NAME
                existing_map = {p.get("name"): p for p in existing_products}

                for p in cleaned:
                    existing_map[p.get("name")] = p

                existing_products = list(existing_map.values())

                _logger.warning(f"TOTAL ACCUMULATED → {len(existing_products)}")

            else:
                _logger.warning("AI RESPONSE NOT LIST")

        except Exception as e:
            _logger.warning(f"AI ERROR → {str(e)}")
            return

        # ================= SAVE =================
        self.ai_response = json.dumps(existing_products)
        self.url_batch_index = current_batch + 1

        _logger.warning(f"URL AI PROGRESS → {self.url_batch_index}/{self.url_total_batches}")

        # ================= STATE =================
        if self.url_batch_index < self.url_total_batches:
            self.state = "url_ai"
        else:
            _logger.warning("URL AI FINISHED ALL BATCHES")
            self.state = "url_creating"

        # 🔥 IMPORTANT: COMMIT FOR CRON CONTINUITY

        try:

            self.env.cr.commit()

        except Exception as commit_error:

            _logger.warning(
                f"COMMIT SKIPPED → {commit_error}"
            )

        return

    
    # ================= PRODUCT CREATION URL ================

    def create_products_url(self):

        import requests
        import base64
        import json

        if not self.ai_response:
            _logger.warning("NO AI RESPONSE")
            return

        product_obj = self.env['product.template']
        category_obj = self.env['product.category']

        try:
            products = json.loads(self.ai_response)

            if isinstance(products, dict):
                products = [products]

        except Exception as e:
            _logger.error(f"INVALID AI JSON → {str(e)}")
            return

        TOTAL_PRODUCTS = len(products)
        start_index = self.last_processed_product_index or 0

        _logger.warning(f"TOTAL AI PRODUCTS → {TOTAL_PRODUCTS}")
        _logger.warning(f"START INDEX → {start_index}")

        created_count = 0
        skipped_count = 0

        MAX_PRODUCTS_PER_RUN = 5

        vendor_id =  self.partner_id.id if self.partner_id else self.env.user.partner_id.id

        end_index = min(start_index + MAX_PRODUCTS_PER_RUN, TOTAL_PRODUCTS)

        _logger.warning(f"PROCESSING RANGE → {start_index} to {end_index}")

        for idx in range(start_index, end_index):

            product_data = products[idx]

            name = product_data.get("name")
            if not name:
                skipped_count += 1
                continue

            description = product_data.get("description", "")
            raw_category = str(

                product_data.get("category") or ""

            ).lower()

            # ================= CATEGORY =================
            mapped_category = self._map_product_category(
                raw_category
            )

            category = self._get_or_create_product_category(
                mapped_category,
                source="url"
            )

            # ================= FINGERPRINT=================

            variant_group = (

                product_data.get("variant_group")

                or

                name
            )

            variant_group = str(
                variant_group
            ).strip().upper()


            vendor_fingerprint = (
                f"{vendor_id}_{variant_group}"
            )


            # ================= DUPLICATE CHECK =================

            existing = product_obj.search([

                (
                    'vendor_fingerprint',
                    '=',
                    vendor_fingerprint
                )

            ], limit=1)


            if existing:

                _logger.warning(

                    f"[URL DUPLICATE SKIP] "

                    f"{vendor_fingerprint}"
                )

                skipped_count += 1

                continue


            currency = self._resolve_catalogue_currency(

                extracted_currency=
                    product_data.get(
                        "currency"
                    ),

                price_text=
                    str(
                        product_data.get(
                            "price",
                            ""
                        )
                    ),

            )


            vals = {
                'name': name.strip(),
                'description_sale': description,
                'type': 'consu',
                'categ_id': category.id,
                'sale_ok': True,
                'website_published': False,
                'vendor_id': vendor_id,
                'vendor_fingerprint': vendor_fingerprint,
                "vendor_currency_id": currency.id,
                'vendor_import_job_id': self.id,
            }

            # ================= IMAGE =================
            image_url = product_data.get("image")

            if image_url and isinstance(image_url, str) and image_url.startswith("http"):

                try:
                    _logger.warning(f"FETCHING IMAGE → {image_url}")

                    res = requests.get(image_url, timeout=5, stream=True)

                    if res.status_code != 200:
                        _logger.warning(f"IMAGE HTTP ERROR → {res.status_code}")
                        continue

                    content_type = res.headers.get("Content-Type", "")
                    if "image" not in content_type:
                        _logger.warning(f"NOT AN IMAGE → {content_type}")
                        continue

                    content = res.raw.read(500000, decode_content=True)

                    if not content:
                        _logger.warning("EMPTY IMAGE CONTENT")
                        continue

                    vals['image_1920'] = base64.b64encode(content).decode("utf-8")

                    _logger.warning("IMAGE STORED SUCCESSFULLY")

                except Exception as e:
                    _logger.warning(f"IMAGE FAILED → {str(e)}")

            else:
                _logger.warning(f"NO VALID IMAGE URL → {image_url}")

            # ================= CREATE =================
            try:
                _logger.warning(
                    f"[URL CREATE PRODUCT] → "
                    f"NAME={name} | "
                    f"VENDOR_ID={vendor_id}"
                )

                # product_obj.create(vals)
                product = product_obj.with_context(
                    mail_create_nolog=True,
                    mail_notify_force_send=False,
                    tracking_disable=True
                ).create(vals)

                #========apply translation==============
                self._apply_product_translation(product)

                #====apply currency conversion================
                product._update_converted_price()

                # =========================================
                # URL VARIANTS
                # =========================================

                variants = product_data.get(
                    "variants",
                    []
                )


                # =========================================
                # FALLBACK VARIANT
                # =========================================

                if not variants:

                    variants = [{

                        "attributes": {

                            "Variant": name
                        }

                    }]


                # =========================================
                # PROCESS VARIANTS
                # =========================================

                for variant in variants:

                    attributes = variant.get(
                        "attributes",
                        {}
                    )


                    for attr_name, attr_value in attributes.items():


                        if not attr_value:
                            continue


                        attr_value = str(attr_value).strip()


                        # =====================================
                        # NORMALIZE BAD VARIANTS
                        # =====================================

                        bad_variants = [

                            'variant 1',

                            'variant 2',

                            'variant 3',

                            'default',

                            'option a',

                            'option b'
                        ]


                        if attr_value.lower() in bad_variants:

                            attr_name = "Design"

                            attr_value = name


                        # =====================================
                        # ATTRIBUTE
                        # =====================================

                        attribute = self.env[
                            'product.attribute'
                        ].search([

                            ('name', '=', attr_name)

                        ], limit=1)

                        # =====================================
                        # TRANSLATE ATTRIBUTE NAME
                        # =====================================

                        try:

                            for lang_code in [

                                'ru_RU',

                                'az_AZ'
                            ]:

                                translated_attr = self._force_translate(

                                    str(attr_name),

                                    lang_code
                                )


                                if translated_attr:

                                    attribute.with_context(
                                        lang=lang_code
                                    ).write({

                                        'name': translated_attr
                                    })


                                    _logger.warning(

                                        f"[URL ATTRIBUTE TRANSLATED] "

                                        f"{attr_name} "

                                        f"-> "

                                        f"{translated_attr} "

                                        f"({lang_code})"
                                    )

                        except Exception as e:

                            _logger.warning(

                                f"[URL ATTRIBUTE TRANSLATION ERROR] "

                                f"{str(e)}"
                            )


                        if not attribute:

                            attribute = self.env[
                                'product.attribute'
                            ].create({

                                'name': attr_name
                            })


                        # =====================================
                        # ATTRIBUTE VALUE
                        # =====================================

                        value = self.env[
                            'product.attribute.value'
                        ].search([

                            ('name', '=', attr_value),

                            (
                                'attribute_id',
                                '=',
                                attribute.id
                            )

                        ], limit=1)


                        if not value:

                            value = self.env[
                                'product.attribute.value'
                            ].create({

                                'name': attr_value,

                                'attribute_id':
                                    attribute.id
                            })


                            # =================================
                            # TRANSLATE VARIANT VALUE
                            # =================================

                            try:

                                for lang_code in [

                                    'ru_RU',

                                    'az_AZ'
                                ]:

                                    translated_variant = (

                                        self._force_translate(

                                            str(attr_value),

                                            lang_code
                                        )
                                    )


                                    if translated_variant:

                                        value.with_context(
                                            lang=lang_code
                                        ).write({

                                            'name':
                                                translated_variant
                                        })


                                        _logger.warning(

                                            f"[URL VARIANT TRANSLATED] "

                                            f"{attr_value} "

                                            f"-> "

                                            f"{translated_variant} "

                                            f"({lang_code})"
                                        )

                            except Exception as e:

                                _logger.warning(

                                    f"[URL VARIANT TRANSLATION ERROR] "

                                    f"{str(e)}"
                                )


                        # =====================================
                        # ATTRIBUTE LINE
                        # =====================================

                        line = self.env[
                            'product.template.attribute.line'
                        ].search([

                            (
                                'product_tmpl_id',
                                '=',
                                product.id
                            ),

                            (
                                'attribute_id',
                                '=',
                                attribute.id
                            )

                        ], limit=1)


                        if not line:

                            self.env[
                                'product.template.attribute.line'
                            ].create({

                                'product_tmpl_id':
                                    product.id,

                                'attribute_id':
                                    attribute.id,

                                'value_ids': [(6, 0, [

                                    value.id

                                ])]
                            })

                        else:

                            if (

                                value.id

                                not in

                                line.value_ids.ids

                            ):

                                line.value_ids = [

                                    (4, value.id)

                                ]
               

                # =========================================
                # GENERATE VARIANTS
                # =========================================

                product._create_variant_ids()

                product.flush_recordset()

                product.invalidate_recordset()

                # =========================================
                # FINALIZE PRODUCT
                # =========================================

                try:

                    product.finalize_product()

                    _logger.warning(

                        "[PRODUCT FINALIZED] "

                        "product=%s",

                        product.display_name,

                    )

                except Exception:

                    _logger.exception(

                        "[PRODUCT FINALIZE FAILED] "

                        "product=%s",

                        product.display_name,

                    )

                created_count += 1

            except Exception as e:
                _logger.error(f"CREATE FAILED → {name} | {str(e)}")
                skipped_count += 1
                continue

            if created_count % 10 == 0:
                self._safe_commit_progress()

        # ================= SAVE PROGRESS =================
        self.last_processed_product_index = end_index

        _logger.warning(f"CREATED THIS RUN → {created_count}")
        _logger.warning(f"SKIPPED THIS RUN → {skipped_count}")
        _logger.warning(f"NEXT START INDEX → {self.last_processed_product_index}")

        if self.last_processed_product_index >= TOTAL_PRODUCTS:
            _logger.warning("ALL PRODUCTS CREATED ✅")
            self.state = "done"
        else:
            _logger.warning("MORE PRODUCTS REMAIN → CONTINUE CREATION")
            self.state = "url_creating"

        self._safe_commit_progress()

    #==============URL API FLOW====================================

    def scrape_with_playwright(self):

        from playwright.sync_api import sync_playwright
        import subprocess
        import os

        _logger.warning(f"PLAYWRIGHT SCRAPE → {self.data_url}")

        #✅ CHECK IF BROWSER EXISTS FIRST
        browser_path = os.path.expanduser("~/.cache/ms-playwright")

        if not os.path.exists(browser_path):
            _logger.warning("PLAYWRIGHT → INSTALLING BROWSER (FIRST RUN)")

            try:
                subprocess.run(
                    ["python", "-m", "playwright", "install", "chromium"],
                    check=True
                )
                _logger.warning("PLAYWRIGHT BROWSER INSTALLED")
            except Exception as e:
                _logger.error(f"PLAYWRIGHT INSTALL FAILED → {str(e)}")
                return

        products = []

        with sync_playwright() as p:

            browser = p.chromium.launch(headless=True)
            page = browser.new_page()

            page.goto(self.data_url, timeout=60000)
            page.wait_for_timeout(5000)

            # ✅ Cookie handling
            try:
                page.locator("button:has-text('Accept')").click(timeout=3000)
            except:
                pass

            items = page.query_selector_all("a, div")

            _logger.warning(f"PLAYWRIGHT ELEMENTS FOUND → {len(items)}")

            for item in items[:200]:

                try:
                    text = item.inner_text().strip()

                    if not text or len(text) < 5:
                        continue

                    img_el = item.query_selector("img")
                    img_url = img_el.get_attribute("src") if img_el else None

                    if img_url and img_url.startswith("//"):
                        img_url = "https:" + img_url

                    img_base64 = None

                    if img_url:
                        try:
                            res = requests.get(img_url, timeout=10)
                            if res.status_code == 200:
                                img_base64 = base64.b64encode(res.content).decode("utf-8")
                        except:
                            pass

                    products.append({
                        "name": text[:120],
                        "image": img_base64
                    })

                except:
                    continue

            browser.close()

        _logger.warning(f"PLAYWRIGHT PRODUCTS → {len(products)}")

        if not products:
            _logger.error("PLAYWRIGHT FAILED → NO PRODUCTS")
            return

        pages = [{
            "page": 1,
            "text": "\n".join([p["name"] for p in products]),
            "images": [p["image"] for p in products if p["image"]]
        }]

        self.extracted_text = json.dumps(pages)

        _logger.warning(f"PLAYWRIGHT DONE → {len(products)} PRODUCTS")

    
    #======apify url fetch/scrapp products=========================
    
    def _run_apify_actor(self, url):

        token = self.env['ir.config_parameter'].sudo().get_param('apify.api_token')

        _logger.warning(
            f"[APIFY DEBUG] "
            f"url={url} | "
            f"run_id={self.apify_run_id} | "
            f"dataset_id={self.apify_dataset_id}"
        )

        if not token:
            raise Exception("Apify API token not configured")

        ACTOR_ID = "selectad~my-actor"
        #ACTOR_ID = "princ_adex~my-actor"

        # ===========================================================
        # 🔥 STEP 1: START ACTOR (ONLY IF NOT STARTED)
        # ==========================================================

        if not getattr(self, "apify_run_id", False):

            run_url = f"https://api.apify.com/v2/acts/{ACTOR_ID}/runs?token={token}"

            payload = {
                "startUrls": [{"url": url}]
            }

            _logger.warning(
                f"[APIFY START PAYLOAD] {payload}"
            )

            headers = {
                "Content-Type": "application/json"
            }

            response = requests.post(run_url, json=payload, headers=headers, timeout=30)

            if response.status_code != 201:
                raise Exception(f"Apify run failed: {response.text}")

            run_data = response.json()
 
            _logger.warning(
                f"[APIFY RUN CREATED] "
                f"url={url} | "
                f"run_id={run_data['data']['id']} | "
                f"dataset={run_data['data']['defaultDatasetId']}"
            )

            # ✅ SAVE FOR NEXT CRON
            self.apify_run_id = run_data["data"]["id"]
            self.apify_dataset_id = run_data["data"]["defaultDatasetId"]

            _logger.warning(f"APIFY STARTED → RUN ID {self.apify_run_id}")

            # 🔥 IMPORTANT: STOP HERE (NON-BLOCKING)

            _logger.warning(
                f"[APIFY WAITING] "
                f"url={url} "
                f"| run_id={self.apify_run_id}"
            )
            return None

        # =====================================================
        # 🔥 STEP 2: CHECK STATUS
        # =====================================================

        status_url = f"https://api.apify.com/v2/actor-runs/{self.apify_run_id}?token={token}"

        status_res = requests.get(status_url, timeout=20).json()
        status = status_res["data"]["status"]

        _logger.warning(f"APIFY STATUS → {status}")

        if status in ["RUNNING", "READY"]:
            _logger.warning("APIFY STILL RUNNING → WAIT NEXT CRON")
            return None

        if status in ["FAILED", "ABORTED", "TIMED-OUT"]:
            raise Exception(f"Apify run failed with status: {status}")

        # =====================================================
        # 🔥 STEP 3: FETCH DATA (ONLY WHEN DONE)
        # =====================================================

        dataset_url = f"https://api.apify.com/v2/datasets/{self.apify_dataset_id}/items"

        params = {
            "token": token,
            "limit": 1000,
            "clean": "true"
        }

        dataset_res = requests.get(dataset_url, params=params, timeout=30)

        if dataset_res.status_code != 200:
            raise Exception(f"Failed to fetch dataset: {dataset_res.text}")


        data = dataset_res.json()
        
        _logger.warning(
            f"[APIFY DATASET FETCH] "
            f"url={url} | "
            f"run_id={self.apify_run_id} | "
            f"dataset={self.apify_dataset_id}"
        )

        _logger.warning(

            f"[APIFY DATASET RETURN] "

            f"url={url} | "

            f"dataset_id={self.apify_dataset_id} | "

            f"items={len(data)}"
        )

        if data:

            _logger.warning(

                "[APIFY FIRST RECORD]\n%s"

                % json.dumps(
                    data[0],
                    indent=4,
                    default=str
                )
            )

        _logger.warning(
            f"APIFY ITEMS FETCHED → {len(data)}"
        )

        
        # =====================================================
        # APIFY COMPLETED BUT RETURNED NO DATA
        # =====================================================
        #
        # Apify has already completed successfully, but the
        # dataset contains zero records.
        #
        # This is NOT "waiting for Apify".
        # This is a terminal URL extraction failure.
        #
        # IMPORTANT:
        # Do not return True here because the caller uses True
        # to mean "Apify is still processing".
        # =====================================================

        if not data:

            _logger.error(
                "[APIFY EMPTY DATASET] "
                "TERMINAL FAILURE "
                "| JOB=%s "
                "| URL=%s "
                "| RUN_ID=%s "
                "| DATASET_ID=%s "
                "| STATUS=SUCCEEDED "
                "| ITEMS=0",
                self.id,
                url,
                self.apify_run_id,
                self.apify_dataset_id,
            )

            self.last_error = (
                "Apify completed successfully but returned "
                "0 dataset items."
            )

            self.last_known_state = (
                'url_scraping'
            )

            self.state = (
                'failed'
            )

            self._safe_commit_progress()

            return False

    # =========== PDF OPENAI BACKUP ================================
    
    def send_to_openai_pdf(self):

        import json

        api_key = self.env[
            'ir.config_parameter'
        ].sudo().get_param(
            'openai.api.key'
        )

        if not api_key:

            raise Exception(
                "OpenAI API key not configured"
            )

        client = OpenAI(
            api_key=api_key
        )


        _logger.warning(
            "[PDF AI] START"
        )


        # =====================================================
        # LOAD PAGE RECORDS
        # =====================================================

        page_records = self.env[
            'vendor.import.page'
        ].search([

            ('job_id', '=', self.id)

        ], order='page_number asc')


        total_available_pages = len(
            page_records
        )


        _logger.warning(

            f"[PDF AI] "

            f"TOTAL PAGE RECORDS="

            f"{total_available_pages}"
        )


        if total_available_pages <= 0:

            _logger.warning(
                "[PDF AI] "
                "NO PAGE RECORDS FOUND"
            )

            return


        # =====================================================
        # LOAD EXISTING AI RESPONSE
        # =====================================================

        existing_pages = []


        if self.ai_response:

            try:

                loaded = json.loads(
                    self.ai_response
                )

                if isinstance(
                    loaded,
                    list
                ):

                    existing_pages = loaded


            except Exception as e:

                _logger.warning(

                    f"[PDF AI] "

                    f"LOAD EXISTING FAILED "

                    f"| {str(e)}"
                )

                existing_pages = []


        # =====================================================
        # FIND ALREADY PROCESSED PAGES
        # =====================================================

        processed_pages = set()


        for p in existing_pages:

            page_num = p.get("page")

            if page_num:

                processed_pages.add(
                    page_num
                )


        _logger.warning(

            f"[PDF AI] "

            f"PROCESSED PAGES="

            f"{sorted(list(processed_pages))}"
        )


        # =====================================================
        # FIND NEXT UNPROCESSED PAGE
        # =====================================================

        next_record = None


        for record in page_records:

            if (

                record.page_number

                not in processed_pages

            ):

                next_record = record

                break


        # =====================================================
        # ALL COMPLETE
        # =====================================================

        if not next_record:

            _logger.warning(
                "[PDF AI] COMPLETE ✅"
            )

            self.last_ai_page = (
                total_available_pages
            )

            self.state = "pdf_creating"

            self.flush_recordset()

            self.env.cr.commit()

            return


        _logger.warning(

            f"[PDF AI] "

            f"PROCESSING PAGE "

            f"{next_record.page_number}"
        )


        # =====================================================
        # LOAD PAGE DATA
        # =====================================================

        try:

            page_blocks = json.loads(

                next_record.extracted_json
                or
                "[]"
            )

            page_image = ""
            page_width = 0
            page_height = 0

            page_text = ""

            for block in page_blocks:

                if block.get("text"):
                    page_text = (
                        block.get("text") or ""
                    ).strip()

                    # if page_text:
                    #     break

                    if page_text:
                        _logger.warning(
                            "[AI PAGE TEXT] "
                            "PAGE=%s | EXISTS=%s | LENGTH=%s",
                            next_record.page_number,
                            bool(page_text),
                            len(page_text)
                        )

                        _logger.warning(
                            "[AI PAGE TEXT SAMPLE] PAGE=%s\n%s",
                            next_record.page_number,
                            page_text[:2000]
                        )

                        break


            for block in page_blocks:

                if block.get("page_image"):

                    page_image = block.get(
                        "page_image"
                    )

                    page_width = block.get(
                        "page_width",
                        0
                    )

                    page_height = block.get(
                        "page_height",
                        0
                    )

                    _logger.warning(
                        f"[AI PAGE IMAGE] "
                        f"exists={bool(page_image)} "
                        f"size={len(page_image) if page_image else 0} "
                        f"width={page_width} "
                        f"height={page_height}"
                    )

                    break

            for block in page_blocks:

                imgs = block.get("images", [])

                if imgs:

                    sample = imgs[0]

                    # if isinstance(sample, dict):
                    if isinstance(sample, dict):

                        _logger.warning(
                            f"[EXTRACTED IMAGE SAMPLE] "
                            f"keys={list(sample.keys())}"
                        )

                        _logger.warning(
                            f"[EXTRACTED IMAGE VALUES] "
                            f"width={sample.get('width')} "
                            f"height={sample.get('height')} "
                            f"x={sample.get('x')} "
                            f"y={sample.get('y')} "
                            f"lifestyle={sample.get('is_lifestyle')} "
                            f"hero={sample.get('hero_score')} "
                            f"gallery={sample.get('gallery_score')}"
                        )

                        
                    break

        except Exception as e:

            _logger.warning(

                f"[PDF AI] "

                f"PAGE LOAD FAILED "

                f"| PAGE "

                f"{next_record.page_number} "

                f"| {str(e)}"
            )

            return


        if not page_blocks:

            _logger.warning(

                f"[PDF AI] "

                f"EMPTY PAGE BLOCKS "

                f"| PAGE "

                f"{next_record.page_number}"
            )

            return


        # =====================================================
        # BUILD PAGE IMAGE ASSET POOL
        # =====================================================

        page_images = []

        # =====================================================
        # 1. LOAD ORIGINAL EXTRACTED IMAGES
        # =====================================================

        for p in page_blocks:

            raw_images = p.get(
                "images",
                []
            )

            # =====================================
            # NORMALIZE STRUCTURED ASSETS
            # =====================================

            for img in raw_images:

                if isinstance(img, dict):

                    if img.get("image"):

                        page_images.append(
                            img
                        )

                elif isinstance(img, str):

                    page_images.append({

                        "image": img,

                        "score": 0,

                        "is_collage": False
                    })


        persisted_assets = []

        try:

            persisted_assets = json.loads(
                next_record.page_images_json
                or "[]"
            )

        except Exception as e:

            _logger.warning(
                "[PDF AI] PAGE IMAGE JSON LOAD FAILED "
                "| JOB=%s "
                "| PAGE=%s "
                "| ERROR=%s",
                self.id,
                next_record.page_number,
                str(e)
            )

            persisted_assets = []


        if not isinstance(
            persisted_assets,
            list
        ):

            _logger.warning(
                "[PDF AI] PERSISTED ASSETS INVALID TYPE "
                "| JOB=%s "
                "| PAGE=%s "
                "| TYPE=%s",
                self.id,
                next_record.page_number,
                type(persisted_assets).__name__
            )

            persisted_assets = []


        _logger.warning(
            "[PDF AI] PERSISTED ASSETS LOADED "
            "| JOB=%s "
            "| PAGE=%s "
            "| COUNT=%s",
            self.id,
            next_record.page_number,
            len(persisted_assets)
        )


        # =========================================================
        # CLASSIFY PERSISTED RECOVERY ASSETS
        # =========================================================

        azure_crop_assets = []

        family_a_precision_crop_assets = []


        for asset in persisted_assets:

            if not isinstance(
                asset,
                dict
            ):
                continue

            if not asset.get(
                "image"
            ):
                continue


            # -----------------------------------------
            # AZURE RECOVERY
            # -----------------------------------------

            if asset.get(
                "azure_crop"
            ) is True:

                azure_crop_assets.append(
                    asset
                )

                continue


            # -----------------------------------------
            # FAMILY A PRECISION RECOVERY
            # -----------------------------------------

            if asset.get(
                "family_a_precision_crop"
            ) is True:

                family_a_precision_crop_assets.append(
                    asset
                )


        _logger.warning(
            "[PDF AI] PERSISTED RECOVERY ASSETS "
            "| JOB=%s "
            "| PAGE=%s "
            "| AZURE=%s "
            "| FAMILY_A_PRECISION=%s",
            self.id,
            next_record.page_number,
            len(azure_crop_assets),
            len(family_a_precision_crop_assets)
        )


        for asset in azure_crop_assets:

            _logger.warning(
                "[PDF AI] AZURE CROP META "
                "| PAGE=%s "
                "| CROP=%s "
                "| PRODUCT=%s "
                "| COLOR=%s "
                "| FIGURE=%s "
                "| PURPOSE=%s "
                "| CLEAN_INDEX=%s",
                next_record.page_number,
                asset.get(
                    "crop_id"
                ),
                asset.get(
                    "product_reference"
                ),
                asset.get(
                    "color"
                ),
                asset.get(
                    "figure_id"
                ),
                asset.get(
                    "purpose"
                ),
                asset.get(
                    "clean_index"
                )
            )


        # =====================================================
        # 3. ADD PERSISTED RECOVERY ASSETS
        # =====================================================

        for asset in azure_crop_assets:

            page_images.append(
                asset
            )


        for asset in family_a_precision_crop_assets:

            page_images.append(
                asset
            )


        _logger.warning(
            "[PDF AI] RECOVERY ASSETS APPENDED "
            "| PAGE=%s "
            "| AZURE=%s "
            "| FAMILY_A_PRECISION=%s "
            "| TOTAL_PAGE_ASSETS=%s",
            next_record.page_number,
            len(azure_crop_assets),
            len(family_a_precision_crop_assets),
            len(page_images)
        )

        _logger.warning(
            "[PDF AI] COMBINED PAGE ASSETS "
            "| PAGE=%s "
            "| ORIGINAL=%s "
            "| AZURE_CROPS=%s "
            "| FAMILY_A_PRECISION=%s "
            "| TOTAL=%s",
            next_record.page_number,
            (
                len(page_images)
                - len(azure_crop_assets)
                - len(family_a_precision_crop_assets)
            ),
            len(azure_crop_assets),
            len(family_a_precision_crop_assets),
            len(page_images)
        )

        # =====================================================
        # VALIDATE PAGE IMAGES
        # =====================================================

        valid_page_images = []

        for asset in page_images:

            try:

                # segmented assets are now dicts
                if isinstance(asset, dict):

                    image_data = asset.get(
                        "image"
                    )

                else:

                    image_data = asset

                if not image_data:
                    continue

                if not self._is_valid_ai_image(
                    image_data
                ):

                    _logger.warning(

                        f"[PDF AI] INVALID IMAGE "

                        f"| PAGE "

                        f"{next_record.page_number}"
                    )

                    continue

                valid_page_images.append(
                    asset
                )

            except Exception as e:

                _logger.warning(

                    f"[PDF AI IMAGE ERROR] "

                    f"{str(e)}"
                )

        page_images = valid_page_images
        # =========================================
        # REBUILD CLEAN IMAGE INDEX MAP
        # =========================================

        normalized_page_images = []

        for idx, asset in enumerate(page_images):

            if isinstance(asset, dict):

                asset["clean_index"] = idx

                normalized_page_images.append(asset)


        page_images = normalized_page_images

        # =========================================================
        # BUILD STRUCTURED IMAGE ASSET IDENTITY MAP
        # =========================================================

        asset_identity_lines = []

        for asset in page_images:

            if not isinstance(
                asset,
                dict
            ):
                continue

            clean_index = asset.get(
                "clean_index"
            )

            if clean_index is None:
                continue

            azure_figure_id = (
                asset.get(
                    "azure_figure_id"
                )
                or ""
            )

            crop_id = (
                asset.get(
                    "crop_id"
                )
                or ""
            )

            product_reference = (
                asset.get(
                    "product_reference"
                )
                or ""
            )

            dominant_color = (
                asset.get(
                    "dominant_color"
                )
                or ""
            )

            image_role = (
                asset.get(
                    "role"
                )
                or asset.get(
                    "image_role"
                )
                or ""
            )

            azure_caption = (
                asset.get(
                    "azure_caption"
                )
                or ""
            )

            asset_identity_lines.append(
                f"""
                INDEX {clean_index}
                - Azure Figure ID: {azure_figure_id}
                - Crop ID: {crop_id}
                - Product Reference: {product_reference}
                - Color: {dominant_color}
                - Image Role: {image_role}
                - Azure Caption: {azure_caption}
                """.strip()
            )

        asset_identity_map = "\n\n".join(
            asset_identity_lines
        )

        _logger.warning(
            "[PDF AI ASSET IDENTITY MAP] "
            "PAGE=%s\n%s",
            next_record.page_number,
            asset_identity_map
        )

        # =====================================
        # CLASSIFY IMAGES BEFORE AI
        # =====================================

        if page_images:

            sample = page_images[0]

            _logger.warning(
                f"[AI SAVE IMAGE SAMPLE] "
                f"keys={list(sample.keys())}"
            )

            _logger.warning(
                f"[AI SAVE IMAGE DATA] "
                f"width={sample.get('width')} "
                f"height={sample.get('height')} "
                f"x={sample.get('x')} "
                f"y={sample.get('y')} "
                f"lifestyle={sample.get('is_lifestyle')} "
                f"hero={sample.get('hero_score')} "
                f"gallery={sample.get('gallery_score')}"
            )


        # =====================================
        # NO VALID IMAGE FAILSAFE
        # =====================================

        if not page_images:

            _logger.warning(

                f"[PDF NO VALID IMAGE] "

                f"PAGE={next_record.page_number}"
            )

            existing_map = {}

            for p in existing_pages:

                existing_map[
                    p.get("page")
                ] = p



            existing_map[
                next_record.page_number
            ] = {
                "page": next_record.page_number,

                "products": [],

                "images": [],

                "failed": True,

                "reason": "no_valid_images",

                "page_image": page_image,

                "page_width": page_width,

                "page_height": page_height
            }

            combined_pages = sorted(

                list(existing_map.values()),

                key=lambda x: x.get(
                    "page",
                    0
                )
            )

            self.ai_response = json.dumps(
                combined_pages
            )

            self.last_ai_page = len(
                combined_pages
            )

            self.state = "pdf_ai"

            self.flush_recordset()

            self.env.cr.commit()

            return

        # =====================================================
        # PRE-AI VALIDATION / RECOVERY
        # =====================================================

        page_data = {
            "page": next_record.page_number,
            "products": [],
            "images": page_images,
            "page_image": page_image,
            "page_width": page_width,
            "page_height": page_height,
            "text": page_text,
        }

        # family = self._prepare_product_family(
        #     product_data,
        #     asset_pool,
        #     page_data
        # )

        validation = self._validate_extraction_quality(
            page_data
        )

        page_data["validation"] = validation

        page_data["recovery_required"] = (
            not validation["passed"]
        )

        _logger.warning(
            f"[VALIDATION] "
            f"passed={validation['passed']} "
            f"score={validation['score']} "
            f"reasons={validation['reasons']}"
        )

        if page_data["recovery_required"]:

            _logger.warning(
                "[RECOVERY REQUIRED]"
            )

            
            recovery = self._ai_catalogue_recovery(
                page_data
            )

            if recovery:

                old_count = len(page_images)

                page_images = recovery.get(
                    "images",
                    page_images
                )

                for idx, asset in enumerate(page_images):

                    if isinstance(asset, dict):

                        asset["clean_index"] = idx

                page_images = self._prepare_asset_intelligence(

                    page_images
                )

                page_images = self._prepare_render_assets(

                    page_images
                )

                validation = self._validate_extraction_quality(

                    page_data
                )

                page_data["validation"] = validation

                page_data["recovery_required"] = (

                    not validation["passed"]
                )

                _logger.warning(
                    f"[RECOVERY APPLIED] "
                    f"old_images={old_count} "
                    f"new_images={len(page_images)}"
                )

        # =====================================
        # BUILD AI PAGE CONTEXT
        # =====================================

        page_data["images"] = page_images

        page_context = self._build_ai_page_context(

            page_data,

            validation
        )

        page_data["page_context"] = page_context

        _logger.warning(

            f"[AI CONTEXT READY] "

            f"page={page_context.get('page')} "

            f"real={page_context.get('real_products')} "

            f"demo={page_context.get('product_demo')} "

            f"life={page_context.get('lifestyle')} "

            f"recovery={page_context.get('requires_recovery')}"
        )

        # =====================================================
        # FAMILY A AUTHORITATIVE ASSET CONTEXT FOR PDF AI
        # =====================================================
        #
        # Family A has already reviewed these extracted assets.
        # Its classification/role decision is authoritative.
        #
        # IMPORTANT:
        # We do NOT replace the existing page_images.
        # We only provide Family A's authoritative decisions
        # to PDF AI as structured context.
        # =====================================================

        family_a_authority = []

        try:
            family_a_review = json.loads(
                self.family_a_review_json
                or "{}"
            )

            current_page_number = int(
                next_record.page_number
            )

            family_a_pages = (
                family_a_review.get("pages", [])
                if isinstance(
                    family_a_review,
                    dict
                )
                else []
            )

            current_family_a_page = None

            for review_page in family_a_pages:
                try:
                    review_page_number = int(
                        review_page.get(
                            "page",
                            0
                        )
                    )
                except (
                    TypeError,
                    ValueError
                ):
                    continue

                if (
                    review_page_number
                    == current_page_number
                ):
                    current_family_a_page = (
                        review_page
                    )
                    break

            if current_family_a_page:
                raw_family_a_assets = (
                    current_family_a_page.get(
                        "extracted_asset_mapping",
                        []
                    )
                )

                if isinstance(
                    raw_family_a_assets,
                    list
                ):
                    family_a_authority = (
                        raw_family_a_assets
                    )

        except Exception as e:
            _logger.warning(
                "[PDF AI] FAMILY A AUTHORITY LOAD FAILED "
                "| PAGE=%s | %s",
                next_record.page_number,
                str(e)
            )
        
                # =====================================================
        # FAMILY A AUTHORITATIVE PRODUCT IDENTITY
        # =====================================================
        #
        # Build the authoritative product-group context for THIS
        # PDF page from the Family A page review.
        #
        # IMPORTANT:
        # current_family_a_page is already resolved above using
        # next_record.page_number.
        #
        # Therefore this context is page-specific and must NOT be
        # built from the entire family_a_review object.
        # =====================================================

        family_a_product_identity_context = (
            self._build_family_a_product_identity_context(
                current_family_a_page
                if isinstance(
                    current_family_a_page,
                    dict
                )
                else {}
            )
        )

        # =====================================================
        # DIAGNOSTIC: FAMILY A PRODUCT GROUPS
        # =====================================================

        if isinstance(
            current_family_a_page,
            dict
        ):

            family_a_product_groups = (
                current_family_a_page.get(
                    "product_groups",
                    []
                )
            )

            if not isinstance(
                family_a_product_groups,
                list
            ):
                family_a_product_groups = []

            _logger.warning(
                "[PDF AI FAMILY A PRODUCT GROUPS] "
                "JOB=%s | PAGE=%s | STRUCTURE=%s "
                "| GROUP_COUNT=%s",
                self.id,
                next_record.page_number,
                current_family_a_page.get(
                    "product_structure"
                ),
                len(
                    family_a_product_groups
                ),
            )

            for group in family_a_product_groups:

                if not isinstance(
                    group,
                    dict
                ):
                    continue

                _logger.warning(
                    "[PDF AI FAMILY A PRODUCT GROUP] "
                    "JOB=%s | PAGE=%s "
                    "| GROUP=%s "
                    "| NAME=%s "
                    "| TITLE=%s "
                    "| RELATIONSHIP=%s "
                    "| VARIANT_COUNT=%s",
                    self.id,
                    next_record.page_number,
                    group.get(
                        "group_id"
                    ),
                    group.get(
                        "product_name"
                    ),
                    group.get(
                        "product_title"
                    ),
                    group.get(
                        "relationship"
                    ),
                    len(
                        group.get(
                            "variants",
                            []
                        )
                        if isinstance(
                            group.get(
                                "variants",
                                []
                            ),
                            list
                        )
                        else []
                    ),
                )

        _logger.warning(
            "[PDF AI FAMILY A PRODUCT IDENTITY] "
            "PAGE=%s | GROUPS=%s\n%s",
            next_record.page_number,
            (
                len(
                    current_family_a_page.get(
                        "product_groups",
                        []
                    )
                )
                if isinstance(
                    current_family_a_page,
                    dict
                )
                else 0
            ),
            family_a_product_identity_context,
        )

        # =====================================================
        # RESOLVE FAMILY A ASSETS AGAINST CURRENT CLEAN INDEX
        # =====================================================
        #
        # Family A's original image_index is preserved.
        # We additionally resolve the same asset by image_hash
        # against the CURRENT page_images clean_index.
        #
        # This protects us if filtering/recovery changed indexes.
        # =====================================================

        current_assets_by_hash = {}

        for asset in page_images:
            if not isinstance(
                asset,
                dict
            ):
                continue

            image_hash = (
                asset.get("image_hash")
                or asset.get("source_hash")
            )

            if image_hash:
                current_assets_by_hash[
                    str(image_hash)
                ] = asset


        family_a_prompt_assets = []

        for family_asset in family_a_authority:

            if not isinstance(
                family_asset,
                dict
            ):
                continue

            image_hash = (
                family_asset.get(
                    "image_hash"
                )
                or ""
            )

            current_asset = (
                current_assets_by_hash.get(
                    str(image_hash)
                )
                if image_hash
                else None
            )

            current_clean_index = None

            if isinstance(
                current_asset,
                dict
            ):
                current_clean_index = (
                    current_asset.get(
                        "clean_index"
                    )
                )

            family_a_prompt_assets.append({
                "family_a_image_index":
                    family_asset.get(
                        "image_index"
                    ),

                "current_clean_index":
                    current_clean_index,

                "image_hash":
                    image_hash,

                "classification":
                    family_asset.get(
                        "classification",
                        "UNKNOWN"
                    ),

                "asset_role":
                    family_asset.get(
                        "asset_role",
                        "UNKNOWN"
                    ),

                "product_group":
                    family_asset.get(
                        "product_group"
                    ),

                "color":
                    family_asset.get(
                        "color"
                    ),

                "matches_original":
                    bool(
                        family_asset.get(
                            "matches_original",
                            False
                        )
                    ),

                "product_body_complete":
                    bool(
                        family_asset.get(
                            "product_body_complete",
                            False
                        )
                    ),

                "trustworthy":
                    bool(
                        family_asset.get(
                            "trustworthy",
                            False
                        )
                    ),

                "preserve":
                    bool(
                        family_asset.get(
                            "preserve",
                            False
                        )
                    ),

                "confidence":
                    family_asset.get(
                        "confidence",
                        0
                    ),
            })

            # =====================================================
            # DIAGNOSTIC: FAMILY A ASSET → PRODUCT GROUP
            # =====================================================

            _logger.warning(
                "[PDF AI FAMILY A ASSET MAP] "
                "JOB=%s | PAGE=%s "
                "| FAMILY_A_IMAGE_INDEX=%s "
                "| CURRENT_CLEAN_INDEX=%s "
                "| HASH=%s "
                "| PRODUCT_GROUP=%s "
                "| COLOR=%s "
                "| CLASSIFICATION=%s "
                "| ROLE=%s "
                "| COMPLETE=%s "
                "| TRUSTWORTHY=%s "
                "| PRESERVE=%s "
                "| CONFIDENCE=%s",
                self.id,
                next_record.page_number,
                family_asset.get(
                    "image_index"
                ),
                current_clean_index,
                image_hash,
                family_asset.get(
                    "product_group"
                ),
                family_asset.get(
                    "color"
                ),
                family_asset.get(
                    "classification",
                    "UNKNOWN"
                ),
                family_asset.get(
                    "asset_role",
                    "UNKNOWN"
                ),
                bool(
                    family_asset.get(
                        "product_body_complete",
                        False
                    )
                ),
                bool(
                    family_asset.get(
                        "trustworthy",
                        False
                    )
                ),
                bool(
                    family_asset.get(
                        "preserve",
                        False
                    )
                ),
                family_asset.get(
                    "confidence",
                    0
                ),
            )

        family_a_authority_context = json.dumps(
            family_a_prompt_assets,
            ensure_ascii=False,
            indent=2
        )

