    #==========build recovery candidates===========================
    def _build_recovery_candidates(

        self,

        page_data,

        images
    ):

        candidates = []

        page_image = page_data.get("page_image")

        if not page_image:

            return candidates

        for asset in images:

            quality = asset.get("crop_quality", 0)

            group = asset.get("asset_group")

            if group == "real" and quality >= 80:
                continue

            candidates.append(asset)

        _logger.warning(

            f"[RECOVERY CANDIDATES] "

            f"selected={len(candidates)} "

            f"total={len(images)}"
        )

        return candidates

    #==========estimate expected products===========================
    def _estimate_expected_products(

        self,

        page_data,

        report
    ):

        try:

            images = page_data.get(
                "images",
                []
            )

            page_width = float(

                page_data.get(
                    "page_width",
                    0
                ) or 0
            )

            page_height = float(

                page_data.get(
                    "page_height",
                    0
                ) or 0
            )

            page_area = page_width * page_height

            if page_area <= 0:

                return {

                    "expected": len(images),

                    "missing": 0
                }

            occupied = 0

            for asset in images:

                occupied += float(

                    asset.get(
                        "crop_area",
                        0
                    ) or 0
                )

            average_product_area = 0

            if images:

                average_product_area = (

                    occupied

                    /

                    len(images)

                )

            expected = len(images)

            if average_product_area > 0:

                estimate = round(

                    page_area

                    /

                    average_product_area

                )

                expected = max(

                    expected,

                    estimate
                )

            missing = max(

                0,

                expected - len(images)
            )

            _logger.warning(

                f"[EXPECTED PRODUCTS] "

                f"current={len(images)} "

                f"expected={expected} "

                f"missing={missing}"
            )

            return {

                "expected": expected,

                "missing": missing
            }

        except Exception:

            _logger.exception(

                "[EXPECTED PRODUCT ERROR]"
            )

            return {

                "expected": 0,

                "missing": 0
            }

    #==========page intelligence==========================
    def _analyse_page(

        self,

        page_data
    ):

        role_report = {

            "hero":0,

            "variant":0,

            "detail":0,

            "packaging":0,

            "feature":0,

            "lifestyle":0,

            "marketing":0
        }

        images = page_data.get(
            "images",
            []
        )

        page_width = page_data.get(
            "page_width",
            0
        )

        page_height = page_data.get(
            "page_height",
            0
        )

        report = {

            "total_images": len(images),

            "coverage": 0,

            "quality": 0,

            "requires_recovery": False,

            "reason": []

        }

        if not images:

            report["requires_recovery"] = True

            report["reason"].append(

                "No product images extracted."
            )

            return report

        total_area = 0

        total_quality = 0

        for asset in images:

            width = asset.get(
                "width",
                0
            ) or 0

            height = asset.get(
                "height",
                0
            ) or 0

            total_area += (

                width * height
            )

            total_quality += asset.get(

                "crop_quality",

                70
            )

            role = asset.get(

                "asset_role",

                "detail"
            )

            if role in role_report:

                role_report[role] += 1

        page_area = max(

            1,

            page_width * page_height
        )

        report["coverage"] = round(

            total_area

            /

            page_area,

            3
        )

        report["quality"] = round(

            total_quality

            /

            len(images),

            1
        )

        # ==========================
        # DECISION
        # ==========================

        if len(images) <= 2:

            report["requires_recovery"] = True

            report["reason"].append(

                "Very few product crops."
            )

        if report["coverage"] < 0.28:

            report["requires_recovery"] = True

            report["reason"].append(

                "Low page coverage."
            )

        if report["quality"] < 70:

            report["requires_recovery"] = True

            report["reason"].append(

                "Poor crop quality."
            )


        # =====================================
        # ROLE-BASED RECOVERY
        # =====================================

        if (

            role_report["hero"] == 0

            and

            role_report["variant"] == 0

        ):

            report["requires_recovery"] = True

            report["reason"].append(

                "No hero or variant products detected."
            )

        # =====================================
        # SAVE ROLE REPORT
        # =====================================

        report["role_report"] = role_report

        _logger.warning(

            f"[PAGE INTELLIGENCE] "

            f"images={len(images)} "

            f"coverage={report['coverage']} "

            f"quality={report['quality']} "

            f"recovery={report['requires_recovery']} "

            f"reason={report['reason']}"
        )

        return report

    #==========plan recovery=========================
    def _plan_page_recovery(

        self,

        page_data,

        page_report
    ):

        try:

            images = page_data.get(
                "images",
                []
            )

            layout = page_report.get(

                "layout",

                {}
            )

            expected = layout.get(

                "expected_products",

                page_report.get(

                    "estimated_products",

                    len(images)
                )
            )


            missing_info = page_report.get(

                "missing_products",

                {}
            )

            actual = missing_info.get(

                "detected",

                len(images)
            )

            missing = missing_info.get(

                "missing",

                max(

                    0,

                    expected - actual
                )
            )

            crop_plan = page_report.get(

                "crop_plan",

                {}
            )

            required = (

                page_report.get(

                    "requires_recovery",

                    False
                )

                or

                crop_plan.get(

                    "required",

                    False
                )

                or

                missing >= 2
            )

            # plan = {

            #     "required": required,

            #     "expected": expected,

            #     "actual": actual,

            #     "missing": missing,

            #     "strategy": "continue",

            #     "regions": []
            # }

            plan = {

                "required": required,

                "expected": expected,

                "actual": actual,

                "missing": missing,

                "strategy": "continue",

                "regions": []
            }

            # =====================================
            # RECOVERY REASONS
            # =====================================

            plan["reason"] = []

            if missing >= 2:

                plan["reason"].append(

                    f"{missing} products estimated missing."
                )

            if crop_plan.get(

                "required",

                False
            ):

                plan["reason"].append(

                    "Crop planner requested recovery."
                )

            if page_report.get(

                "requires_recovery",

                False
            ):

                plan["reason"].extend(

                    page_report.get(

                        "reason",

                        []
                    )
                )

            if not plan["required"]:

                return plan

            coverage = page_report.get(

                "coverage",

                1
            )

            if missing >= 2:

                plan["strategy"] = "recrop"

            elif crop_plan.get(

                "required",

                False
            ):

                plan["strategy"] = "recrop"

            elif coverage < 0.40:

                plan["strategy"] = "recrop"

            else:

                plan["strategy"] = "rerank"

            _logger.warning(

                f"[RECOVERY PLAN] "

                f"expected={expected} "

                f"actual={actual} "

                f"missing={missing} "

                f"strategy={plan['strategy']}"
            )

            plan["layout"] = layout

            plan["estimated_missing"] = missing

            return plan

        except Exception:

            _logger.exception(

                "[RECOVERY PLAN ERROR]"
            )

            return {

                "required": False,

                "strategy": "continue"
            }
    
    #==========role intelligence==============================
    def _apply_role_intelligence(

        self,

        images
    ):

        try:

            if not images:

                return images

            for asset in images:

                role = "detail"

                width = asset.get(

                    "width",

                    0
                )

                height = asset.get(

                    "height",

                    0
                )

                hero = asset.get(

                    "hero_score",

                    0
                )

                gallery = asset.get(

                    "gallery_score",

                    0
                )

                confidence = asset.get(

                    "confidence",

                    0
                )

                if asset.get("is_collage"):

                    role = "marketing"

                elif asset.get("asset_group") == "lifestyle":

                    role = "lifestyle"

                elif hero >= 90:

                    role = "hero"

                elif hero >= 70:

                    role = "variant"

                elif (

                    width > 250

                    and

                    height > 250

                    and

                    gallery >= 70

                ):

                    role = "variant"

                elif (

                    width < 180

                    or

                    height < 180

                ):

                    role = "detail"

                elif confidence > 80:

                    role = "detail"

                asset["asset_role"] = role

                _logger.warning(

                    f"[ROLE ENGINE] "

                    f"clean={asset.get('clean_index')} "

                    f"group={asset.get('asset_group')} "

                    f"role={role}"
                )

            return images

        except Exception:

            _logger.exception(

                "[ROLE ENGINE ERROR]"
            )

            return images

    #==========detect catalogue layout=========================
    def _detect_catalog_layout(

        self,

        page_data
    ):

        try:

            images = page_data.get(
                "images",
                []
            )

            width = page_data.get(
                "page_width",
                0
            )

            height = page_data.get(
                "page_height",
                0
            )

            if not width or not height:

                return {}

            boxes = []

            xs = []
            ys = []

            for asset in images:

                x = asset.get("x", 0)
                y = asset.get("y", 0)
                w = asset.get("width", 0)
                h = asset.get("height", 0)

                boxes.append({

                    "x": x,
                    "y": y,
                    "width": w,
                    "height": h
                })

                xs.append(x)
                ys.append(y)

            columns = len(

                sorted(

                    set(

                        round(x / 80)

                        for x in xs
                    )
                )
            )

            rows = len(

                sorted(

                    set(

                        round(y / 80)

                        for y in ys
                    )
                )
            )

            expected = max(

                len(images),

                rows * columns
            )

            layout = {

                "rows": rows,

                "columns": columns,

                "expected_products": expected,

                "boxes": boxes
            }


            _logger.warning(

                f"[LAYOUT ENGINE] "

                f"rows={rows} "

                f"columns={columns} "

                f"detected={len(images)} "

                f"expected={expected} "

                f"missing={max(0, expected-len(images))}"
            )

            return layout

        except Exception:

            _logger.exception(

                "[LAYOUT ENGINE ERROR]"
            )

            return {}

    #==========detect missing products==========================
    def _detect_missing_products(

        self,

        page_data,

        layout
    ):

        try:

            images = page_data.get(
                "images",
                []
            )

            expected = layout.get(
                "expected_products",
                len(images)
            )

            missing = max(

                0,

                expected - len(images)
            )

            result = {

                "expected": expected,

                "detected": len(images),

                "missing": missing,

                "requires_crop_generation": (

                    missing > 0
                )
            }

            _logger.warning(

                f"[MISSING DETECTOR] "

                f"expected={expected} "

                f"detected={len(images)} "

                f"missing={missing}"
            )

            return result

        except Exception:

            _logger.exception(

                "[MISSING DETECTOR ERROR]"
            )

            return {}

    #==========build crop plan==================================
    def _build_crop_plan(

        self,

        page_data,

        page_report
    ):

        layout = page_report.get(

            "layout",

            {}
        )

        missing = page_report.get(

            "missing_products",

            {}
        )

        plan = {

            "required": missing.get(

                "requires_crop_generation",

                False
            ),

            "count": missing.get(

                "missing",

                0
            ),

            "layout": layout
        }

        _logger.warning(

            f"[CROP PLAN] "

            f"required={plan['required']} "

            f"count={plan['count']}"
        )

        return plan

    #==========generate additional crops==========================
    def _generate_additional_crops(

        self,

        page_data,

        crop_plan
    ):

        page_image = page_data.get(

            "page_image"
        )

        if not page_image:

            return []

        generated = []

        for crop in crop_plan.get(

            "crops",

            []
        ):

            generated.append({

                "type": "recrop",

                "x": crop.get("x"),

                "y": crop.get("y"),

                "width": crop.get("width"),

                "height": crop.get("height"),

                "score": crop.get(

                    "priority",

                    0
                )
            })

        _logger.warning(

            f"[RECROP PLAN] "

            f"generated={len(generated)}"
        )

        return generated

    #==========workflow strategy=================================
    def _select_processing_strategy(

        self,

        page_report
    ):

        # =====================================
        # DEFAULT
        # =====================================

        strategy = "continue"

        confidence = 1.00

        reasons = []

        # =====================================
        # RECOVERY PLAN
        # =====================================

        recovery_plan = page_report.get(

            "recovery_plan",

            {}
        )

        if recovery_plan:

            strategy = recovery_plan.get(

                "strategy",

                strategy
            )

            if strategy != "continue":

                confidence = 0.95

                reasons.append(

                    f"Recovery strategy: {strategy}"
                )

        # =====================================
        # LEGACY RECOVERY SUPPORT
        # =====================================

        elif page_report.get(

            "requires_recovery",

            False
        ):

            strategy = "recover"

            confidence = 0.95

            reasons.extend(

                page_report.get(

                    "reason",

                    []
                )
            )

        # =====================================
        # EXPECTED PRODUCT CHECK
        # =====================================

        missing = page_report.get(

            "missing",

            0
        )

        if missing >= 2:

            if strategy == "continue":

                recovery_plan = page_report.get(

                    "recovery_plan",

                    {}
                )

                strategy = recovery_plan.get(

                    "strategy",

                    "recrop"
                )

            confidence = min(

                confidence,

                0.90
            )

            reasons.append(

                f"Estimated {missing} product(s) missing."
            )


        _logger.warning(

            f"[WORKFLOW STRATEGY] "

            f"strategy={strategy} "

            f"missing={missing} "

            f"confidence={confidence:.2f} "

            f"recovery={page_report.get('requires_recovery')} "

            f"reason={reasons}"
        )

        return {

            "strategy": strategy,

            "confidence": confidence,

            "reason": reasons
        }
    
    #================build_ai_page_context=======================
    def _build_ai_page_context(

        self,

        page_data,

        validation
    ):

        try:

            images = page_data.get(

                "images",

                []
            )

            report = {

                "real": 0,

                "product_demo": 0,

                "lifestyle": 0,

                "marketing": 0
            }

            for asset in images:

                if not isinstance(asset, dict):

                    continue

                group = asset.get(

                    "asset_group",

                    "real"
                )

                if group in report:

                    report[group] += 1

            context = {

                "page": page_data.get(

                    "page"
                ),

                "coverage": round(

                    validation.get(

                        "coverage",

                        0

                    ),

                    3
                ),

                "score": validation.get(

                    "score",

                    0
                ),

                "requires_recovery": page_data.get(

                    "recovery_required",

                    False
                ),

                "real_products": report["real"],

                "product_demo": report["product_demo"],

                "lifestyle": report["lifestyle"],

                "marketing": report["marketing"],

                "page_width": page_data.get(

                    "page_width",

                    0
                ),

                "page_height": page_data.get(

                    "page_height",

                    0
                )
            }

            _logger.warning(

                f"[AI PAGE CONTEXT] "

                f"page={context['page']} "

                f"real={context['real_products']} "

                f"demo={context['product_demo']} "

                f"life={context['lifestyle']} "

                f"coverage={context['coverage']} "

                f"score={context['score']} "

                f"recovery={context['requires_recovery']}"
            )

            return context

        except Exception:

            _logger.exception(

                "[AI PAGE CONTEXT ERROR]"
            )

            return {}

    #==========crop quality=======================================
    def _calculate_crop_quality(

        self,

        asset
    ):

        quality = 100

        width = int(
            asset.get(
                "width",
                0
            ) or 0
        )

        height = int(
            asset.get(
                "height",
                0
            ) or 0
        )

        score = float(
            asset.get(
                "score",
                0
            ) or 0
        )

        lifestyle_score = float(
            asset.get(
                "lifestyle_score",
                0
            ) or 0
        )

        # =====================================
        # SIZE
        # =====================================

        if width < 120:
            quality -= 25

        if height < 120:
            quality -= 25

        # =====================================
        # LONG STRIPS
        # =====================================

        if width and height:

            ratio = width / height

            if ratio > 4:

                quality -= 15

            elif ratio < 0.25:

                quality -= 15

        # =====================================
        # COLLAGE
        # =====================================

        if asset.get("is_collage"):

            quality -= 50

        # =====================================
        # LIFESTYLE
        # =====================================

        quality -= int(
            lifestyle_score * 25
        )

        # =====================================
        # EXTRACTOR SCORE
        # =====================================

        if score < 40:

            quality -= 15

        elif score > 90:

            quality += 5

        return max(
            0,
            min(
                quality,
                100
            )
        )

