    #==========analyse crop quality=================================
    def _crop_quality_analysis(
        self,
        asset
    ):

        width = int(
            asset.get("width", 0) or 0
        )

        height = int(
            asset.get("height", 0) or 0
        )

        score = 100

        reasons = []

        # =====================================
        # TOO SMALL
        # =====================================

        if width < 120 or height < 120:

            score -= 40

            reasons.append("tiny")

        # =====================================
        # EXTREME RATIO
        # =====================================

        if width and height:

            ratio = width / height

            if ratio > 4:

                score -= 20

                reasons.append("too_wide")

            elif ratio < 0.25:

                score -= 20

                reasons.append("too_tall")

        # =====================================
        # COLLAGE
        # =====================================

        if asset.get("is_collage"):

            score -= 50

            reasons.append("collage")

        # =====================================
        # LIFESTYLE
        # =====================================

        if asset.get("asset_group") == "lifestyle":

            score -= 25

            reasons.append("lifestyle")

        return {

            "score": max(0, score),

            "reasons": reasons
        }

    #==========determine refinement================================
    def _needs_crop_refinement(
        self,
        asset
    ):

        quality = asset.get(
            "crop_quality",
            100
        )

        return quality < 70

