    # ========================================================================
    def match_image_with_ai(self, product_name, images):

        api_key = self.env['ir.config_parameter'].sudo().get_param('openai.api.key')
        client = OpenAI(api_key=api_key)

        if not images:
            return None

        # limit images for performance
        images = images[:5]
        image_inputs = [
        {
                "type": "input_image",
                "image_url": f"data:image/jpeg;base64,{img}"
            }
            for img in images
        ]

        prompt = f"""
        You are an expert product image matcher.

        Select the image that BEST represents this product:

        PRODUCT:
        {product_name}

        RULES:
        - Return ONLY the index (0-based integer)
        - No explanation
        - No text

            PRIORITY:
        1. Prefer isolated product on plain/white background
        2. Prefer centered single-product image
        3. Prefer image showing full product clearly
        4. Prefer clean studio product photos
        5. Prefer catalog hero product image
        6. Avoid lifestyle scenes if isolated image exists
        7. Avoid collages whenever possible
        8. Avoid infographic layouts
        9. Avoid text-heavy graphics
        10. Avoid multi-product overview images
        11. Avoid images containing large text blocks

        DO NOT PICK:
        - logos
        - icons
        - banners
        - cropped fragments
        - specification charts
        - text-heavy graphics
        - tiny thumbnails
        """

        try:
            response = client.responses.create(
                model="gpt-4.1",
                input=[{
                    "role": "user",
                    "content": [{"type": "input_text", "text": prompt}] + image_inputs
                }],
                timeout=30
            )

            result = response.output_text.strip()

            index = int(result)

            if 0 <= index < len(images):
                return images[index]

        except Exception as e:
            _logger.warning(f"AI IMAGE MATCH FAILED → {str(e)}")

        return None
    
    #======== returning images indexes========================================
    def match_image_index_with_ai( self, product_name, images):

        api_key = self.env[
            'ir.config_parameter'
        ].sudo().get_param(
            'openai.api.key'
        )

        client = OpenAI(api_key=api_key)

        if not images:
            return None


        filtered_images = []

        for img in images:

            try:

                if not img:
                    continue

                img_lower = img.lower()

                bad_keywords = [

                    "banner",

                    "lifestyle",

                    "infographic",

                    "specification",

                    "sizechart",

                    "dimensions"
                ]

                if any(
                    k in img_lower
                    for k in bad_keywords
                ):
                    continue

                filtered_images.append(img)

            except Exception:
                continue

        if filtered_images:

            images = filtered_images

        images = images[:8]

        image_inputs = []

        for idx, img in enumerate(images):

            image_inputs.append({
                "type": "input_text",
                "text": f"IMAGE INDEX: {idx}"
            })

            image_inputs.append({
                "type": "input_image",
                "image_url":
                    f"data:image/jpeg;base64,{img}"
            })

        prompt = f"""
        You are an ecommerce
        product image selector.

        PRODUCT:
        {product_name}

        Return ONLY the BEST
        image index.

        PRIORITY:
        - isolated product
        - plain background
        - centered object
        - clean catalog render

        AVOID:
        - people
        - lifestyle scenes
        - infographics
        - collages
        - banners
        - text-heavy graphics

        Return ONLY integer index.
        """

        try:

            response = client.responses.create(

                model="gpt-4.1",

                input=[{
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": prompt
                        }
                    ] + image_inputs
                }],

                timeout=30
            )

            result = (
                response.output_text or ""
            ).strip()

            index = int(result)

            if 0 <= index < len(images):

                return index

        except Exception as e:

            _logger.warning(

                f"[IMAGE INDEX MATCH FAILED] "

                f"{str(e)}"
            )

        return None

    #============enforce translation=========================================
    def _force_translate(self, text, target_lang):

        from openai import OpenAI

        if not text:
            return text

        try:

            api_key = self.env[
                'ir.config_parameter'
            ].sudo().get_param(
                'openai.api.key'
            )

            if not api_key:

                _logger.warning(
                    "[OPENAI TRANSLATE] MISSING API KEY"
                )

                return text


            client = OpenAI(
                api_key=api_key
            )


            prompt = f"""
            Translate the following text into {target_lang}.

            Rules:
            - Return ONLY the translated text
            - Preserve formatting
            - Preserve product terminology
            - Do not explain anything

            TEXT:
            {text}
            """


            response = client.responses.create(

                model="gpt-4.1-mini",

                input=prompt
            )


            translated = (
                response.output_text or ''
            ).strip()


            if not translated:

                _logger.warning(
                    "[OPENAI TRANSLATE EMPTY]"
                )

                return text


            _logger.warning(

                f"[OPENAI TRANSLATION SUCCESS] "

                f"lang={target_lang}"
            )

            return translated


        except Exception as e:

            _logger.warning(

                f"[OPENAI TRANSLATE FAILED] "

                f"{str(e)}"
            )

            return text

    #=========Translation new logic==========================================

    def _apply_product_translation(self, product):

        if not product:
            return

        name = product.name or ''
        desc = product.description_sale or ''

        # ----------------------------
        # DEBUG
        # ----------------------------
        _logger.warning(
            f"[TRANSLATION INPUT] product={product.id} | name={name} | desc_len={len(desc)}"
        )

        # ----------------------------
        # ALWAYS TRANSLATE NAME (cheap)
        # ----------------------------
        ru_name = self._force_translate(name, "ru")
        az_name = self._force_translate(name, "az")

        # ----------------------------
        # ONLY TRANSLATE DESCRIPTION IF EXISTS
        # ----------------------------
        if desc and len(desc.strip()) > 10:

            ru_desc = self._smart_translate(desc, "ru")
            az_desc = self._smart_translate(desc, "az")

        else:
            ru_desc = ''
            az_desc = ''

            _logger.warning(
                f"[TRANSLATION SKIPPED DESC] product={product.id}"
            )

        # ----------------------------
        # SAVE
        # ----------------------------
        product.with_context(lang='ru_RU').write({
            'name': ru_name,
            'description_sale': ru_desc
        })

        product.with_context(lang='az_AZ').write({
            'name': az_name,
            'description_sale': az_desc
        })


        # =========================================
        # DETECT REAL TRANSLATION
        # =========================================

        translation_changed = False

        try:

            # =====================================
            # SAFE LANGUAGE
            # =====================================

            lang_code = 'ru_RU'

            translated_product = product.with_context(
                lang=lang_code
            )

            translated_name = translated_product.name or ''

            original_name = product.name or ''

            translated_desc = (
                translated_product.description_sale or ''
            )

            original_desc = (
                product.description_sale or ''
            )

            # =====================================
            # NAME CHANGED
            # =====================================

            if translated_name != original_name:

                translation_changed = True

            # =====================================
            # DESCRIPTION CHANGED
            # =====================================

            if translated_desc != original_desc:

                translation_changed = True

        except Exception as e:

            _logger.warning(

                f"[TRANSLATION CHECK FAILED] "

                f"{str(e)}"
            )


        if translation_changed:


            # =========================================
            # SHOW REAL TRANSLATED VALUES
            # =========================================

            try:

                ru_name = product.with_context(
                    lang='ru_RU'
                ).name or ''

                az_name = product.with_context(
                    lang='az_AZ'
                ).name or ''

            except Exception:

                ru_name = ''
                az_name = ''


            _logger.warning(

                f"[TRANSLATION SUCCESS] "

                f"product={product.id} | "

                f"RU={ru_name[:120]} | "

                f"AZ={az_name[:120]}"
            )

        else:

            _logger.warning(

                f"[TRANSLATION NO-CHANGE] "

                f"product={product.id}"
            )


    #============product translation extended================
    def _smart_translate(self, text, lang):

        # fallback if needed
        if len(text) < 5:
            return self._force_translate(text, lang)

        try:
            api_key = self.env['ir.config_parameter'].sudo().get_param('openai.api.key')
            client = OpenAI(api_key=api_key)

            prompt = f"Translate to {lang} and improve clarity:\n{text}"

            response = client.responses.create(
                model="gpt-4.1-mini",
                input=prompt
            )

            return response.output_text.strip()

        except:
            return self._force_translate(text, lang)


    #==========expand recovery products=========================
    def _expand_products_from_recovery(

        self,

        products,

        page_images
    ):

        try:

            if not products:

                return products

            used_indexes = set()

            for product in products:

                main = product.get(

                    "main_image_index"
                )

                if main is not None:

                    used_indexes.add(main)

                for idx in product.get(

                    "gallery_image_indexes",

                    []
                ):

                    used_indexes.add(idx)

            created = 0

            base_product = products[0]

            for asset in page_images:

                if (

                    asset.get("promotion_source") != "recovery"

                ):

                    continue

                clean = asset.get(

                    "clean_index"
                )

                if clean in used_indexes:

                    continue

                candidate = dict(base_product)

                candidate["generated_from"] = "recovery"

                candidate["main_image_index"] = clean

                candidate["gallery_image_indexes"] = [clean]

                candidate["variants"] = [{

                    "attributes": {

                        "Recovered": f"{clean}"

                    }

                }]

                products.append(candidate)

                used_indexes.add(clean)

                created += 1

                _logger.warning(

                    f"[RECOVERY PRODUCT CREATED] "

                    f"clean={clean}"
                )

            _logger.warning(

                f"[RECOVERY PRODUCT EXPANSION] "

                f"added={created}"
            )

            return products

        except Exception:

            _logger.exception(

                "[RECOVERY PRODUCT EXPANSION ERROR]"
            )

            return products

