    #======send to Open AI excel flow============================
    def send_to_openai_excel(self):

        import json

        api_key = self.env[
            'ir.config_parameter'
        ].sudo().get_param(
            'openai.api.key'
        )

        if not api_key:

            raise Exception(
                "OpenAI API key not configured"
            )


        client = OpenAI(
            api_key=api_key
        )


        _logger.warning(
            "[EXCEL AI] START"
        )


        # =====================================================
        # LOAD EXTRACTED DATA
        # =====================================================

        try:

            pages = json.loads(
                self.extracted_text or "[]"
            )

        except Exception as e:

            _logger.error(

                f"[EXCEL AI] "

                f"INVALID extracted_text JSON "

                f"| {str(e)}"
            )

            return


        if not pages:

            _logger.error(
                "[EXCEL AI] NO ROWS TO PROCESS"
            )

            return


        _logger.warning(

            f"[EXCEL AI] "

            f"TOTAL ROWS={len(pages)}"
        )


        # =====================================================
        # BATCH
        # =====================================================

        BATCH_SIZE = 5

        start = (
            self.excel_ai_index or 0
        )

        end = min(

            start + BATCH_SIZE,

            len(pages)
        )


        batch = pages[start:end]


        _logger.warning(

            f"[EXCEL AI BATCH] "

            f"{start} → {end}"
        )


        # =====================================================
        # LOAD EXISTING PRODUCTS
        # =====================================================

        existing_products = []


        if self.ai_response:

            try:

                existing_ai = json.loads(
                    self.ai_response
                )

                if (
                    isinstance(existing_ai, list)
                    and existing_ai
                ):

                    existing_products = (
                        existing_ai[0].get(
                            "products",
                            []
                        )
                    )


                _logger.warning(

                    f"[EXCEL AI] "

                    f"EXISTING PRODUCTS="

                    f"{len(existing_products)}"
                )

            except Exception as e:

                _logger.warning(

                    f"[EXCEL AI] "

                    f"FAILED LOAD EXISTING "

                    f"| {str(e)}"
                )

                existing_products = []


        new_products = []


        # =====================================================
        # PROCESS ROWS
        # =====================================================

        for idx, row in enumerate(

            batch,

            start=start

        ):

            try:

                row_text = row.get(
                    "text",
                    ""
                )

                row_price = row.get(
                    "price",
                    ""
                )

                row_stock = row.get(
                    "stock",
                    ""
                )

                images = row.get(
                    "images",
                    []
                )


                _logger.warning(

                    f"[EXCEL AI ROW] "

                    f"idx={idx} "

                    f"| images={len(images)}"
                )


                prompt = f"""
                You are a structured Excel product parser.

                Each input represents EXACTLY ONE ROW = ONE PRODUCT.

                =====================================
                COLUMN UNDERSTANDING (CRITICAL)
                =====================================

                The row could contain mixed values like:

                - ID (e.g. 94601, 12345)
                - Range (e.g. 2-66, 11-00)
                - Stock numbers
                - Prices
                - Links (http...)
                - Image references

                YOU MUST:

                1. IDENTIFY PRODUCT ID
                - Usually numeric (e.g. 94601)
                - Column name may vary:
                    - KOD
                    - SKU
                    - ID
                    - CODE

                2. IDENTIFY PRODUCT NAME
                - MUST NOT be:
                    - pure numbers
                    - ranges
                    - links
                    - dates
                    - headers

                - Product names should describe the ACTUAL product type.

               GOOD:
                - Sports Bottle
                - Metal Pen
                - Travel Mug
                - Drawstring Bag

                If the Excel already contains a valid product name:
                - preserve and use it

                If the Excel does NOT contain a real product name:
                - intelligently generate one using:
                    - Product <ID>
                    - category clues
                    - image appearance
                    - surrounding row data

                Fallback naming is allowed when necessary.

                GOOD fallback examples:
                - Product 94601
                - Bottle 94646
                - Pen 92070

                However:

                If rows belong to the SAME variant_group,
                you MUST still detect and extract the REAL variant difference.

                Example:

                Parent:
                Product 94646

                Variants:
                - White
                - Orange
                - Black

                DO NOT return:
                - Variant 1
                - Variant 2

                when a real difference can be visually or textually identified.
                
                =====================================
                VARIANT GROUPING (VERY IMPORTANT)
                =====================================

                - SAME ID = SAME variant_group
                - DIFFERENT ID = DIFFERENT PRODUCT
                - NEVER leave variant_group empty

                Rows sharing the same:
                - ID
                - grouped code
                - SKU group

                should be treated as variants of ONE parent product.

                 =====================================
                VARIANT DETECTION
                =====================================

                If rows share same PRODUCT ID:

                → they belong to the SAME product family.

                IMPORTANT:

                Use PRODUCT IMAGES as the PRIMARY
                source for identifying variants.

                Look for visual differences such as:

                - color
                - material
                - finish
                - lid type
                - texture
                - shape
                - capacity
                - packaging

                THEN use nearby codes/numbers
                as supporting evidence.

                Example:

                Rows may contain:

                106
                103
                128

                These MAY represent:
                - color codes
                - material codes
                - size codes

                DO NOT assume globally.

                Infer meaning from:
                - image differences
                - repeated patterns
                - product appearance

                If uncertain:

                Use safe fallback:

                "attributes": {{
                    "Vendor Code": "106"
                }}

                NEVER return:
                - Variant 1
                - Variant 2
                - Variant 3

                ALWAYS return meaningful attributes.

                =====================================
                VISUAL DIFFERENCE DETECTION
                =====================================

                If product images exist:

                You MUST visually inspect the images
                to identify the distinguishing feature.

                Example:

                If grouped products show:
                - white bottle
                - orange bottle
                - black bottle

                Return:

                {{
                    "name": "Sports Bottle",
                    "color": "White"
                }}

                {{
                    "name": "Sports Bottle",
                    "color": "Orange"
                }}

                DO NOT return:
                - Variant 1
                - Variant 2
                - Product 94601

                =====================================
                PARENT PRODUCT CONSISTENCY
                =====================================

                When multiple rows belong to the same
                variant_group:

                - The parent product name MUST remain consistent.
                - ONLY the variant fields should change.

                GOOD:

                Sports Bottle
                → White
                → Orange
                → Black

                BAD:

                White Bottle
                Orange Bottle
                Black Bottle

                =====================================
                ATTRIBUTE EXTRACTION
                =====================================

                Put distinguishing values into:

                - color
                - material
                - size
                - capacity
                - style

                Only use generic "Variant"
                if absolutely no real difference can be detected.

                =====================================
                PRICE & STOCK
                =====================================

                - Extract numeric price carefully
                - Extract stock carefully
                - Ignore ranges like:
                    - 2-66
                    - 11-00

                =====================================
                LINKS
                =====================================

                If a row contains a product URL:
                - preserve it
                - never use URL as product name

                =====================================
                OUTPUT FORMAT
                =====================================

                [
                    {{
                        "name": "",
                        "description": "",
                        "category": "",
                        "price": "",
                        "stock": "",
                        "variant_group": "",
                        "color": "",
                        "material": "",
                        "size": "",
                        "capacity": "",
                        "style": "",
                        "url": "",
                        "variants": [
                            {{
                                "attributes": {{
                                    "Variant": ""
                                }},
                                "image_index": 0,
                                "stock": null
                            }}
                        ]
                    }}
                ]

                =====================================
                IMPORTANT RULES
                =====================================

                - Return ONLY valid JSON
                - No markdown
                - No explanations
                - No comments
                - No trailing commas

                ROW TEXT:
                {row_text}

                DETECTED PRICE:
                {row_price}

                DETECTED STOCK:
                {row_stock}
                """

                response = client.responses.create(

                    model="gpt-4.1-mini",

                    input=prompt,

                    timeout=60
                )


                result = (
                    response.output_text or ""
                ).strip()

                _logger.warning(
                    f"[EXCEL AI RAW] "
                    f"row={idx} "
                    f"| result={result[:3000]}"
                )


                result = result.replace(
                    "```json",
                    ""
                )

                result = result.replace(
                    "```",
                    ""
                ).strip()


                if not result:

                    raise Exception(
                        "EMPTY AI RESPONSE"
                    )


                parsed = json.loads(
                    result
                )

                for product_idx, p in enumerate(parsed):

                    _logger.warning(
                        f"[EXCEL AI PRODUCT] "
                        f"idx={product_idx} "
                        f"| name={p.get('name')} "
                        f"| stock={p.get('stock')} "
                        f"| price={p.get('price')} "
                        f"| variant_group={p.get('variant_group')}"
                    )

                    for v_idx, variant in enumerate(
                        p.get("variants", [])
                    ):

                        _logger.warning(
                            f"[EXCEL AI VARIANT] "
                            f"product={p.get('name')} "
                            f"| variant_idx={v_idx} "
                            f"| stock={variant.get('stock')} "
                            f"| attrs={variant.get('attributes')}"
                        )


                if (

                    isinstance(parsed, list)

                    and parsed

                ):

                    parsed = parsed[0]


                if not isinstance(
                    parsed,
                    dict
                ):

                    _logger.warning(

                        f"[EXCEL AI] "

                        f"INVALID STRUCTURE "

                        f"| idx={idx}"
                    )

                    continue


                # =================================================
                # IMAGE
                # =================================================

                if images:

                    parsed["image"] = (
                        images[0]
                    )


                # =================================================
                # DEBUG
                # =================================================

                _logger.warning(

                    f"[EXCEL AI PRODUCT] "

                    f"name={parsed.get('name')} "

                    f"| group={parsed.get('variant_group')}"
                )


                new_products.append(
                    parsed
                )


            except Exception as e:

                _logger.exception(

                    f"[EXCEL AI ERROR] "

                    f"idx={idx} "

                    f"| {str(e)}"
                )


        # =====================================================
        # MERGE PRODUCTS SAFELY
        # =====================================================

        combined_products = (
            existing_products
            +
            new_products
        )


        _logger.warning(

            f"[EXCEL AI MERGE] "

            f"existing={len(existing_products)} "

            f"| new={len(new_products)} "

            f"| total={len(combined_products)}"
        )


        # =====================================================
        # SAVE
        # =====================================================

        self.ai_response = json.dumps([{

            "page": 1,

            "products": combined_products

        }])


        self.excel_ai_index = end


        _logger.warning(

            f"[EXCEL AI SAVE] "

            f"{self.excel_ai_index}/"

            f"{len(pages)}"
        )


        # =====================================================
        # NEXT STATE
        # =====================================================

        if end < len(pages):

            self.state = "excel_ai"

        else:

            _logger.warning(
                "[EXCEL AI COMPLETE]"
            )

            self.state = (
                "excel_creating"
            )


        self.flush_recordset()

        self.env.cr.commit()

        return
    

    #==========Excel url detect workflo=======================
    def _extract_product_url(self, row):

        possible_keys = [

            "url",
            "link",
            "product_url",
            "product link",
            "website",
            "href",

        ]

        for key in possible_keys:

            value = row.get(key)

            if not value:
                continue

            value = str(value).strip()

            if value.startswith(
                ("http://", "https://")
            ):
                return value

        return False
    
    #======Excel url detection router=======================
    def _route_excel_rows(self, products):

        normal_products = []
        url_products = []

        for row in products:

            url = self._extract_product_url(row)

            if url:

                row["detected_url"] = url

                url_products.append(row)

            else:

                normal_products.append(row)

        return {
            "normal": normal_products,
            "url": url_products,
        }

    #==========Excel URl queue logic========================
    def _queue_excel_urls(self, url_products):

        import json

        if not url_products:
            return

        seen = set()
        cleaned = []

        for row in url_products:

            url = row.get("detected_url")

            if not url:
                continue

            if url in seen:
                continue

            seen.add(url)

            cleaned.append(row)

        url_products = cleaned

        self.excel_url_queue = json.dumps(
            url_products
        )

        self.excel_url_processing = True

        self.excel_url_index = 0

    #==========================================================
    #===========Excel Url Data Main Update Method==============
    #==========================================================

    def process_excel_url_queue(self):

        import json

        if not self.excel_url_queue:

            _logger.warning(
                "[URL QUEUE] EMPTY"
            )

            self.state = "done"

            return

        rows = json.loads(
            self.excel_url_queue
        )

        # ====================================
        # LOAD FAMILY LOOKUP
        # ====================================

        family_lookup = json.loads(
            self.family_lookup_json or "{}"
        )

        _logger.warning(

            "[FAMILY LOOKUP LOADED]\n%s"

            % json.dumps(
                family_lookup,
                indent=4
            )
        )

        start = self.excel_url_index or 0

        processed = 0
        updated = 0
        skipped = 0
        failed = 0

        BATCH_SIZE = 5

        end = min(
            start + BATCH_SIZE,
            len(rows)
        )

        _logger.warning(

            f"[URL QUEUE START] "

            f"{start} -> {end} | "

            f"total={len(rows)}"
        )

        vendor_id = (

            self.partner_id.id

            if self.partner_id

            else self.env.user.partner_id.id
        )

        for idx in range(start, end):

            try:

                row = rows[idx]
                processed += 1

                group_id = str(
                    row.get("group_id") or ""
                ).strip()

                product_url = str(
                    row.get("url") or ""
                ).strip()

                _logger.warning(

                    "[QUEUE ITEM] "

                    f"idx={idx} | "

                    f"group_id={group_id} | "

                    f"url={product_url}"

                )

                if not product_url:

                    _logger.warning(

                        f"[URL QUEUE SKIP] "

                        f"NO URL AT INDEX {idx}"
                    )

                    self.excel_url_index = idx + 1

                    self._safe_commit_progress()

                    skipped += 1
                    continue

                if not group_id:

                    _logger.warning(

                        f"[URL QUEUE SKIP] "

                        f"NO GROUP ID AT INDEX {idx}"
                    )

                    self.excel_url_index = idx + 1

                    self._safe_commit_progress()

                    skipped += 1
                    continue

               
                # ====================================
                # EXTRACT URL DATA
                # ====================================

                url_data = self._extract_url_product_data(
                    product_url,
                    group_id
                )

                _logger.warning(

                    f"[TARGET PRODUCT CODE] "

                    f"{group_id}"
                )


                # ====================================
                # APIFY STILL RUNNING
                # ====================================

                if not url_data:

                    _logger.warning(

                        f"[URL WAITING FOR APIFY] "

                        f"{product_url}"
                    )

                    self.state = "excel_url_enrichment"

                    self._safe_commit_progress()

                    return

                # ====================================
                # DEBUG URL DATA
                # ====================================

                _logger.warning(

                    f"[URL DATA KEYS] "

                    f"{list(url_data.keys())}"
                )

                _logger.warning(

                    "[URL DATA RAW]\n%s"

                    % json.dumps(
                        url_data,
                        indent=4,
                        default=str
                    )
                )

                _logger.warning(

                    f"[URL DATA TITLE] "

                    f"{url_data.get('title')}"
                )

                _logger.warning(

                    f"[URL DATA SUBTITLE] "

                    f"{url_data.get('subtitle')}"
                )

                _logger.warning(

                    f"[URL DATA DESCRIPTION] "

                    f"{bool(url_data.get('description'))}"
                )

                # ====================================
                # FIND EXISTING FAMILY/VARIANT PRODUCT
                # ====================================

                template_id = row.get("template_id")
                family_id = row.get("vendor_family_id")

                # ------------------------------------
                # Fallback for older queues
                # ------------------------------------

                if not template_id:

                    family_info = family_lookup.get(group_id)

                    if isinstance(family_info, dict):

                        template_id = family_info.get("template_id")
                        family_id = family_info.get("family_id")

                # ------------------------------------
                # Still nothing?
                # ------------------------------------

                if not template_id:

                    _logger.warning(

                        "[FAMILY LOOKUP FAILED] "

                        f"group={group_id}"

                    )

                    self.excel_url_index = idx + 1

                    self._safe_commit_progress()

                    skipped += 1
                    continue

                _logger.warning(

                    "[TARGET LOOKUP] "

                    f"group={group_id} "

                    f"template={template_id} "

                    f"family={family_id}"

                )

                # ====================================
                # FIND PARENT TEMPLATE
                # ====================================

                template_id = int(
                    template_id or 0
                )

                product = self.env[
                    "product.template"
                ].browse(template_id)

                if not product.exists():

                    _logger.warning(
                        "[TEMPLATE NOT FOUND] "
                        f"{template_id}"
                    )

                    product = self.env[
                        "product.template"
                    ].search(
                        [
                            ("vendor_family_id", "=", family_id),
                            ("vendor_import_job_id", "=", self.id),
                        ],
                        limit=1,
                    )

                    _logger.warning(

                        "[FAMILY LOOKUP FALLBACK] "

                        f"count={len(product)}"

                    )
                

                _logger.warning(

                    f"[URL LOOKUP PRODUCTS] "

                    f"count={len(product)}"
                )


                if product:

                    _logger.warning(

                        "[TARGET PRODUCT] "

                        f"id={product.id} "

                        f"name={product.name} "

                        f"family={product.vendor_family_id}"

                    )

                else:

                    _logger.warning(

                        "[TARGET PRODUCT NOT FOUND] "

                        f"family={family_id}"

                    )


                if not product:

                    _logger.warning(

                        f"[URL ENRICHMENT] "

                        f"PRODUCT NOT FOUND "

                        f"{group_id}"
                    )

                    self.excel_url_index = idx + 1

                    self._safe_commit_progress()

                    skipped += 1
                    continue

                
                # ====================================
                # BUILD UPDATE VALUES
                # ====================================

                vals = {}

                # ------------------------------------
                # Build HTML description
                # ------------------------------------

                html = []

                # ========= Subtitle =========

                subtitle = str(
                    url_data.get("subtitle") or ""
                ).strip()

                if subtitle:

                    html.append(

                        f"<p>{subtitle}</p>"

                    )

                # ========= Description =========

                description = str(
                    url_data.get("description") or ""
                ).strip()

                if description:

                    paragraphs = [

                        p.strip()

                        for p in description.splitlines()

                        if p.strip()

                    ]

                    if paragraphs:

                        for p in paragraphs:

                            html.append(

                                f"<p>{p}</p>"

                            )

                    else:

                        html.append(

                            f"<p>{description}</p>"

                        )
                

                # ========= SKU =========

                sku = str(
                    url_data.get("sku") or ""
                ).strip()

                if sku:

                    html.append(

                        f"<p><strong>SKU:</strong> {sku}</p>"

                    )

                # ========= Technical Details =========

                details = []

                for label, field in [

                    ("Material", "material"),

                    ("Capacity", "capacity"),

                    ("Dimensions", "dimensions"),

                    ("Specifications", "specifications")

                ]:

                    value = url_data.get(field)

                    # AI may return specifications as a list
                    if isinstance(value, list):

                        value = "<br/>".join(

                            str(v).strip()

                            for v in value

                            if str(v).strip()

                        )

                    else:

                        value = str(
                            value or ""
                        ).strip()

                    if value:

                        details.append(

                            f"<li><strong>{label}:</strong> {value}</li>"

                        )

                if details:

                    html.append(

                        "<ul>"

                        + "".join(details)

                        + "</ul>"

                    )

                # ========= Save HTML =========

                if html:

                    vals["description_sale"] = "\n".join(html)

                
                # ====================================
                # UPDATE PRODUCT
                # ====================================

                if vals:

                    _logger.warning(

                        "[URL DESCRIPTION]\n%s"

                        % vals.get(
                            "description_sale",
                            ""
                        )[:3000]
                    )

                    # ====================================
                    # UPDATE ENTIRE FAMILY
                    # ====================================

                    family_products = self.env[
                        "product.template"
                    ].search([

                        (
                            "vendor_family_id",
                            "=",
                            family_id
                        )

                    ])

                    # ====================================
                    # DETERMINE BEST FAMILY NAME
                    # ====================================

                    existing_name = ""

                    if family_products:

                        existing_name = family_products[0].name or ""

                    name = self._get_best_product_name(

                        url_data,

                        existing_name

                    )

                    if name:

                        vals["name"] = name

                        _logger.warning(

                            "[FAMILY NAME UPDATE] "

                            f"family={family_id} "

                            f"name={name}"

                        )

                    _logger.warning(

                        "[FAMILY UPDATE] "

                        f"family={family_id} "

                        f"count={len(family_products)}"

                    )


                    _logger.warning(

                        "[WRITE TARGETS] "

                        f"ids={family_products.ids} "

                        f"family={family_id} "

                        f"description_len={len(vals.get('description_sale', ''))}"

                    )

                    # ====================================
                    # UPDATE INTERNAL REFERENCE
                    # ====================================

                    sku = str(
                        url_data.get("sku") or ""
                    ).strip()

                    if sku:

                        for product in family_products:

                            if not product.default_code:

                                product.default_code = sku


                    family_products.write(vals)

                     # ====================================
                    # URL IMAGE ENRICHMENT
                    # ====================================

                    image_url = str(

                        url_data.get("image") or ""

                    ).strip()

                    if image_url:

                        image_data = self._download_product_image(

                            image_url

                        )

                        if image_data:

                            for product in family_products:

                                self._add_url_image_to_product(

                                    product,

                                    image_data

                                )

                    # ====================================
                    # URL IMAGE ENRICHMENT
                    # ====================================

                    _logger.warning(

                        f"[URL ENRICHED] "

                        f"{group_id} "

                        f"-> "

                        f"{url_data.get('title')}"
                    )

                else:

                    _logger.warning(

                        f"[URL ENRICHMENT EMPTY] "

                        f"{group_id}"
                    )

                # ====================================
                # SAVE PROGRESS
                # ====================================

                self.excel_url_index = idx + 1

                self._safe_commit_progress()

            except Exception as e:

                _logger.exception(

                    f"[EXCEL URL ERROR] "

                    f"{str(e)}"
                )

                self.env.cr.rollback()

        # =========================================
        # COMPLETE
        # =========================================

        if (
            self.excel_url_index >= len(rows)
            and
            rows
        ):

            _logger.warning(
                "[URL QUEUE COMPLETE]"
            )

    
            if not self.completion_email_sent:

                self.send_completion_email()
                
            self.excel_url_queue = "[]"

            self.excel_url_processing = False

            self.excel_url_index = 0

            self.state = "done"

            self._safe_commit_progress()

            self.env.invalidate_all()

        else:

            self.state = "excel_url_enrichment"

            self._safe_commit_progress()

    #=========Update excel url gallery/image 1=================
    # ADD IMAGE TO PRODUCT GALLERY
    # =========================================================
    def _download_product_image(
        self,
        image_url
     ):

        import base64
        import requests

        if not image_url:

            return False

        try:

            response = requests.get(

                image_url,

                timeout=30

            )

            response.raise_for_status()

            content_type = response.headers.get(
                "Content-Type",
                ""
            )

            if "image" not in content_type.lower():

                _logger.warning(

                    "[URL IMAGE] Invalid content type %s",

                    content_type

                )

                return False

            return base64.b64encode(
                response.content
            )

        except Exception as e:

            _logger.warning(

                "[URL IMAGE DOWNLOAD FAILED] %s",

                str(e)

            )

            return False

    #=========Update excel url gallery/image 2=================
    # ADD IMAGE TO PRODUCT GALLERY
    # =========================================================
    def _add_url_image_to_product(

        self,

        product,

        image_data

     ):

        import hashlib

        if not image_data:

            return

        # =====================================
        # Existing Gallery Images
        # =====================================

        existing_gallery = self.env[
            "product.image"
        ].search([

            ("product_tmpl_id", "=", product.id)

        ])

        image_hash = hashlib.md5(

            image_data.encode("utf-8")

        ).hexdigest()

        existing_hashes = set()

        for gallery in existing_gallery:

            if gallery.image_1920:

                existing_hashes.add(

                    hashlib.md5(

                        gallery.image_1920.encode("utf-8")

                    ).hexdigest()

                )

        # =====================================
        # Assign Main Image
        # =====================================

        if not product.image_1920:

            product.image_1920 = image_data

            _logger.warning(

                "[URL MAIN IMAGE] "

                f"{product.name}"

            )

        # =====================================
        # Skip Duplicate Gallery Image
        # =====================================

        if image_hash in existing_hashes:

            _logger.warning(

                "[URL GALLERY DUPLICATE] "

                f"{product.name}"

            )

            return

        # =====================================
        # Create Gallery Image
        # =====================================

        self.env[
            "product.image"
        ].create({

            "name":

                f"{product.name} URL",

            "product_tmpl_id":

                product.id,

            "image_1920":

                image_data

        })

        _logger.warning(

            "[URL GALLERY ADDED] "

            f"{product.name}"

        )

    #==============Enrich excel url product name=======================

    def _get_best_product_name(self, url_data, existing_name=""):

        title = str(
            url_data.get("title") or ""
        ).strip()

        sku = str(
            url_data.get("sku") or ""
        ).strip()

        if title:

            return title

        if sku:

            return sku

        return existing_name

    # ======================================================
    # LIGHTWEIGHT URL ENRICHMENT (excel url backup)
    # ======================================================

    def _extract_url_product_data(

        self,

        product_url,

        group_id=""
     ):

        try:

            _logger.warning(

                f"[URL ENRICHMENT START] "

                f"{product_url}"
            )

            raw_data = self._run_apify_actor(
                product_url
            )

            # =========================================
            # APIFY STILL RUNNING
            # =========================================

            if raw_data is None:

                _logger.warning(

                    "[EXCEL URL ENRICHMENT] "

                    "APIFY NOT READY"
                )

                return {}
            
            _logger.warning(
                "[APIFY RAW DATA]\n%s"
                % json.dumps(
                    raw_data[:3],
                    indent=4,
                    default=str
                )
            )


            if not raw_data:

                _logger.warning(

                    "[EXCEL URL ENRICHMENT] "

                    "EMPTY RESPONSE"
                )

                return {}

            first = raw_data[0] if raw_data else {}

            _logger.warning(
                "[FIRST APIFY RECORD]\n%s"
                % json.dumps(
                    first,
                    indent=4,
                    default=str
                )
            )

            # =========================================
            # BLOCKED / EMPTY
            # =========================================

            if first.get("type") in [

                "BLOCKED",

                "EMPTY"
            ]:

                _logger.warning(

                    f"[EXCEL URL ENRICHMENT] "

                    f"INVALID TYPE "

                    f"{first.get('type')}"
                )

                return {}

            # =========================================
            # NORMALIZE
            # =========================================

            structured_data = []

            for block in raw_data:

                # ======================================
                # FORMAT 1
                # Legacy URL extractor
                # ======================================

                if block.get("text"):

                    structured_data.append({

                        "source": "legacy",

                        "title": "",

                        "description": "",

                        "text": block.get("text", "").strip(),

                        "image": block.get("image"),

                        "gallery": block.get("gallery", []),

                        "sku": block.get("sku"),

                        "url": block.get("url")

                    })

                    continue

                # ======================================
                # FORMAT 2
                # Category extractor
                # ======================================

                if block.get("type") == "PRODUCTS":

                    for item in block.get("items", []):

                        structured_data.append({

                            "source": "category",

                            "title": item.get("title", "").strip(),

                            "description": item.get("description", "").strip(),

                            "text": item.get("text", "").strip(),

                            "image": item.get("image"),

                            "gallery": item.get("gallery", []),

                            "sku": item.get("sku"),

                            "url": item.get("url")

                        })

                    continue

                # ======================================
                # FORMAT 3
                # New Product Page extractor
                # ======================================

                if block.get("title"):

                    title = str(
                        block.get("title") or ""
                    ).strip()

                    description = str(
                        block.get("description") or ""
                    ).strip()

                    specs = block.get(
                        "specifications"
                    ) or []

                    # ----------------------------------
                    # Beautiful text for AI
                    # ----------------------------------

                    sections = []

                    if title:

                        sections.append(

                            f"TITLE\n{title}"

                        )

                    if description:

                        sections.append(

                            f"DESCRIPTION\n{description}"

                        )

                    if specs:

                        spec_lines = []

                        for spec in specs:

                            spec = str(spec).strip()

                            if spec:

                                spec_lines.append(

                                    f"• {spec}"

                                )

                        if spec_lines:

                            sections.append(

                                "SPECIFICATIONS\n" +

                                "\n".join(spec_lines)

                            )

                    structured_data.append({

                        "source": "product",

                        "title": title,

                        "description": description,

                        "text": "\n\n".join(sections),

                        "image": block.get("image"),

                        "gallery": block.get("gallery", []),

                        "sku": block.get("sku"),

                        "url": block.get("url")

                    })

            _logger.warning(
                "[STRUCTURED DATA SAMPLE]\n%s"
                % json.dumps(
                    structured_data[:5],
                    indent=4,
                    default=str
                )
            )

            enriched = (
                self._extract_enrichment_data_from_url(
                    structured_data,
                    group_id
                )
            )

            _logger.warning(

                "[URL ENRICHED DATA]\n%s"

                % json.dumps(
                    enriched,
                    indent=4,
                    default=str
                )
            )

            if not enriched:

                return {}
            
            _logger.warning(

                f"[URL ENRICHMENT SUCCESS] "

                f"{product_url}"
            )

           
            # =========================================
            # USE APIFY IDENTITY
            # =========================================

            product_record = {}

            for item in structured_data:

                if item.get("title"):

                    product_record = item

                    break

            return {

                "sku":

                    str(
                        product_record.get("sku") or ""
                    ).strip(),

                "title":

                    str(
                        product_record.get("title") or ""
                    ).strip(),

                "subtitle":

                    enriched.get(
                        "subtitle",
                        ""
                    ),

                "description":

                    enriched.get(
                        "description",
                        ""
                    ),

                "material":

                    enriched.get(
                        "material",
                        ""
                    ),

                "capacity":

                    enriched.get(
                        "capacity",
                        ""
                    ),

                "dimensions":

                    enriched.get(
                        "dimensions",
                        ""
                    ),

                "specifications":

                    enriched.get(
                        "specifications",
                        ""
                    )

            }

        except Exception as e:

            _logger.warning(

                f"[EXCEL URL ENRICHMENT FAILED] "

                f"{str(e)}"
            )

            return {}


    #=====excel group url update====================================

    def _enrich_group_with_url_data(

        self,

        group_items,

        url_cache=None
    ):


        if url_cache is None:

            url_cache = {}

        group_url = ""

        # =====================================
        # FIND FIRST VALID GROUP URL
        # =====================================

        for item in group_items:

            possible_url = (
                item.get("url")
                or
                item.get("product_url")
                or
                ""
            ).strip()

            if possible_url:

                group_url = possible_url

                break

        # =====================================
        # NO URL FOUND
        # =====================================

        if not group_url:

            _logger.warning(

                "[URL ENRICHMENT SKIPPED] "

                "NO URL FOUND"
            )

            return {}

        _logger.warning(

            f"[URL GROUP FOUND] "

            f"{group_url}"
        )

        # =====================================
        # CACHE HIT
        # =====================================

        if group_url in url_cache:

            _logger.warning(

                f"[URL CACHE HIT] "

                f"{group_url}"
            )

            return url_cache[group_url]

        try:

            _logger.warning(

                f"[URL ENRICHMENT START] "

                f"{group_url}"
            )

            url_data = self._extract_url_product_data(
                group_url
            ) or {}


            # =====================================
            # EMPTY RESPONSE
            # =====================================

            if not url_data:

                _logger.warning(

                    f"[URL ENRICHMENT EMPTY] "

                    f"{group_url}"
                )

                url_cache[group_url] = {}

                return {}

            url_cache[group_url] = url_data

            _logger.warning(

                f"[URL ENRICHMENT SUCCESS] "

                f"{group_url} "

                f"| keys={list(url_data.keys())}"
            )

            return url_data

        except Exception as e:

            _logger.warning(

                f"[URL ENRICHMENT FAILED] "

                f"{group_url} "

                f"| {str(e)}"
            )

            return {}

    #===============EXCEL URL LAST CREATED============================
   
    def _build_excel_url_queue(
       self,

        grouped_products,

        family_lookup=None
    ):

        import json

        queue = []

        seen_urls = set()

        for group_id, items in grouped_products.items():

            for item in items:

                url = (
                    item.get("url")
                    or ""
                ).strip()

                if not url:
                    continue

                if url in seen_urls:
                    break

                seen_urls.add(url)

                # queue.append({

                family_info = family_lookup.get(group_id, {})

                _logger.warning(

                    "[QUEUE BUILD] "

                    f"group={group_id} "

                    f"family_info={family_info}"

                )

                queue.append({

                    "group_id":

                        group_id,

                    "vendor_family_id":

                        family_info.get(
                            "family_id"
                        ),

                    "template_id":

                        family_info.get(
                            "template_id"
                        ),

                    "url":

                        url

                })

                break

        self.excel_url_queue = json.dumps(
            queue
        )

        _logger.warning(

            f"[EXCEL URL QUEUE] "

            f"{len(queue)} queued"
        )

        _logger.warning(
            "[URL QUEUE BUILT] "
            f"groups={len(queue)}"
        )

        for i, item in enumerate(queue):

            _logger.warning(

                "[QUEUE %s] "

                "group=%s "

                "family=%s "

                "url=%s",

                i,

                item.get("group_id"),

                item.get("family_id"),

                item.get("url")

            )
    
    # ==============================================================
    # URL AI PRODUCT EXTRACTOR (DEAD CODE)
    # =============================================================

    def _extract_url_product_data_ai(
        self,
        pages
    ):

        import json
        import re

        try:

            api_key = self.env[
                'ir.config_parameter'
            ].sudo().get_param(
                'openai.api.key'
            )

            if not api_key:

                _logger.warning(
                    "[URL AI] NO API KEY"
                )

                return {}

            client = OpenAI(
                api_key=api_key
            )

            # =========================================
            # FLATTEN BLOCKS
            # =========================================

            all_blocks = [

                b

                for p in pages

                for b in p.get(
                    "blocks",
                    []
                )
            ]

            if not all_blocks:

                return {}

            cleaned_blocks = (
                self._clean_scraped_blocks(
                    all_blocks
                )
            )

            if not cleaned_blocks:

                return {}

            combined_text = "\n\n---\n\n".join([

                f"""
                TEXT:
                {b.get('text','')}

                PRICE:
                {b.get('price','')}

                STOCK:
                {b.get('stock','')}

                IMAGE_URL:
                {b.get('image','')}
                """

                for b in cleaned_blocks
            ])

            if not combined_text.strip():

                return {}

            if len(combined_text) > 15000:

                combined_text = (
                    combined_text[:15000]
                )

            # =========================================
            # SIMPLE PRODUCT EXTRACTION
            # =========================================

            prompt = f"""
            Extract the main product.

            Return ONLY valid JSON.

            Format:

            {{
                "name": "",
                "description": "",
                "category": ""
            }}

            TEXT:

            {combined_text}
            """

            response = client.responses.create(

                model="gpt-4.1-mini",

                input=prompt,

                temperature=0,

                timeout=60
            )

            result = (
                response.output_text
                .strip()
            )

            result = re.sub(

                r"^```(?:json)?|```$",

                "",

                result

            ).strip()

            data = json.loads(
                result
            )

            if not isinstance(
                data,
                dict
            ):

                return {}

            _logger.warning(

                f"[URL AI SUCCESS] "

                f"{data.get('name')}"
            )

            return {

                "name":
                    data.get("name"),

                "description":
                    data.get(
                        "description"
                    ),

                "category":
                    data.get(
                        "category"
                    ),

                "images": []
            }

        except Exception as e:

            _logger.warning(

                f"[URL AI FAILED] "

                f"{str(e)}"
            )

            return {}

    #====Excel variant mapping==================================
    def _detect_basic_image_color(self, image_data):

        try:

            import base64
            from io import BytesIO

            from PIL import Image

            img = Image.open(
                BytesIO(
                    base64.b64decode(image_data)
                )
            ).convert("RGB")

            img = img.resize((50, 50))

            colors = img.getcolors(
                50 * 50
            )

            if not colors:
                return False


            # =====================================
            # REMOVE BACKGROUND COLORS
            # =====================================

            filtered_colors = []

            for count, rgb in colors:

                r, g, b = rgb

                # skip near-white backgrounds
                if r > 220 and g > 220 and b > 220:
                    continue

                # skip light grey/silver reflections
                if abs(r - g) < 15 and abs(g - b) < 15 and r > 170:
                    continue

                filtered_colors.append(
                    (count, rgb)
                )


            # fallback if everything removed
            if filtered_colors:
                dominant = max(
                    filtered_colors,
                    key=lambda x: x[0]
                )[1]
            else:
                dominant = max(
                    colors,
                    key=lambda x: x[0]
                )[1]


            r, g, b = dominant


            _logger.warning(
                f"[COLOR RGB] r={r} g={g} b={b}"
            )


            # =====================================
            # BASIC COLOR MAPPING
            # =====================================

            if r > 200 and g > 200 and b > 200:
                return "White"

            if r < 60 and g < 60 and b < 60:
                return "Black"

            if r > 180 and g < 120 and b < 80:
                return "Orange"

            if r > 180 and g < 80 and b < 80:
                return "Red"

            # =====================================
            # BLUE FAMILY
            # =====================================

            if b > r and b > g:

                # NAVY / DARK BLUE
                if b < 120:
                    return "Navy"

                # LIGHT BLUE / CYAN
                if g > 140:
                    return "Light Blue"

                # ROYAL / NORMAL BLUE
                return "Blue"

            if g > 140 and r < 120:
                return "Green"

            if r > 150 and g > 150 and b < 120:
                return "Yellow"

            # =====================================
            # BLUE FAMILY FALLBACK
            # =====================================

            if b > r and b > g:

                # deep navy
                if b < 120:
                    return "Navy"

                # light blue / cyan
                if g > 120:
                    return "Light Blue"

                return "Blue"


            # =====================================
            # GREEN FAMILY FALLBACK
            # =====================================

            if g > r and g > b:

                if g > 160 and r > 120:
                    return "Lime Green"

                return "Green"


            # =====================================
            # RED / ORANGE
            # =====================================

            if r > g and r > b:

                if g > 100:
                    return "Orange"

                return "Red"


            # =====================================
            # DARK COLORS
            # =====================================

            if r < 90 and g < 90 and b < 120:
                return "Black"


            # =====================================
            # FINAL FALLBACK
            # =====================================

            return "Grey"

        except Exception as e:

            _logger.warning(

                f"[COLOR DETECTION FAILED] "

                f"{str(e)}"
            )

            return False

    #====extract_enrichment_data_from_url==================================
    def _extract_enrichment_data_from_url(
        self,
        structured_data,
        group_id
    ):

        import json
        import re

        api_key = self.env[
            'ir.config_parameter'
        ].sudo().get_param(
            'openai.api.key'
        )

        if not api_key:
            return {}

        client = OpenAI(
            api_key=api_key
        )

        # ==========================================
        # BUILD WELL-FORMATTED AI INPUT
        # ==========================================

        sections = []

        for item in structured_data:

            # --------------------------------------
            # New Product Page Format
            # --------------------------------------

            if item.get("title"):

                block = []

                title = str(
                    item.get("title") or ""
                ).strip()

                description = str(
                    item.get("description") or ""
                ).strip()

                specs = item.get(
                    "specifications"
                ) or []

                if title:

                    block.append(

                        "PRODUCT TITLE\n"

                        f"{title}"

                    )

                if description:

                    block.append(

                        "DESCRIPTION\n"

                        f"{description}"

                    )

                if specs:

                    spec_lines = []

                    for spec in specs:

                        spec = str(spec).strip()

                        if spec:

                            spec_lines.append(

                                f"• {spec}"

                            )

                    if spec_lines:

                        block.append(

                            "SPECIFICATIONS\n"

                            + "\n".join(spec_lines)

                        )

                sections.append(

                    "\n\n".join(block)

                )

                continue

            # --------------------------------------
            # Legacy Support
            # --------------------------------------

            text = str(
                item.get("text") or ""
            ).strip()

            if text:

                sections.append(text)

        combined_text = "\n\n".join(sections)

        if not combined_text.strip():

            return {}
        

        # ==========================================
        # BUILD AI PAYLOAD
        # ==========================================

        product_payload = []

        for item in structured_data:

            # --------------------------------------
            # New Product Page Format
            # --------------------------------------

            if item.get("title"):

                specs = item.get("specifications") or []

                # Normalize specifications into a list
                if isinstance(specs, str):

                    specs = [

                        line.strip()

                        for line in specs.splitlines()

                        if line.strip()

                    ]

                elif not isinstance(specs, list):

                    specs = [str(specs)]

                product_payload.append({

                    "sku": str(
                        item.get("sku") or ""
                    ).strip(),

                    "title": str(
                        item.get("title") or ""
                    ).strip(),

                    "description": str(
                        item.get("description") or ""
                    ).strip(),

                    "specifications": specs,

                })

                continue

            # --------------------------------------
            # Legacy Support
            # --------------------------------------

            text = str(
                item.get("text") or ""
            ).strip()

            if text:

                product_payload.append({

                    "text": text

                })


        prompt = f"""
        You are an AI product enrichment engine.

        The product has ALREADY been identified.

        DO NOT identify products.

        DO NOT search for products.

        DO NOT compare products.

        DO NOT invent information.

        The SKU and product title have already been extracted directly from the supplier website.

        Your ONLY task is to clean and organise the product information.

        ========================================================
        KNOWN PRODUCT
        ========================================================

        SKU

        {product_payload[0].get("sku", group_id) if product_payload else group_id}
        ========================================================
        YOUR TASK
        ========================================================

        Extract and organise ONLY:

        • subtitle
        
        • sku

        • description

        • material

        • capacity

        • dimensions

        • specifications

        Rules

        - Keep the supplier wording.

        - Do NOT rewrite marketing text.

        - Do NOT summarise.

        - Do NOT shorten.

        - Do NOT invent information.

        - Preserve important product features.

        - Preserve technical information.

        - If useful information exists inside Specifications,
        include it naturally inside the description as well.

        - Return ALL specification items.

        - Do NOT remove bullet points.

        - Ignore duplicated lines.

        - Ignore repeated headings.

        - Ignore repeated product titles.

        ========================================================
        RETURN JSON ONLY
        ========================================================

        {{
            "subtitle":"",
            "sku":"",
            "description":"",
            "material":"",
            "capacity":"",
            "dimensions":"",
            "specifications":[]
        }}

        ========================================================
        SUPPLIER DATA
        ========================================================

        {json.dumps(product_payload, indent=2)}
        """

        _logger.warning(

            "[URL ENRICHMENT INPUT]\n%s"

            % combined_text[:5000]
        )

        _logger.warning(

            f"[AI TARGET PRODUCT] "

            f"{group_id}"
        )

        try:

            response = client.responses.create(

                model="gpt-4.1-mini",

                input=prompt,

                temperature=0,

                timeout=60
            )

            # =========================================
            # GET AI RESPONSE TEXT
            # =========================================

            result = (

                response.output_text

                or ""

            ).strip()

            _logger.warning(

                "[URL ENRICHMENT RAW RESPONSE]\n%s"

                % result[:5000]
            )

            # =========================================
            # CLEAN JSON WRAPPERS
            # =========================================

            result = re.sub(

                r"^```(?:json)?|```$",

                "",

                result

            ).strip()

            # =========================================
            # PARSE JSON
            # =========================================

            parsed = json.loads(
                result
            )

            _logger.warning(

                "[URL ENRICHMENT OUTPUT]\n%s"

                % json.dumps(
                    parsed,
                    indent=4,
                    default=str
                )
            )

            _logger.warning(
                "[URL ENRICHMENT RETURNING DATA]"
            )

            # ==========================================
            # NORMALIZE AI RESPONSE
            # ==========================================

            def clean(value):

                if value is None:

                    return ""

                if isinstance(value, list):

                    return "\n".join(

                        str(v).strip()

                        for v in value

                        if str(v).strip()

                    )

                return str(value).strip()


            _logger.warning(

                "[URL ENRICHMENT TYPES] "

                f"title={type(parsed.get('title')).__name__} | "
               
                f"title={type(parsed.get('sku')).__name__} | "

                f"subtitle={type(parsed.get('subtitle')).__name__} | "

                f"description={type(parsed.get('description')).__name__} | "

                f"specifications={type(parsed.get('specifications')).__name__}"

            )

            return {

                "title":

                    clean(
                        parsed.get("title")
                    ),

                "sku":

                    clean(
                        parsed.get("sku")
                    ),

                "subtitle":

                    clean(
                        parsed.get("subtitle")
                    ),

                "description":

                    clean(
                        parsed.get("description")
                    ),

                "material":

                    clean(
                        parsed.get("material")
                    ),

                "capacity":

                    clean(
                        parsed.get("capacity")
                    ),

                "dimensions":

                    clean(
                        parsed.get("dimensions")
                    ),

                "specifications":

                    clean(
                        parsed.get("specifications")
                    )

            }

        except Exception as e:

            _logger.warning(

                f"[URL ENRICHMENT AI ERROR] "

                f"{str(e)}"
            )

            return {}


    #==========create excel product=================================
    def create_products_excel(self):

        import json
        import re

        _logger.warning(
            "[EXCEL CREATE] START"
        )


        # =====================================================
        # VALIDATION
        # =====================================================

        if not self.ai_response:

            _logger.warning(

                "[EXCEL CREATE] "

                "NO AI RESPONSE"
            )

            # ====================================
            # RECOVERY PATH
            # ====================================

            if self.is_excel_parsed:

                _logger.warning(

                    "[EXCEL CREATE] "

                    "PARSED COMPLETE "

                    "→ MOVE TO REVIEW"
                )

                self.last_error = (
                    "Excel AI response missing"
                )

                self.last_known_state = (
                    "excel_creating"
                )

                self.state = "review"

                self._safe_commit_progress()

            return

        try:

            ai_pages = json.loads(
                self.ai_response or "[]"
            )

        except Exception as e:

            _logger.exception(

                f"[EXCEL CREATE] "

                f"INVALID AI JSON "

                f"| {str(e)}"
            )

            return


        if not ai_pages:

            _logger.warning(
                "[EXCEL CREATE] EMPTY AI"
            )

            return


        ai_page = ai_pages[0]

        products = ai_page.get(
            "products",
            []
        )


        _logger.warning(

            f"[EXCEL CREATE] "

            f"RAW PRODUCTS={len(products)}"
        )


        if not products:

            return


        # =====================================================
        # MODELS
        # =====================================================

        product_obj = self.env[
            'product.template'
        ]

        category_obj = self.env[
            'product.category'
        ]

        attribute_obj = self.env[
            'product.attribute'
        ]

        attribute_value_obj = self.env[
            'product.attribute.value'
        ]

        line_obj = self.env[
            'product.template.attribute.line'
        ]

        stock_quant_obj = self.env[
            'stock.quant'
        ]

        warehouse = self.env[
            'stock.warehouse'
        ].search(
            [],
            limit=1
        )

        stock_location = (
            warehouse.lot_stock_id
            if warehouse
            else False
        )

        # =====================================================
        # ROOT CATEGORY
        # =====================================================

        parent_category = category_obj.search([

            ('name', '=', "All Products")

        ], limit=1)


        # if not parent_category:

        #     parent_category = category_obj.create({

        #         'name': "All Products"

        #     })


        # # =====================================================
        # # CATEGORY MAP
        # # =====================================================

        # CATEGORY_MAPPING = {

        #     "t-shirt": "Apparel",
        #     "shirt": "Apparel",
        #     "polo": "Apparel",
        #     "bag": "Bags",
        #     "backpack": "Bags",
        #     "cap": "Headwear",
        #     "hat": "Headwear",
        #     "bottle": "Drinkware",
        #     "drinkware": "Drinkware",
        #     "pen": "Stationery",
        #     "notebook": "Stationery",
        #     "powerbank": "Electronics",
        #     "charger": "Electronics",
        #     "laptop": "Electronics",
        # }


        # =====================================================
        # GROUP PRODUCTS
        # =====================================================

        grouped_products = {}

        for p in products:

            raw_name = (
                p.get("name") or ""
            ).strip()


            variant_group = (
                p.get("variant_group")
            )


            # ============================================
            # PRIORITY 1:
            # USE EXPLICIT VARIANT GROUP
            # ============================================

            if variant_group:

                group_id = str(
                    variant_group
                ).strip().upper()


            # ============================================
            # PRIORITY 2:
            # USE PRODUCT ID
            # ============================================

            elif p.get("id"):

                group_id = str(
                    p.get("id")
                ).strip().upper()


            # ============================================
            # PRIORITY 3:
            # FALLBACK TO RAW NAME
            # ============================================

            else:

                normalized_name = re.sub(

                    r'[\W_]+',

                    ' ',

                    raw_name
                ).strip().upper()


                # ============================================
                # INVALID / GENERIC NAMES
                # ============================================

                generic_names = [

                    'PRODUCT',
                    'ITEM',
                    'GOODS',
                    'SAMPLE',
                    'TEST',
                    'UNKNOWN',

                    'SPORTS BOTTLE',
                    'BOTTLE',
                    'TRAVEL MUG',
                    'TRAVEL CUP',
                    'DRINKWARE MUG',
                    'THERMAL BOTTLE',
                    'MUG',
                    'CUP',
                ]


                # ============================================
                # SAFE NAME GROUPING
                # ============================================

                if (

                    normalized_name

                    and normalized_name not in generic_names

                    and not re.match(
                        r'^PRODUCT\s+\d+$',
                        normalized_name,
                        re.I
                    )

                ):

                    group_id = normalized_name

                else:

                    # =============================================
                    # FINAL HARD FALLBACK
                    # =============================================

                    group_id = f"ROW_{len(grouped_products)}"


            grouped_products.setdefault(

                group_id,

                []

            ).append(p)


        grouped_keys = list(
            grouped_products.keys()
        )


        _logger.warning(

            f"[EXCEL GROUPS] "

            f"TOTAL={len(grouped_keys)}"
        )

        # =====================================================
        # BATCH GROUPS
        # =====================================================

        BATCH_SIZE = 10

        start = (
            self.excel_created_index or 0
        )

        end = min(

            start + BATCH_SIZE,

            len(grouped_keys)
        )


        _logger.warning(

            f"[EXCEL BATCH] "

            f"{start} → {end}"
        )


        created_count = 0
        merged_count = 0

        # =====================================================
        # IMPORT FAMILY LOOKUP
        # (ACCUMULATE ACROSS CREATE BATCHES)
        # =====================================================

        try:

            family_lookup = json.loads(

                self.family_lookup_json or "{}"

            )

            if not isinstance(family_lookup, dict):

                family_lookup = {}

        except Exception:

            family_lookup = {}

        _logger.warning(

            "[FAMILY LOOKUP LOADED] "

            f"{len(family_lookup)} existing families"

        )


        # =====================================================
        # PROCESS GROUPS
        # =====================================================

        for group_idx in range(start, end):

            try:

                group_id = grouped_keys[
                    group_idx
                ]

                group_items = grouped_products[
                    group_id
                ]


                _logger.warning(

                    f"[EXCEL GROUP] "

                    f"{group_id} "

                    f"| items={len(group_items)}"
                )


                main_product = (
                    group_items[0]
                )

                fingerprint = self._build_vendor_fingerprint(
                    main_product
                )

                raw_name = (

                    main_product.get(
                        "name"
                    ) or ""

                ).strip()


                # =====================================================
                # VALIDATE PRODUCT NAME
                # =====================================================

                invalid_name = False


                if not raw_name:

                    invalid_name = True


                elif re.fullmatch(r'[\d\W_]+', raw_name):

                    invalid_name = True


                elif len(raw_name) < 3:

                    invalid_name = True

                elif raw_name.lower() in [

                    'product',
                    'item',
                    'goods',
                    'sample',
                    'test',
                    'n/a',
                    'unknown',

                    # =====================================
                    # GENERIC AI NAMES
                    # =====================================

                    'sports bottle',
                    'bottle',
                    'travel mug',
                    'travel cup',
                    'drinkware mug',
                    'thermal bottle',
                    'mug',
                    'cup',
                ]:

                    invalid_name = True


                elif re.match(

                    r'^(variant|color|size|style)\s*\d*$',

                    raw_name,

                    re.I
                ):

                    invalid_name = True


                # =====================================================
                # FINAL NAME
                # =====================================================

                if invalid_name:

                    # =========================================
                    # STRICT FALLBACK NAME
                    # =========================================

                    name = f"Product {group_id}"

                    _logger.warning(

                        f"[NAME FALLBACK] "

                        f"{raw_name} "

                        f"-> "

                        f"{name}"
                    )

                else:

                    name = raw_name

                description = (

                    main_product.get(
                        "description"
                    ) or ""
                )

                raw_category = (

                    main_product.get(
                        "category"
                    ) or ""

                ).lower()

                mapped_category = self._map_product_category(

                    raw_category

                )

                category = self._get_or_create_product_category(

                    mapped_category,

                    source="excel"

                )


                # ================================================
                # FIND BY PRODUCT CODE FIRST
                # ================================================

                vendor_id = self.partner_id.id if self.partner_id else False

                product = False

                # =====================================================
                # 1. STRICT FINGERPRINT MATCH
                # =====================================================

                if (
                    'vendor_fingerprint' in product_obj._fields
                    and vendor_id
                ):

                    product = product_obj.search([

                        (
                            'vendor_fingerprint',
                            '=',
                            fingerprint
                        ),

                        (
                            'vendor_id',
                            '=',
                            vendor_id
                        )

                    ], limit=1)


                    if product:

                        _logger.warning(

                            f"[FINGERPRINT MATCH] "

                            f"{group_id} "

                            f"| vendor={vendor_id} "

                            f"| product_id={product.id}"
                        )

                 # =====================================================
                # 2. FALLBACK SKU MATCH
                # =====================================================

                if not product and vendor_id:

                    product = product_obj.search([

                        (
                            'default_code',
                            '=',
                            group_id
                        ),

                        (
                            'vendor_id',
                            '=',
                            vendor_id
                        )

                    ], limit=1)


                    if product:

                        _logger.warning(

                            f"[SKU MATCH] "

                            f"{group_id} "

                            f"| vendor={vendor_id} "

                            f"| product_id={product.id}"
                        )

                is_new_product = False

                if product:

                    _logger.warning(
                        f"[EXCEL DUPLICATE FOUND] "
                        f"{group_id} | vendor={vendor_id} | product_id={product.id}"
                    )

                else:
                    is_new_product = True


                # =================================================
                # CREATE PARENT
                # =================================================

                catalogue_currency = self._resolve_catalogue_currency(

                    extracted_currency=main_product.get(
                        "currency"
                    ),

                    price_text=main_product.get(
                        "price_text"
                    ),

                )

                if is_new_product:

                    vals = {

                        'name': name,

                        'default_code':
                            group_id,

                        'description_sale':
                            description,

                       'type': 'consu',

                        'categ_id':
                            category.id,

                        'sale_ok': True,

                        'website_published':
                            False,

                        # =====================================
                        # SAVE VENDOR LINK
                        # =====================================

                        'vendor_id':
                            vendor_id,

                        'vendor_stock_qty': int(
                            main_product.get(
                                "stock",
                                0
                            ) or 0
                        ),

                        'vendor_price': self._safe_float(
                            main_product.get("price")
                        ),

                        'vendor_currency_id':
                                catalogue_currency.id,

                        'vendor_fingerprint': fingerprint,

                        'vendor_import_job_id': self.id,
                    }


                    image = main_product.get(
                        "image"
                    )


                    if image:

                        vals[
                            'image_1920'
                        ] = image


                    _logger.warning(
                        f"[TYPE FIELD VALUES] "
                        f"{product_obj._fields['type'].selection}"
                    )

                    #===============peoduct creation====================
                    product = product_obj.create(
                        vals
                    )

                   
                    # ==========================================
                    # KEEP FAMILY LOOKUP
                    # ==========================================

                    family_id = self._get_or_create_family_id(product)

                    family_lookup[group_id] = {

                        "family_id": family_id,

                        "product_id": product.id,

                        "template_id": product.id,

                        "vendor_id": vendor_id,

                    }

                    self.family_lookup_json = json.dumps(

                        family_lookup

                    )

                    self.family_lookup_json = json.dumps(
                        family_lookup
                    )

                    _logger.warning(

                        "[FAMILY LOOKUP SAVED] "

                        f"families={len(family_lookup)}"

                    )

                    _logger.warning(

                        "[LOOKUP ENTRY] %s",

                        family_lookup[group_id]

                    )

                    _logger.warning(

                        "[FAMILY REUSED] "

                        f"group={group_id} "

                        f"family={family_id}"

                    )
                    _logger.warning(

                        f"[NEW PRODUCT] "

                        f"id={product.id} | "

                        f"group_id={group_id} | "

                        f"default_code={product.default_code} | "

                        f"name={product.name} | "

                        f"fingerprint={product.vendor_fingerprint}"
                    )

                    #===========currency conversion======
                    product._update_converted_price()

                    # ✅ SAFE TRANSLATION CALL (PLUG-IN)
                    self._apply_product_translation(product)
                   
                    created_count += 1

                    _logger.warning(

                        f"[MERGED PRODUCT] "

                        f"id={product.id} | "

                        f"group_id={group_id} | "

                        f"default_code={product.default_code} | "

                        f"name={product.name} | "

                        f"fingerprint={product.vendor_fingerprint}"
                    )

                    _logger.warning(

                        f"[EXCEL CREATED] "

                        f"{group_id} "

                        f"| vendor={vendor_id}"
                    )

                else:

                    merged_count += 1

                    # ==========================================
                    # KEEP FAMILY LOOKUP
                    # ==========================================

                    family_id = self._get_or_create_family_id(product)

                    family_lookup[group_id] = {

                        "family_id": family_id,

                        "product_id": product.id,

                        "template_id": product.id,

                        "vendor_id": vendor_id,

                    }

                    self.family_lookup_json = json.dumps(
                        family_lookup
                    )

                    _logger.warning(

                        "[FAMILY LOOKUP SAVED] "

                        f"families={len(family_lookup)}"

                    )

                    _logger.warning(

                        "[LOOKUP ENTRY] %s",

                        family_lookup[group_id]

                    )

                    _logger.warning(

                        "[FAMILY REUSED] "

                        f"group={group_id} "

                        f"family={family_id}"

                    )

                    # =====================================
                    # TRANSLATE EXISTING PRODUCT TOO
                    # =====================================

                    self._apply_product_translation(product)

                    _logger.warning(

                        f"[EXCEL EXISTING PRODUCT] "

                        f"{group_id} "

                        f"| vendor={vendor_id} "

                        f"| product_id={product.id}"
                    )
              
                # ==================================================
                # VARIANTS
                # ==================================================

                for idx, item in enumerate(group_items):

                    # =============================================
                    # DETECT ATTRIBUTE TYPE
                    # =============================================

                    variant_attribute_name = "Variant"

                    if item.get("color") or item.get("colour"):

                        variant_attribute_name = "Color"

                    elif item.get("material"):

                        variant_attribute_name = "Material"

                    elif item.get("size"):

                        variant_attribute_name = "Size"

                    elif item.get("capacity"):

                        variant_attribute_name = "Capacity"

                    elif item.get("style"):

                        variant_attribute_name = "Style"


                    # =============================================
                    # RAW ATTRIBUTE VALUE
                    # =============================================

                    attr_value = str(

                        item.get("color")

                        or item.get("colour")

                        or item.get("material")

                        or item.get("size")

                        or item.get("variant")

                        or item.get("capacity")

                        or item.get("style")

                        or ""

                    ).strip()


                    # ===============================================
                    # IMAGE COLOR FALLBACK
                    # ===============================================

                    if not attr_value:

                        detected_color = self._detect_basic_image_color(
                            item.get("image")
                        )

                        if detected_color:

                            variant_attribute_name = "Color"

                            attr_value = detected_color.title()

                            _logger.warning(

                                f"[IMAGE COLOR DETECTED] "

                                f"{attr_value}"
                            )


                    # =============================================
                    # FINAL SAFE FALLBACK
                    # =============================================

                    if not attr_value:

                        attr_value = f"Variant {idx+1}"

                    
                    _logger.warning(

                        f"[VARIANT DETECTED] "

                        f"{variant_attribute_name} "

                        f"= {attr_value}"
                    )


                    # =============================================
                    # ATTRIBUTE
                    # =============================================

                    attribute = attribute_obj.search([

                        (
                            'name',
                            '=',
                            variant_attribute_name
                        )

                    ], limit=1)


                    if not attribute:

                        attribute = attribute_obj.create({

                            'name': variant_attribute_name

                        })


                        _logger.warning(

                            f"[ATTRIBUTE CREATED] "

                            f"{variant_attribute_name}"
                        )


                    # =============================================
                    # ATTRIBUTE VALUE
                    # =============================================

                    value = attribute_value_obj.search([

                        (
                            'name',
                            '=',
                            attr_value
                        ),

                        (
                            'attribute_id',
                            '=',
                            attribute.id
                        )

                    ], limit=1)

                    if not value:

                        value = attribute_value_obj.create({

                            'name': attr_value,

                            'attribute_id': attribute.id
                        })


                        # =========================================
                        # TRANSLATE VARIANT VALUE
                        # =========================================

                        try:

                            for lang_code in ['ru_RU', 'az_AZ']:

                                translated_variant = self._force_translate(

                                    attr_value,

                                    lang_code
                                )


                                if translated_variant:

                                    value.with_context(
                                        lang=lang_code
                                    ).write({

                                        'name': translated_variant
                                    })


                                    _logger.warning(

                                        f"[VARIANT TRANSLATED] "

                                        f"{attr_value} "

                                        f"-> "

                                        f"{translated_variant} "

                                        f"({lang_code})"
                                    )

                        except Exception as e:

                            _logger.warning(

                                f"[VARIANT TRANSLATION ERROR] "

                                f"{str(e)}"
                            )


                        _logger.warning(

                            f"[ATTRIBUTE VALUE CREATED] "

                            f"{attr_value}"
                        )


                    # =============================================
                    # TEMPLATE ATTRIBUTE LINE
                    # =============================================

                    line = line_obj.search([

                        (
                            'product_tmpl_id',
                            '=',
                            product.id
                        ),

                        (
                            'attribute_id',
                            '=',
                            attribute.id
                        )

                    ], limit=1)


                    if not line:

                        line = line_obj.create({

                            'product_tmpl_id': product.id,

                            'attribute_id': attribute.id,

                            'value_ids': [

                                (
                                    6,
                                    0,
                                    [value.id]
                                )
                            ]
                        })


                        _logger.warning(

                            f"[VARIANT LINE CREATED] "

                            f"{group_id}"
                        )

                    else:

                        if value.id not in line.value_ids.ids:

                            line.value_ids = [

                                (
                                    4,
                                    value.id
                                )
                            ]


                            _logger.warning(

                                f"[VARIANT ADDED] "

                                f"{group_id} "

                                f"| {attr_value}"
                            )


                    # =============================================
                    # VARIANT IMAGE
                    # =============================================

                    variant_record = self.env[
                        'product.product'
                    ].search([

                        (
                            'product_tmpl_id',
                            '=',
                            product.id
                        ),

                        (
                            'product_template_attribute_value_ids.product_attribute_value_id',
                            '=',
                            value.id
                        )

                    ], limit=1)


                    if variant_record:

                        variant_image = item.get(
                            "image"
                        )


                        if variant_image:

                            variant_record.image_1920 = (
                                variant_image
                            )


                            _logger.warning(

                                f"[VARIANT IMAGE] "

                                f"{group_id} "

                                f"| {attr_value}"
                            )

                # =====================================
                # FORCE VARIANT GENERATION
                # SAME AS PDF FLOW
                # =====================================

                product._create_variant_ids()

                product.flush_recordset()

                product.invalidate_recordset()

                # =====================================================
                # PROPAGATE FAMILY ID TO VARIANTS
                # =====================================================

                for variant in product.product_variant_ids:

                    if variant.vendor_family_id != product.vendor_family_id:

                        variant.vendor_family_id = (

                            product.vendor_family_id

                        )

                _logger.warning(

                    "[FAMILY PROPAGATED] "

                    f"{product.vendor_family_id} "

                    f"variants={len(product.product_variant_ids)}"

                )

                for v in product.product_variant_ids:

                    _logger.warning(
                        f"[GENERATED VARIANT] "
                        f"id={v.id} "
                        f"type={v.type}"
                    )

                _logger.warning(
                    f"[EXCEL VARIANTS GENERATED] "
                    f"product={product.name} "
                    f"variant_count={len(product.product_variant_ids)} "
                    f"variant_ids={product.product_variant_ids.ids}"
                )

                
                #========================================
                # APPLY STOCK (SAME AS PDF FLOW)
                # ========================================

                stock_qty = int(
                    main_product.get(
                        "stock",
                        0
                    ) or 0
                )

                self._apply_catalog_stock(
                    product,
                    stock_qty,
                    stock_quant_obj,
                    stock_location
                )

                # ==========================================================
                # FINALIZE PRODUCT
                # ==========================================================

                try:

                    product.finalize_product()

                    _logger.warning(

                        "[PRODUCT FINALIZED] "

                        "product=%s",

                        product.display_name,

                    )

                except Exception:

                    _logger.exception(

                        "[PRODUCT FINALIZE FAILED] "

                        "product=%s",

                        product.display_name,

                    )

                # =================================================
                # SAVE PROGRESS
                # =================================================

                self.excel_created_index = (
                    group_idx + 1
                )


                self._safe_commit_progress()
                

                _logger.warning(

                    f"[EXCEL SAVE] "

                    f"index="

                    f"{self.excel_created_index}"
                )


            except Exception as e:

                _logger.exception(

                    f"[EXCEL GROUP ERROR] "

                    f"group_idx={group_idx} "

                    f"| {str(e)}"
                )

                self.env.cr.rollback()


        # =====================================================
        # FINAL LOG
        # =====================================================

        _logger.warning(

            f"[EXCEL COMPLETE] "

            f"created={created_count} "

            f"| merged={merged_count}"
        )


        # ======================================================
        # NEXT STATE
        # ======================================================

        if self.excel_created_index >= len(grouped_keys):

            _logger.warning(

                "[EXCEL FLOW] "

                "GROUP BATCH COMPLETE"
            )


            # ============================================
            # FULL IMPORT COMPLETED
            # ============================================

            if self.is_excel_parsed:
                _logger.warning(

                    f"[EXCEL PARSED CHECK] "

                    f"is_excel_parsed={self.is_excel_parsed}"
                )

                _logger.warning(
                    "[EXCEL IMPORT COMPLETE] ✅"
                )

                # =========================================
                # FINAL RESET
                # =========================================

                self.excel_created_index = 0

                self.excel_ai_index = 0

                # =====================================================
                # SAVE FAMILY LOOKUP
                # =====================================================

                self.family_lookup_json = json.dumps(
                    family_lookup
                )

                _logger.warning(

                    "[FAMILY LOOKUP SAVED]\n%s"

                    % json.dumps(

                        family_lookup,

                        indent=4

                    )

                )

                # =========================================
                # BUILD URL QUEUE FROM FINAL PRODUCT SET
                # =========================================

                self._build_excel_url_queue(

                    grouped_products,

                    family_lookup

                )

                queue = json.loads(
                    self.excel_url_queue or "[]"
                )

                _logger.warning(

                    f"[URL QUEUE FINAL CHECK] "

                    f"queue_count={len(queue)} | "

                    f"queue={queue}"
                )

                # ==========================================
                # URL ENRICHMENT REQUIRED
                # ==========================================

                if queue:

                    _logger.warning(

                        "[EXCEL FLOW] "

                        "START URL ENRICHMENT"
                    )

                    self.excel_url_processing = True

                    self.excel_url_index = 0

                    self.last_known_state = (
                        "excel_url_enrichment"
                    )

                    self.state = (
                        "excel_url_enrichment"
                    )

                    self._safe_commit_progress()

                    return

                # =========================================
                # NO URLS FOUND
                # =========================================

                else:

                    _logger.warning(

                        "[EXCEL FLOW] "

                        "NO URL ENRICHMENT REQUIRED"
                    )

                    self.ai_response = False

                    self.excel_url_processing = False

                    self.excel_url_index = 0

                    if not self.completion_email_sent:

                        self.send_completion_email()

                    self.state = "done"

            # =========================================
            # MORE PARSE ROWS REMAIN
            # =========================================

            else:

                _logger.warning(

                    "[EXCEL FLOW] "

                    "RETURN TO excel_parsing"
                )

                self.state = 'excel_parsing'

                _logger.warning(

                    "[EXCEL FLOW] "

                    f"NEXT PARSE INDEX="

                    f"{self.excel_parse_index}"
                )


    # =====================================================
    # CRON PROCESSOR
    # =====================================================
    def run_pending_jobs(self):

        _logger.warning(
            "🔥 CRON HEARTBEAT → RUNNING"
        )


        active_states = [

            'draft',
            'review',

            'excel_parsing',
            'excel_ai',
            'excel_creating',

            'azure_review',
            'azure_crop',
            'azure_fallback',

            'family_a_review',
            'family_a_partial_recovery',

            'pdf_extracting',
            'pdf_ai',
            'pdf_creating',

            'url_scraping',
            'url_ai',
            'url_creating',
            'excel_url_enrichment'
        ]

        STALL_STATES = {

            "pdf_extracting": "PDF extraction stalled",

            "pdf_ai": "PDF AI stalled",

            "pdf_creating": "PDF creation stalled",

            "excel_ai": "Excel AI stalled",

            "excel_creating": "Excel creation stalled",

            "excel_url_enrichment": "Excel URL enrichment stalled",

            "url_scraping": "URL scraping stalled",

            "url_ai": "URL AI stalled",

            "url_creating": "URL creation stalled",

            # =============================================
            # FAMILY A VISUAL QUALITY GATE
            # =============================================

            "family_a_review": "Family A Review",
            "family_a_partial_recovery" : "Family A Partial Recovery",

            # =============================================
            # AZURE VISUAL INTERCEPTION
            # =============================================
            
            "azure_review": "Azure visual review stalled",
            
            "azure_crop": "Azure image cropping stalled",

            "azure_fallback": "Azure Fallback",

            
            "pdf_ai": "PDF AI stalled",
            
            "pdf_creating": "PDF creation stalled",

        }

       


        # =================================================
        # LOAD JOBS
        # =================================================

        jobs = self.search(

            [('state', 'in', active_states)],

            order="id desc"
        )


        _logger.warning(

            f"[CRON] ACTIVE JOBS "

            f"→ {len(jobs)}"
        )


        # =================================================
        # REMOVE DUPLICATES
        # =================================================

        seen = {}

        duplicates = self.env[
            'vendor.import.job'
        ]

        for j in jobs:

            sig = (

                str(j.partner_id.id)

                + "_"

                + str(j.upload_signature)
            )
           
            if not sig:

                continue


            if sig not in seen:

                seen[sig] = j

            else:

                if j.id > seen[sig].id:

                    duplicates |= seen[sig]

                    seen[sig] = j

                else:

                    duplicates |= j


        if duplicates:

            _logger.warning(

                f"[CRON] REMOVING DUPLICATES "

                f"→ {len(duplicates)}"
            )

            try:

                duplicates.unlink()

                self.env.cr.commit()

                _logger.warning(
                    "[CRON] DUPLICATES REMOVED"
                )

            except Exception as e:

                _logger.exception(

                    f"[CRON ERROR] "

                    f"DUPLICATE DELETE FAILED "

                    f"→ {str(e)}"
                )


        # =================================================
        # RECOVER STALE LOCKS
        # =================================================

        stale_jobs = self.search([

            ('state', 'in', active_states),

            ('lock', '=', True)

        ])


        for stale in stale_jobs:

            try:

                delta = (

                    fields.Datetime.now()

                    - stale.write_date

                ).total_seconds()

            except Exception:

                delta = 0


            _logger.warning(

                f"[LOCK CHECK] "

                f"job={stale.id} "

                f"| seconds={delta}"
            )


            if delta > 60:

                _logger.warning(

                    f"[STALE LOCK RESET] "

                    f"job={stale.id}"
                )

                try:

                    stale.lock = False

                    self.env.cr.commit()

                except Exception as e:

                    _logger.exception(

                        f"[STALE LOCK ERROR] "

                        f"{str(e)}"
                    )

        # =================================================
        # CONTINUOUS QUEUE PROCESSOR
        # =================================================

        while True:

        # =================================================
        # GET NEXT JOB
        # =================================================

            job = self.search(

                [

                    ('state', 'in', active_states),

                    ('lock', '=', False)

                ],

                order="create_date asc, id asc",

                limit=1
            )


            if not job:

                _logger.warning(

                    "[CRON] NO AVAILABLE JOBS "
                    "(all locked or done)"
                )

                return


            # =================================================
            # PROCESS
            # =================================================

            try:

                # =============================================
                # LOCK
                # =============================================

                job.lock = True

                self.env.cr.commit()


                _logger.warning(

                    f"[CRON] JOB LOCKED "

                    f"| job={job.id}"
                )


                # =============================================
                # SAFER CHAIN
                # =============================================

                MAX_CHAIN = 1


                for step in range(MAX_CHAIN):

                    # =========================================
                    # REFRESH
                    # =========================================

                    try:

                        job.invalidate_cache()

                    except Exception:

                        pass


                    job = self.env[
                        'vendor.import.job'
                    ].browse(job.id)


                    _logger.warning(

                        f"[CHAIN] STEP "

                        f"{step + 1} "

                        f"| state={job.state}"
                    )


                    # =========================================
                    # STOP STATES
                    # =========================================

                    if job.state == 'done':

                        _logger.warning(

                            f"[CHAIN STOP] "

                            f"terminal state "

                            f"→ {job.state}"
                        )

                        break


                    # =========================================
                    # TRACK BEFORE
                    # =========================================

                    previous_state = (
                        job.state
                    )

                    previous_page = (
                        job.current_page or 0
                    )

                    previous_ai_page = (
                        job.last_ai_page or 0
                    )

                    previous_created = (
                        job.last_created_page or 0
                    )

                    previous_excel_ai = (
                        job.excel_ai_index or 0
                    )

                    previous_excel_created = (
                        job.excel_created_index or 0
                    )

                    previous_excel_url = (
                        job.excel_url_index or 0
                    )
                
                    previous_url_batch = (
                        job.url_batch_index or 0
                    )

                    previous_url_created = (
                        job.last_processed_product_index or 0
                    )
                

                    _logger.warning(

                        f"[CHAIN BEFORE] "

                        f"state={previous_state} "

                        f"| extract={previous_page} "

                        f"| ai={previous_ai_page} "

                        f"| create={previous_created} "

                        f"| excel_ai={previous_excel_ai} "

                        f"| excel_create={previous_excel_created}"
                    )


                    # =========================================
                    # PROCESS
                    # =========================================

                    try:

                        # =========================================
                        # REAL PROCESSING
                        # =========================================

                        job._process_step()

                        # =========================================
                        # SUCCESS RESET
                        # =========================================

                        self.env.cr.commit()

                    except Exception as e:

                        _logger.exception(

                            f"[PROCESS ERROR] "

                            f"job={job.id} "

                            f"| {str(e)}"
                        )

                        # =====================================
                        # INFRASTRUCTURE FAILURE DETECTION
                        # =====================================

                        dead_cursor = any(

                            x in str(e).lower()

                            for x in [

                                "cursor already closed",

                                "connection already closed",

                                "closed cursor",

                                "interfaceerror"
                            ]
                        )

                        # =====================================
                        # DO NOT CONSUME BUSINESS RETRIES
                        # =====================================

                        if dead_cursor:

                            _logger.warning(

                                f"[INFRA FAILURE] "

                                f"job={job.id} "

                                f"| retry preserved"
                            )

                            return

                        try:

                            # =====================================
                            # RETRY TRACKING
                            # =====================================

                            job.stage_retry_count += 1

                            _logger.warning(

                                f"[JOB RETRY] "

                                f"job={job.id} "

                                f"| retry={job.stage_retry_count}/8"
                            )

                            # =====================================
                            # TERMINAL FAILURE
                            # =====================================

                            if job.stage_retry_count >= 8:

                                _logger.error(

                                    f"[JOB FAILED PERMANENTLY] "

                                    f"job={job.id}"
                                )

                                job.state = 'failed'

                                job.failed_at = fields.Datetime.now()

                                job.failure_reason = str(e)

                                self.env.cr.commit()

                                # =================================
                                # FAILED EMAIL NOTIFICATION
                                # =================================

                                try:

                                    _logger.warning(

                                        f"[FAILED EMAIL] "

                                        f"START → job={job.id}"
                                    )

                                    job._send_failed_processing_email(

                                        error_message=str(e)
                                    )

                                    _logger.warning(

                                        f"[FAILED EMAIL] "

                                        f"COMPLETE → job={job.id}"
                                    )

                                except Exception as email_error:

                                    _logger.exception(

                                        f"[FAILED EMAIL ERROR] "

                                        f"{str(email_error)}"
                                    )

                            else:

                                # =================================
                                # RECOVERY STATE
                                # =================================

                                job.state = 'review'

                                self.env.cr.commit()

                        except Exception:

                            _logger.warning(

                                "[PROCESS ERROR] "

                                "FAILED SAVE FAILED"
                            )

                        break

                    # =========================================
                    # REFRESH AFTER
                    # =========================================

                    try:

                        job.invalidate_cache()

                    except Exception:

                        pass


                    job = self.env[
                        'vendor.import.job'
                    ].browse(job.id)


                    _logger.warning(

                        f"[CHAIN AFTER] "

                        f"state={job.state} "

                        f"| extract={job.current_page} "

                        f"| ai={job.last_ai_page} "

                        f"| create={job.last_created_page} "

                        f"| excel_ai={job.excel_ai_index} "

                        f"| excel_create={job.excel_created_index}"
                    )


                    # =========================================
                    # PROGRESS DETECTION
                    # =========================================

                    progress_detected = False


                    # PDF extract progress

                    if (

                        (job.current_page or 0)

                        >

                        previous_page

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        # ===============================
                        # RESET STALL COUNTER
                        # ===============================

                        if job.stage_retry_count:

                            _logger.warning(

                                "[STALL RESET] "

                                f"job={job.id} "

                                f"{job.stage_retry_count} -> 0"

                            )

                            job.stage_retry_count = 0

                        _logger.warning(

                            f"[PROGRESS] PDF "

                            f"{previous_page}"

                            f" → "

                            f"{job.current_page}"
                        )


                    # PDF AI progress

                    if (

                        (job.last_ai_page or 0)

                        >

                        previous_ai_page

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] PDF AI "

                            f"{previous_ai_page}"

                            f" → "

                            f"{job.last_ai_page}"
                        )


                    # PDF create progress

                    if (

                        (job.last_created_page or 0)

                        !=

                        previous_created

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] PDF CREATE "

                            f"{previous_created}"

                            f" → "

                            f"{job.last_created_page}"
                        )


                    # PDF create state continuation

                    elif job.state == 'pdf_creating':

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            "[PROGRESS] PDF CREATE LOOP ACTIVE"
                        )
                

                    # Excel AI progress

                    if (

                        (job.excel_ai_index or 0)

                        >

                        previous_excel_ai

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] EXCEL AI "

                            f"{previous_excel_ai}"

                            f" → "

                            f"{job.excel_ai_index}"
                        )


                    # Excel create progress

                    if (

                        (job.excel_created_index or 0)

                        >

                        previous_excel_created

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] EXCEL CREATE "

                            f"{previous_excel_created}"

                            f" → "

                            f"{job.excel_created_index}"
                        )

                    # Excel URL enrichment progress

                    if (

                        (job.excel_url_index or 0)

                        >

                        previous_excel_url

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] EXCEL URL "

                            f"{previous_excel_url}"

                            f" -> "

                            f"{job.excel_url_index}"
                        )

                    # =========================================
                    # URL AI progress
                    # =========================================

                    if (

                        (job.url_batch_index or 0)

                        >

                        previous_url_batch

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] URL AI "

                            f"{previous_url_batch}"

                            f" → "

                            f"{job.url_batch_index}"
                        )


                    # =========================================
                    # URL create progress
                    # =========================================

                    if (

                        (job.last_processed_product_index or 0)

                        >

                        previous_url_created

                    ):

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] URL CREATE "

                            f"{previous_url_created}"

                            f" → "

                            f"{job.last_processed_product_index}"
                        )


                    # =========================================
                    # APIFY WAIT STATE
                    # =========================================

                    if job.state == 'url_scraping':

                        job._reset_stage_retry()

                        _logger.warning(

                            "[PROGRESS] APIFY WAITING"
                        )
                


                    # state transition

                    if previous_state != job.state:

                        progress_detected = True

                        job._reset_stage_retry()

                        _logger.warning(

                            f"[PROGRESS] STATE "

                            f"{previous_state}"

                            f" → "

                            f"{job.state}"
                        )


                    # =========================================
                    # STOP IF NO PROGRESS
                    # =========================================

                    if not progress_detected:

                        _logger.warning(

                            "[CHAIN STOP] NO PROGRESS DETECTED"

                        )

                        # ==========================================
                        # PDF EXTRACTION STALL
                        # ==========================================

                        if job.state in STALL_STATES:

                            job._handle_stalled_stage(

                                stage_name=job.state,

                                max_retries=8,

                                failure_reason=STALL_STATES[job.state]

                            )

                        break


                    _logger.warning(

                        "[CHAIN CONTINUE] "

                        "PROGRESS DETECTED"
                    )


                    # =========================================
                    # COMMIT
                    # =========================================

                    try:

                        self.env.cr.commit()

                        _logger.warning(
                            "[CHAIN] COMMIT OK"
                        )

                    except Exception as e:

                        _logger.exception(

                            f"[CHAIN COMMIT ERROR] "

                            f"{str(e)}"
                        )

                        break


                _logger.warning(
                    "[CRON] PROCESS LOOP COMPLETE"
                )


            except Exception as e:

                _logger.exception(

                    f"[CRON FATAL ERROR] "

                    f"{str(e)}"
                )


                try:

                    self.env.cr.rollback()

                    _logger.warning(
                        "[CRON] ROLLBACK OK"
                    )

                except Exception:

                    _logger.warning(
                        "[CRON] ROLLBACK FAILED"
                    )


            finally:

                # =============================================
                # UNLOCK
                # =============================================

                try:

                    # =============================================
                    # DEAD CURSOR SAFETY
                    # =============================================

                    if self.env.cr.closed:

                        _logger.warning(

                            "[CRON] SKIP UNLOCK "

                            "CURSOR CLOSED"
                        )

                    else:

                        if (

                            job

                            and

                            job.exists()

                        ):

                            job.lock = False

                            self.env.cr.commit()


                            _logger.warning(

                                f"[CRON] JOB UNLOCKED "

                                f"| job={job.id}"
                            )

                except Exception:

                    _logger.warning(

                        "[CRON] UNLOCK FAILED"
                    )


            _logger.warning(
                "[CRON] RUN COMPLETE"
            )

            break

    # =================================================
    # STALLED STAGE HANDLER
    # =================================================

    def _handle_stalled_stage(

        self,

        stage_name,

        max_retries=10,

        failure_reason=None

    ):

        self.ensure_one()

        failure_reason = (

            failure_reason

            or

            f"{stage_name} stalled"

        )

        self.stage_retry_count += 1

        _logger.warning(

            "[STALL DETECTED] "

            f"job={self.id} "

            f"stage={stage_name} "

            f"retry={self.stage_retry_count}/{max_retries}"

        )

        self.last_error = failure_reason

        # ==========================================
        # TERMINATE
        # ==========================================

        if self.stage_retry_count >= max_retries:

            _logger.error(

                "[STALL TERMINATED] "

                f"job={self.id} "

                f"stage={stage_name}"

            )

            # Preserve the stage that actually failed
            self.last_known_state = stage_name

            self.last_error = failure_reason

            self.failed_at = fields.Datetime.now()

            self.state = "failed"

            self._safe_commit_progress()

            # ==========================================
            # EMAIL VENDOR
            # ==========================================

            try:

                self._send_failed_processing_email(

                    error_message=failure_reason

                )

            except Exception as e:

                _logger.exception(

                    f"[STALL EMAIL FAILED] "

                    f"{str(e)}"

                )

            return

        # ==========================================
        # WAIT FOR NEXT CRON
        # ==========================================

        self._safe_commit_progress()

    
    # =================================================
    # STALLED STAGE HANDLER reset
    # =================================================
    def _reset_stage_retry(self):

        if not self.stage_retry_count:
            return

        _logger.warning(

            "[STALL RESET] "

            f"job={self.id} "

            f"{self.stage_retry_count} -> 0"

        )

        self.stage_retry_count = 0

