    #---------------clean_scraped_blocks------------------------------
    def _clean_scraped_blocks(self, raw_blocks):
        """
        Clean Apify output before sending to AI
        """

        cleaned = []
        seen = set()

        for item in raw_blocks:

            text = (item.get("text") or "").strip()
            image = item.get("image")

            # ❌ REMOVE NOISE
            if not text:
                continue

            if len(text.strip()) < 5:
                continue

            noise = text.lower().strip()

            if noise in [
                "privacy",
                "cookies",
                "cookie",
                "login",
                "menu",
                "home"
            ]:
                continue

            # ❌ REMOVE DUPLICATES
            # allow more variation
            key = (
                text.strip(),
                item.get("image") or ""
            )

            if key in seen:
                continue

            seen.add(key)

            cleaned.append({
                "text": text,
                "image": image,
                "url": item.get("url", ""),
                "price": item.get("price", ""),
                "stock": item.get("stock", "")
            })

        return cleaned

    #---------------normalizer-------------------------------

    def _normalize_url_data(self, items):

        blocks = []

        for item in items:

            # =====================================================
            # FORMAT 1 → ORIGINAL WORKING FORMAT
            # =====================================================
            # {
            #   "text": "...",
            #   "image": "..."
            # }
            # =====================================================

            if item.get("text"):

                text = (item.get("text") or "").strip()
                image = item.get("image")

                # 🔥 STRICT VALIDATION
                if not text or len(text) < 5:
                    continue

                if (
                    image and
                    isinstance(image, str) and
                    not image.startswith("http")
                ):
                    image = None

                blocks.append({
                    "text": text,
                    "image": image,
                    "price": item.get("price", ""),
                    "stock": item.get("stock", "")
                })

                continue

            # =====================================================
            # FORMAT 2 → STRUCTURED FORMAT
            # =====================================================

            if item.get("type") == "PRODUCTS":

                for sub in item.get("items", []):

                    text = (
                        sub.get("text") or ""
                    ).strip()

                    image = sub.get("image")

                    if not text or len(text) < 5:
                        continue

                    if (
                        image and
                        isinstance(image, str) and
                        not image.startswith("http")
                    ):
                        image = None

                    # blocks.append({
                    #     "text": text,
                    #     "image": image
                    # })

                    blocks.append({
                        "text": text,
                        "image": image,
                        "price": sub.get("price", ""),
                        "stock": sub.get("stock", "")
                    })

            # =====================================================
            # DEBUG TYPES
            # =====================================================

            elif item.get("type") in [
                "EMPTY",
                "BLOCKED"
            ]:

                _logger.error(
                    f"URL DEBUG → "
                    f"{item.get('reason')}"
                )
            
            # =====================================================
            # FORMAT 3 → NEW STRUCTURED PRODUCT
            # =====================================================

            elif (

                item.get("semanticType") == "PRODUCT"

                or item.get("title")

                or item.get("url")

            ):

                image = item.get("image")

                if (
                    image
                    and isinstance(image, str)
                    and not image.startswith("http")
                ):
                    image = None

                title = str(
                    item.get("title") or ""
                ).strip()

                description = str(
                    item.get("description") or ""
                ).strip()

                raw_text = str(
                    item.get("rawText") or ""
                ).strip()

                # --------------------------------------
                # Build AI text
                # --------------------------------------

                text = "\n\n".join(

                    x for x in [

                        title,

                        description,

                        raw_text

                    ]

                    if x

                )

                if len(text) < 5:

                    continue

                blocks.append({

                    "text": text,

                    "title": title,

                    "sku": item.get("sku"),

                    "description": description,

                    "price": item.get("price", ""),

                    "currency": item.get("currency", ""),

                    "stock": item.get("stock", ""),

                    "url": item.get("url", ""),

                    "image": image,

                    "brand": item.get("brand", ""),

                    "rating": item.get("rating", ""),

                    "rawText": raw_text,

                })

        _logger.warning(f"NORMALIZED BLOCKS → {len(blocks)}")

        # =====================================================
        # 🔥 SPLIT INTO MULTIPLE PAGES (CRITICAL FIX)
        # =====================================================

        PAGE_SIZE = 15  # 🔥 prevents AI overload

        pages = []

        for i in range(0, len(blocks), PAGE_SIZE):

            chunk = blocks[i:i + PAGE_SIZE]

            pages.append({
                "page": len(pages) + 1,
                "blocks": chunk
            })

        _logger.warning(f"NORMALIZED PAGES → {len(pages)}")

        return pages
    
    #=======validation===================
    def validate_ai_output(products):
        for p in products:
            if "variants" in p:
                if not isinstance(p["variants"], list):
                    p["variants"] = []

                for v in p["variants"]:
                    if "attributes" not in v:
                        v["attributes"] = {"Variant": "Default"}

        return products
    
