    #========bukl price update==================
    def action_apply(self):

        products = self.env[
            'product.template'
        ].browse(
            self.env.context.get(
                'active_ids',
                []
            )
        )

        for product in products:

            current_price = product.list_price

            if self.update_type == 'fixed':

                if self.operation == 'set':
                    new_price = self.value

                elif self.operation == 'increase':
                    new_price = (
                        current_price +
                        self.value
                    )

                else:
                    new_price = (
                        current_price -
                        self.value
                    )

            else:

                if self.operation == 'increase':
                    new_price = (
                        current_price *
                        (
                            1 +
                            self.value / 100
                        )
                    )

                else:
                    new_price = (
                        current_price *
                        (
                            1 -
                            self.value / 100
                        )
                    )

            product.list_price = max(
                0,
                new_price
            )

    def _get_or_create_family_id(self, product):

        if product.vendor_family_id:
            return product.vendor_family_id

        family_id = self.env[
            "ir.sequence"
        ].next_by_code(
            "vendor.import.family"
        )
        if not family_id:
            raise Exception(
                "Sequence 'vendor.import.family' was not found."
            )

        product.vendor_family_id = family_id
        product.flush_recordset()

        _logger.warning(

            "[FAMILY GENERATED] "

            f"product={product.id} "

            f"family={family_id}"

        )

        return family_id
    
