    def _map_product_category(

        self,

        raw_category

    ):

        CATEGORY_MAPPING = {

            "t-shirt": "Apparel",
            "shirt": "Apparel",
            "polo": "Apparel",

            "bag": "Bags",
            "backpack": "Bags",

            "cap": "Headwear",
            "hat": "Headwear",

            "bottle": "Drinkware",
            "drinkware": "Drinkware",
            "sports bottle": "Drinkware",

            "pen": "Stationery",
            "notebook": "Stationery",

            "powerbank": "Electronics",
            "charger": "Electronics",
            "laptop": "Electronics",

            "football": "Football Fever",
            "wristband": "Football Fever",
            "sports towel": "Football Fever",
            "sports t-shirt": "Football Fever",

        }

        raw = " ".join(

            str(raw_category or "").lower().split()

        )

        for key, value in CATEGORY_MAPPING.items():

            if key in raw:

                return value

        return "General"

    # =====================================================
    # CATEGORY MANAGER
    # =====================================================

    def _get_or_create_product_category(

        self,

        category_name,

        source="unknown"

    ):


        category_name = " ".join(

            str(category_name).split()

        ).strip()

        # ============================
        # CACHE
        # ============================

        category_obj = self.env["product.category"]

        # ============================
        # ROOT
        # ============================

        parent = category_obj.search([

            ("name", "=", "All Products"),

            ("parent_id", "=", False)

        ], limit=1)

        if not parent:

            _logger.warning(

                "[CATEGORY ROOT CREATE]"

            )

            parent = category_obj.create({

                "name": "All Products"

            })

        # ============================
        # SEARCH ALL
        # ============================

        matches = category_obj.search([

            ("parent_id", "=", parent.id),

            ("name", "=ilike", category_name)

        ])

        if matches:

            if len(matches) > 1:

                _logger.warning(

                    "[CATEGORY DUPLICATE] "

                    f"source={source} "

                    f"name={category_name} "

                    f"ids={matches.ids}"

                )

            category = matches.sorted(

                "id"

            )[0]

            return category

        _logger.warning(

            "[CATEGORY CREATE] "

            f"source={source} "

            f"name={category_name}"

        )

        category = category_obj.create({

            "name": category_name,

            "parent_id": parent.id

        })

        return category


    # ==========================================================
    # RESOLVE CATALOGUE CURRENCY
    # ==========================================================

    def _resolve_catalogue_currency(

        self,

        extracted_currency=None,

        price_text=None,

    ):

        """
        Resolve the source currency for the
        imported catalogue.

        Priority:

            1. Explicit currency code

            2. Currency symbol

            3. Default USD
        """

        Currency = self.env["res.currency"]

        default_currency = Currency.search(

            [

                ("name", "=", "USD")

            ],

            limit=1,

        )

        #
        # Explicit code
        #

        if extracted_currency:

            currency = Currency.search(

                [

                    ("name", "=", extracted_currency.upper())

                ],

                limit=1,

            )

            if currency:

                return currency

        #
        # Detect symbol
        #

        if price_text:

            symbol_map = {

                "$": "USD",

                "€": "EUR",

                "£": "GBP",

                "₺": "TRY",

                "¥": "JPY",

                "AED": "AED",

            }

            for symbol, code in symbol_map.items():

                if symbol in price_text:

                    return Currency.search(

                        [

                            ("name", "=", code)

                        ],

                        limit=1,

                    )

        #
        # Default
        #

        return default_currency

    